function crewFull(j,c){
  if(hasName(j))return (jobName(j)+(c.title?' '+c.title:'')).trim();
  var s=siteText(j)||'',t=String(c.title||'').trim();
  return (s&&t?(t.toUpperCase().indexOf(s.toUpperCase())===0?t:s+' '+t):(t||s))||'Untitled job';
}
