  for(var j=0;j<P.length;j++){var q=P[j],by2='';if(em2&&pdNorm(q.email)===em2)by2='email';else if(nm2&&pdNorm(q.name)===nm2)by2='name';if(by2)return {coll:'ert',id:q.id,name:q.name,by:by2}}
