function pdNameDecide(kind,x){var I=pdNameInfo(kind,x);if(!I||!I.can)return null;var el=document.getElementById('pd-nm'),v=String((el?el.value:(S.updRev&&S.updRev.vals&&S.updRev.vals.__name))||'').trim();if(!v||pdNorm(v)===pdNorm(I.cur))return null;var both=document.getElementById('pd-nm-both');return {val:v,also:(I.also&&(!both||both.checked))?I.also:null}}
