  var dpe=S.dpf||dpQ,dpHid=0,dsel=$('#dp-f');
  if(dsel){var want=dpOpts(S.dpf);if(dsel.dataset.sig!==want){dsel.innerHTML=want;dsel.dataset.sig=want}dsel.value=S.dpf||'';var dl=dsel.closest('.rfsel');if(dl)dl.classList.toggle('on',!!S.dpf)}
  if(q)ppl=ppl.filter(function(p){return v589Hit(p,q)});
  if(dpe){var hv=ppl.filter(function(p){return dpClasses(p).indexOf(dpe)>-1});dpHid=hv.filter(function(p){return !dpValid(p)}).length;ppl=hv.filter(dpValid)}
  /* 3.42 role quick filter */
  var rolef=S.rolef||'',rsel=$('#role-f'),rbase=ppl;
