function bgName(p){p=String(p||'');var i=p.indexOf('/');if(i<0)return p||'a save';var c=p.slice(0,i).toLowerCase(),id=p.slice(i+1),M={access:'Access record for ',staff:'Staff record ',ert:'ERT profile ',leavereq:'Leave request ',profreq:'Profile update request ',jobletter:'Job letter request ',staffleave:'Staff leave record ',refindex:'Reference list entry ',ertlink:'ERT sign-in link ',stafflink:'Staff sign-in link '};return M[c]?M[c]+id:p}
