function accLevel(a){return a.role==='edit'||a.role==='view'?'staff':a.role}
function accVO(a){return a.role==='view'||(accLevel(a)==='staff'&&a.viewOnly===true)}
function accLevelsHtml(){return '<details class="card acclev"><summary><h3>What each level can do</h3></summary><div class="acclevbody">'+
  '<div class="acclv"><b>Executive</b><span>Sees and does everything in every department: access and permissions, positions, departments, leave, History, rates, backups and restore.</span></div>'+
  '<div class="acclv"><b>Director</b><span>Sees everything in every department, including leave and History. Changes and approves nothing.</span></div>'+
  '<div class="acclv"><b>Admin</b><span>Full access to the work in every department, manages leave and sees History. Gives access to Staff and Department Admins. Executives tick extra permissions for each Admin:</span><span class="accptags">'+ACC_PERMS.map(function(x){return '<i>'+esc(x[1])+'</i>'}).join('')+'</span></div>'+
  '<div class="acclv"><b>Department Admin</b><span>Full access in the departments they run (including leave and History for those departments, if the department includes them); normal staff work in any other department they belong to; nothing elsewhere.</span></div>'+
  '<div class="acclv"><b>Staff</b><span>Works in the tabs of their departments: jobs and crews, ER Log tickets, crew confirmations and more. Can view leave if a department of theirs includes Leave. Set <b>View only</b> for someone who should look but not change anything.</span></div>'+
  '<div class="acclv"><b>ERT accounts</b><span>Field personnel see only their own information in the ERT view, never the office pages.</span></div></div></details>'}
function accRoles(){accLblFix();return S.isOwner?['staff','dadmin','admin','director','exec']:S.isExec?['staff','dadmin','admin','director']:['staff','dadmin']}
function accGrants(a){
  if(!S.isExec)return '';
  if(a.role==='exec')return 'Proposals and Staff Members';
  var g=[];
  if(a.proposals&&a.proposals!=='none')g.push('Proposals: '+ACC_GR[a.proposals].toLowerCase());
  if(a.staff&&a.staff!=='none')g.push('Staff Members: '+ACC_GR[a.staff].toLowerCase());
  if(a.role==='admin'&&a.hours===true)g.push('Correct work hours');
  return g.join(' \u2022 ');
}
function accR(a){return ((a.role==='exec'||a.role==='owner'||(a.role==='admin'&&a.rates===true))?'<b class="accd accr" title="Can edit Rates" aria-label="Can edit Rates">R</b>':'')+accH(a)}
function accH(a){return (a.role==='admin'&&a.hours===true)?'<b class="accd acch" title="Can correct work hours" aria-label="Can correct work hours">H</b>':''}
function accDActive(a){return a.role==='exec'||a.role==='owner'||(a.role==='admin'&&a.download===true&&(!a.downloadUntil||String(a.downloadUntil)>=iso(TODAY)))}
function accD(a){return accDActive(a)?'<b class="accd" title="Can download files'+(a.role==='admin'&&a.downloadUntil?' until '+fmt(a.downloadUntil):'')+'" aria-label="Can download files">D</b>':''}
function accSel(attr,e,label,cur){
  return '<div class="accf"><label>'+label+'</label><select '+attr+'="'+e+'" aria-label="'+label+' for '+e+'">'+['none','view','edit'].map(function(v){return '<option value="'+v+'"'+(cur===v?' selected':'')+'>'+ACC_GR[v]+'</option>'}).join('')+'</select></div>';
}
function accSay(t){S.accMsg=t;var el=$('#acc-msg');if(el)el.textContent=t}
async function accMigrate(){if(S.accMigBusy||!(S.isExec||S.isOwner)||!S.db)return;var todo=(S.access||[]).filter(function(a){return a.role==='edit'||a.role==='view'||(a.role==='admin'&&a.permsSet!==true)});if(!todo.length)return;S.accMigBusy=true;var n=0;
  for(var a of todo){try{var d=Object.assign({},a);if(a.role==='edit'){d.role='staff'}else if(a.role==='view'){d.role='staff';d.viewOnly=true}else{ACC_PERMS.forEach(function(x){if(x[0].charAt(0)==='p')d[x[0]]=true});d.permsSet=true}
    if(!S.isOwner&&a.role==='exec')continue;await S.db.doc('access/'+a.email).set(d);n++}catch(e){}}
  S.accMigBusy=false;if(n)toast('Access updated to the new levels for '+n+(n===1?' person':' people'))}
async function accInvite(email,role){
  accSay('Adding '+email+'...');
  var res;
  try{res=await window.HHSL_invite(email)}catch(e){accSay(inviteError(e));return}
  var sp=(role==='exec'||role==='owner')?{}:(S.accAddSec?{sections:[S.accAddSec]}:{needSection:true});S.accAddSec='';
  if(role==='staffvo')await accSet(email,'staff',Object.assign({viewOnly:true},sp));else await accSet(email,role,sp);
  accSay(res.created?'Added '+email+'. A sign-in email is on its way. They open it, set a password, then sign in. Use Share invite message above to send them the app link.':email+' already had an account, so it was added and a sign-in email was sent. Use Share invite message above to send them the app link.');
}
async function accResend(email){
  accSay('Sending to '+email+'...');
  try{await window.HHSL_invite(email);accSay('A sign-in email was sent to '+email+'.')}catch(e){accSay(inviteError(e))}
}
async function accSetRaw(email,role,patch){
  if(!S.isAdmin||!S.db)return false;
  var cur=(S.access||[]).filter(function(x){return x.email===email})[0]||{};
  var d=Object.assign({},cur,{email:email,role:role});
  if(!d.added)d.added=new Date().toISOString();
  if(patch)Object.assign(d,patch);
  if(role==='edit')role=d.role='staff';if(role==='view'){role=d.role='staff';d.viewOnly=true}
  if(role==='exec'||!d.proposals||d.proposals==='none')delete d.proposals;
  if(role==='exec'||!d.staff||d.staff==='none')delete d.staff;
  if(role!=='admin'||d.download!==true){delete d.download;delete d.downloadUntil}
  if(role!=='admin'||d.rates!==true)delete d.rates;
  if(role!=='admin'||d.hours!==true)delete d.hours;
  ACC_PERMS.forEach(function(x){if(x[0].charAt(0)==='p'&&x[0]!=='pPay'&&(role!=='admin'||d[x[0]]!==true))delete d[x[0]]});
  if(role!=='admin')delete d.permsSet;
  if(role!=='staff'||d.viewOnly!==true)delete d.viewOnly;
  try{await S.db.doc('access/'+email).set(d);return true}catch(e){toast('Could not save. Try again.');return false}
}
/* ===== access (more, placed by who calls them) (function declarations only, moved here in V4.62; the order of these functions does not matter) ===== */
async function saveFields(){
  if(!S.db)return false;
  try{await S.db.doc('config/fields').set(Object.assign({certs:CERTS.slice(),orient:ORIENT.slice(),med:MED.map(function(x){return {k:x[0],l:x[1]}}),unmon:Object.keys(S.unmon),lbl:Object.keys(S.lbl).map(function(k){return {k:k,l:S.lbl[k]}}),sub:Object.keys(S.sub).map(function(k){return {k:k,p:S.sub[k]}})},Array.isArray(S.ownRate)?{ownRate:S.ownRate.slice()}:{}));flashSaved();return true}
  catch(e){toast(e&&e.code==='invalid_argument'?'You do not have permission to change settings':'Could not save the settings. Try again.');return false}
}
function flashSaved(){
  if(!S.set)return;var bar=document.querySelector('#set-in .sheet-bar');if(!bar)return;
  var p=bar.querySelector('.setsaved');if(!p){p=document.createElement('span');p.className='setsaved';p.setAttribute('role','status');var done=bar.querySelector('[data-act="set-close"]:last-child');bar.insertBefore(p,done||null)}
  p.textContent='\u2713 Saved';p.classList.remove('show');void p.offsetWidth;p.classList.add('show');
  clearTimeout(S.savedT);S.savedT=setTimeout(function(){var q=document.querySelector('#set-in .setsaved');if(q)q.classList.remove('show')},2200);
}
function setGroup(title,rows){rows=rows.filter(Boolean);return rows.length?'<div class="setgl">'+esc(title)+'</div><div class="setmenu">'+rows.join('')+'</div>':''}
function themeAutoNow(){try{return window.matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'}catch(e){return 'light'}}
function setTheme(m){ S.theme=(m==='light'||m==='dark')?m:'auto'; var r=document.documentElement; r.setAttribute('data-theme',S.theme==='auto'?themeAutoNow():S.theme);
  try{localStorage.setItem('ert_theme',S.theme)}catch(e){}
  if(S.set&&S.setPage==='appearance')flashSaved();
  [].forEach.call(document.querySelectorAll('[data-act="theme"]'),function(b){b.setAttribute('aria-pressed',b.dataset.val===S.theme?'true':'false')});
}
async function persistReps(){
  if(!S.db||!S.canWrite)return;
  try{await S.db.doc('config/reps').set({sites:Object.keys(S.reps).filter(function(k){return S.reps[k].length}).map(function(k){return {c:k,r:S.reps[k].map(function(r){return r.p?{n:r.n,p:r.p}:{n:r.n}})}})});flashSaved()}catch(e){}
}
function splitRepNames(n){return String(n||'').split(/\s*(?:\/|&|\+|,|\band\b)\s*/i).map(function(s){return s.trim().replace(/\s+/g,' ')}).filter(function(s){return s.length>1})}
function saveRep(client,name,phone){
  var k=repKey(client),names=splitRepNames(name);phone=String(phone||'').trim();
  if(!k||!names.length||!S.canWrite||!S.db)return;
  if(names.length>1)phone='';
  ensureRateSiteForLocation(k,false);
  var list=(S.reps[k]||[]).slice(),changed=false;
  names.forEach(function(nm){
    var lc=nm.toLowerCase(),ex=list.filter(function(r){return r.n.toLowerCase()===lc})[0];
    if(ex){
      if(phone&&ex.p!==phone){ex.p=phone;changed=true}
      if(ex.n===ex.n.toUpperCase()&&nm!==nm.toUpperCase()){ex.n=nm;changed=true}
    }else{list.push({n:nm,p:phone});changed=true}
  });
  if(!changed)return;
  S.reps[k]=list;persistReps();
}
function splitSavedReps(){
  if(!S.canWrite||!S.db||S.repSplitDone)return;S.repSplitDone=true;var changed=false;
  Object.keys(S.reps||{}).forEach(function(k){
    var out=[];
    var src=S.reps[k]||[],multi=src.filter(function(r){return splitRepNames(r.n).length>1});
    src.filter(function(r){return multi.indexOf(r)<0}).forEach(function(r){var ex=out.filter(function(o){return o.n.toLowerCase()===r.n.toLowerCase()})[0];if(!ex)out.push(r);else if(!ex.p&&r.p)ex.p=r.p});
    multi.forEach(function(r){changed=true;splitRepNames(r.n).forEach(function(n){if(!out.some(function(o){return o.n.toLowerCase()===n.toLowerCase()}))out.push({n:n,p:''})})});
    S.reps[k]=out;
  });
  if(changed)persistReps();
}
