function appLink(){return location.origin+location.pathname.replace(/index\.html$/,'')}
function appInviteText(){return 'You have been given access to HHSL Command, the HHSL Safety Systems Limited app.\n\n1. Check your email (and the spam folder) for our message and tap the link to create your HHSL Command password. This password is only for the app; your email address and email password do not change.\n2. Open the app: '+appLink()+'\n3. Sign in with your email and the new password, then choose the name others will see.\n\nTip: add it to your home screen. Android (Chrome): menu \u22EE then Add to Home screen. iPhone (Safari): Share then Add to Home Screen.'}
function appLinkCard(){return '<div class="card" id="sec-applink"><h3>App link</h3><div class="applink"><code>'+esc(appLink())+'</code></div><div class="alinkacts"><button class="mini" data-act="acc-share">Share invite</button><button class="mini" data-act="acc-wa">WhatsApp</button><button class="mini" data-act="acc-copy">Copy link</button></div>'+(S.shareMenu?'<div class="alinkacts sharemenu"><span class="was" style="flex:1 1 100%">Send the invite by:</span><button class="mini" data-act="acc-gmail">Gmail</button><button class="mini" data-act="acc-mail">Outlook or email app</button><button class="mini" data-act="acc-copymsg">Copy message</button>':'')+'</div><div class="was" style="padding:0 14px 10px">Send the invite message to people you add. It tells them where the app is and how to install it.</div></div>'}
function inviteError(e){
  var c=e&&e.code;
  if(c==='auth/operation-not-allowed'||c==='auth/admin-restricted-operation')return 'New accounts are switched off in Firebase. In Firebase open Authentication, Settings, User actions and tick Enable create (sign-up). Then try again.';
  if(c==='auth/invalid-email')return 'That email address is not valid.';
  if(c==='auth/network-request-failed')return 'No connection. Check your signal and try again.';
  if(c==='auth/too-many-requests')return 'Too many tries. Wait a few minutes and try again.';
  return 'Could not send the invite. Try again.';
}
function inactiveRateClient(name){var u=String(name||'').trim().toUpperCase();var f=S.erc.clients.filter(function(c){return c.active===false&&String(c.n).toUpperCase()===u})[0];if(f)return f;if(S.erc.clients.some(function(c){return c.active!==false&&String(c.n).toUpperCase()===u}))return null;var l=linkedRateClient(u);return l&&l.active===false?l:null}
async function ensureRateSiteForLocation(name,notify,lid){
  var u=rateNorm(name);if(!u||u==='ANY SITE'||!S.canRates||!S.db||!S.ercLoaded)return 'skipped';
  var fl=lid?rateLocations().filter(function(x){return x.id===lid})[0]:placeByName(u);if(fl&&fl.kind==='p'&&placeFollows(fl)){if(notify)toast(fl.label+' uses '+fl.parent+'\u2019s rates. Use Give own rate beside it if it needs different pay.');return 'follows'}
  if(!S.erc.links)S.erc.links={};
  if(lid){
    var st=locRateStatus({id:lid,name:u,alt:''});
    if(st.st==='disabled'){if(notify)toast(u+' has Rates disabled. Use Enable Rates beside it if it needs a Rates setup.');return 'disabled'}
    if(st.c){var had=S.erc.links[lid];if(had!==st.c.id){S.erc.links[lid]=st.c.id;if(!(await saveErc())){if(had)S.erc.links[lid]=had;else delete S.erc.links[lid]}}
      if(st.st==='inactive'){if(notify)toast(st.c.n+' is inactive in Rates. Tap Restore beside it to use its saved settings again.');return 'inactive'}return 'existing'}
  }else{
    if(activeRateClient(u))return 'existing';
    if(inactiveRateClient(u))return 'inactive';
    if(disabledRateSite(u))return 'disabled';
  }
  var c=newDefaultRateSite(u);
  S.erc.clients.push(c);if(lid)S.erc.links[lid]=c.id;var saved=await saveErc();
  if(!saved){S.erc.clients=S.erc.clients.filter(function(x){return x!==c});if(lid&&S.erc.links[lid]===c.id)delete S.erc.links[lid];return 'failed'}
  if(notify)toast(u+' added to Rates with defaults, Standard overtime, 1-hour lunch and 5-hour minimum pay');return 'created';
}
