function lvWords(n){var w=['zero','one','two','three','four','five','six','seven','eight','nine','ten','eleven','twelve','thirteen','fourteen','fifteen','sixteen','seventeen','eighteen','nineteen','twenty'];return (n>=0&&n<=20&&n===Math.floor(n)?w[n]+' ('+n+')':String(n))}
