  try{S.db.doc('stafflink/'+em).onSnapshot(function(d){S.lvLink=d.exists?d.data():null;S.lvLinkLoaded=true;if(S.lvLink&&S.lvLink.staffId)lvLoadMine();lvRefresh()},function(){S.lvLinkLoaded=true;lvRefresh()})}catch(e){}
