function lvEntOf(d,set,sid,type){var k=type==='vac'?'vac':'sick',K=k==='vac'?'Vac':'Sick';d=d||{};set=set||{};var own=lvNum(set.vsOwn&&set.vsOwn[sid]!==undefined?(set.vsOwn[sid]||{})[k]:d['leave'+K]);if(own!=null)return own;var rk=d.rank&&set.ranks?set.ranks[d.rank]:null;if(rk&&lvNum(rk[k])!=null)return lvNum(rk[k]);var df=set.defaults||{},dv=lvNum(df[k]),ex=df['ex'+K]||[];if(dv!=null&&ex.indexOf(sid)<0)return dv;return null}
