  if(F.mode==='start')return '<div class="card"><h3>Start sick leave</h3><div class="none">Tell the office you are on sick leave today. You complete it with Return to work when you are back.</div><div class="f"><label for="lv-start">First day sick</label><input id="lv-start" type="date" data-lv="start" value="'+esc(f.start||iso(TODAY))+'"></div><div class="f"><label for="lv-phone">Phone while on sick leave</label><input id="lv-phone" type="tel" inputmode="tel" data-lv="phone" value="'+esc(f.phone)+'"></div><div class="f"><label>What are you sick with? (optional, private)</label><div class="lvchips">'+LV_ILL.map(function(x){return '<button type="button" class="chip" data-act="lv-ill" data-v="'+esc(x)+'" aria-pressed="'+(f.illness===x)+'">'+esc(x)+'</button>'}).join('')+'</div></div>'+(F.err?'<div class="lverr" role="alert">'+esc(F.err)+'</div>':'')+'<div class="actions"><button class="btn ghost" data-act="lv-cancel">Cancel</button><button class="btn" data-act="lv-send"'+(F.busy?' disabled':'')+'>'+(F.busy?'Sending\u2026':'Tell the office')+'</button></div></div>';
  var days=v529W(f.type,function(){return lvDays(f.start,f.end)}),ret=isDate(f.end)?lvNextWork(f.end):'',b=lvMyBal(f.type),after=b.ent==null?null:b.left-days,notice='';
