    B.push({t:'rp',runs:[[(r.ongoing||!r.end?'I am absent due to ':'I was absent due to ')+v523Phrase(r.illness)+'.'+(r.certId?' I was seen by a doctor, and the ':r.doctor==='yes'?' I was seen by a doctor.':'')]].concat(r.certId?[['medical certificate is attached',1],['.']]:[])});
