  B.push({t:'p',x:r.name+(r.sig?'\nSigned electronically, '+lvShort(String(r.at||r.updated||'').slice(0,10))+', '+String(r.at||r.updated||'').slice(11,16)+' UTC':''),sz:9.5});
  var dec=r.status==='approved'?'APPROVED':r.status==='recorded'?'RECORDED':r.status==='declined'?'DECLINED':'WAITING FOR APPROVAL',tone=(r.status==='approved'||r.status==='recorded')?'ok':r.status==='declined'?'no':'';
  var asig=null;if(r.decSig){try{asig=await pLoadImg(r.decSig)}catch(e){}}
