  (S.payNotes||[]).forEach(function(n){var t=Date.parse(n.at||'');if(t>Date.now()-14*864e5)act.push({k:'pyn:'+n.id,t:t,ic:'leave',title:n.text,sub:'Payroll',go:'me',id:n.id})});(S.payPulls||[]).forEach(function(p){var t=Date.parse(p.at||'');if(t>Date.now()-14*864e5)act.push({k:'pyp:'+p.id,t:t,ic:'leave',title:payMon(p.ym)+' is ready: '+p.ertCount+(p.ertCount===1?' ERT, ':' ERTs, ')+p.dayCount+(p.dayCount===1?' day':' days'),sub:'Payroll',go:'payroll',id:p.id})});(S.lvMy||[]).forEach(function(r){var t=Date.parse(r.decidedAt||'');if(!(t>Date.now()-14*864e5)||r.status==='cancelled')return;var w=lvTypeName(r.type).toLowerCase()+' '+lvShort(r.start)+(r.end&&r.end!==r.start?' \u2013 '+lvShort(r.end):'');act.push({k:'lvd:'+r.id+':'+r.status,t:t,ic:'leave',title:'Your '+w+(r.status==='approved'?' was approved':r.status==='recorded'?' was recorded':r.status==='declined'?' was declined':r.status==='changes'?' needs changes':r.status==='cancelled'?' was cancelled':r.status==='cancelask'?' has a cancellation waiting':''),sub:r.status==='declined'?r.declineReason||'':r.status==='changes'?r.changesNote||'':(r.ref||''),go:'me',id:r.id})});
