  if(rows.length)h+=rows.map(function(x){return '<div class="lvovr"><span class="lvovd" style="background:'+col(x.type)+'" aria-hidden="true"></span><span class="lvovm"><b>'+esc(x.name)+'</b><small><span class="lvovt" style="color:'+col(x.type)+'">'+nm(x.type)+'</span> \u2022 '+esc(sd(x.start,x.end))+(x.days?' \u2022 '+x.days+(x.days===1?' day':' days'):'')+'</small></span><span class="lvovs2'+(x.st==='Waiting'?' w':'')+'">'+esc(x.st)+'</span></div>'}).join('');
