  rows.sort(function(a,b){return String(a.s).localeCompare(String(b.s))});
  var nm=function(tp){return tp==='vac'?'Vacation':tp==='sick'?'Sick':'Casual'},col=function(tp){return (typeof LV_COL!=='undefined'&&LV_COL[tp==='vac'||tp==='sick'?tp:'other'])||'#7a6a55'};
  var h='<div class="card mpnow"><h3>Your requests</h3>';
