function overlaps(a,b){
  if(!isDate(a.start)||!isDate(b.start))return false;
  var ae=isDate(a.end)?a.end:a.start,be=isDate(b.end)?b.end:b.start;
  return a.start<=be&&b.start<=ae;
}
