function crewCmp(c){return function(a,b){if(c.lead===a.id)return c.lead===b.id?0:-1;if(c.lead===b.id)return 1;return roleBucket(c,a.id)-roleBucket(c,b.id)||roleRank(a)-roleRank(b)||a.name.localeCompare(b.name)}}
