function jobNos(j){var o=[];(j&&j.crews||[]).forEach(function(c){var n=crewNo(j,c);if(n&&o.indexOf(n)<0)o.push(n)});return o.sort(function(a,b){return a-b})}
function jobRef(j){if(!j)return '';if(j.crews){var ns=jobNos(j);return ns.length?'JOB #'+ns.join(', #'):''}return j.jobNo?'JOB #'+j.jobNo:''}
function crewCount(job,shift){return job.crews.filter(function(c){return c.shift===shift}).length}
function crewNum(job,c){var n=0;for(var i=0;i<job.crews.length;i++){if(job.crews[i].shift===c.shift)n++;if(job.crews[i].id===c.id)break}return n}
function crewLabel(job,c){return crewCount(job,c.shift)>1?'Crew '+crewNum(job,c):c.shift+' shift'}
function jobLog(j){
  var t=(S.erlog||[]).concat(S.erarchive||[]).filter(function(x){return x.jobId===j.id}),exp=0;
  j.crews.forEach(function(c){if(c.members.length&&c.kind!=='medic')exp+=crewDays(j,c).length});
  var signed=t.filter(function(x){return x.status==='SIGNED'}).length;
  return {n:t.length,exp:exp,signed:signed,allSigned:exp>0&&signed>=exp};
}
function jobFinishReady(j){
  var crews=(j.crews||[]).filter(function(c){return (c.members||[]).length});
  return crews.length>0&&crews.every(function(c){return !!c.endTime});
}
function jobState(j){
  var t=iso(TODAY);
  if(j.done&&jobLog(j).allSigned)return 'signed';
  if(j.done&&jobFinishReady(j))return 'unlogged';
  if(j.end&&j.end<t)return 'overdue';
  return 'todo';
}
function bdPersonHtml(start,end){
  var pid=S.bdPerson;if(!pid)return '';var p=S.people.filter(function(x){return x.id===pid})[0];if(!p)return '';
  var rows=[];S.jobs.forEach(function(j){(j.crews||[]).forEach(function(c){if((c.members||[]).indexOf(pid)<0)return;crewDaysOf(j,c,pid).forEach(function(k){if(k>=start&&k<=end)rows.push({k:k,j:j,c:c})})})});
  rows.sort(function(a,b){return a.k.localeCompare(b.k)||(a.c.shift==='Day'?-1:1)});
  var per={};rows.forEach(function(r){per[r.k]=(per[r.k]||0)+1});
  return '<div class="card bdpc" id="bd-pcard"><h3>'+esc(p.name)+'</h3><div class="none">'+(rows.length?rows.length+(rows.length===1?' shift':' shifts'):'No shifts')+' from '+esc(fmt(start))+' to '+esc(fmt(end))+', all locations</div>'+
    rows.map(function(r){return '<button class="bdprow" data-act="openjob" data-jid="'+esc(r.j.id)+'"><b>'+esc(shortDay(r.k))+'</b><span>'+esc(crewFull(r.j,r.c))+' \u2022 '+esc(crewLong(r.j,r.c))+(r.c.startTime?' \u2022 '+esc(time12(r.c.startTime)):'')+'</span>'+(per[r.k]>1?'<em>Double-booked</em>':'')+'</button>'}).join('')+
    '<div class="actions"><button class="btn ghost" data-id="'+esc(pid)+'">Open profile</button><button class="btn ghost" data-act="bd-person-close">Close</button></div></div>';
}
function jobDayMap(){
  var m={};
  S.jobs.forEach(function(j){if(!isDate(j.start))return;var ds=jobDays(j);(j.crews||[]).forEach(function(c){(c.members||[]).forEach(function(pid){crewDaysOf(j,c,pid).forEach(function(d){if(ds.indexOf(d)<0)return;var x=m[d]=m[d]||{};(x[pid]=x[pid]||[]).push({job:j,c:c})})})})});
  return m;
}
function jobChecks(j,map,byId){
  var badges=[],lines=[];
  if(!j||j.done)return {badges:badges,lines:lines};
  map=map||jobDayMap();
  if(!byId){byId={};S.people.forEach(function(p){byId[p.id]=p})}
  var crews=j.crews||[],short=0,noLead=0,noVeh=0,noPh=0;
  function tag(c){return crewLong(j,c)}
  crews.forEach(function(c){
    var n=+c.need||0,m=(c.members||[]).length;
    if(n>m){short+=n-m;lines.push({k:'short',t:tag(c)+': '+(n-m)+' short ('+m+' of '+n+' people)'})}
    if(c.kind==='medic'||c.kind==='offshore')return;
    if(m&&!c.lead){noLead++;lines.push({k:'lead',t:tag(c)+': no team lead'})}
    if(m&&S.vehicles.length&&!(c.vehicles||[]).length&&!crews.some(function(x){return (x.vehicles||[]).length})){noVeh++;lines.push({k:'veh',t:tag(c)+': no vehicle'})}
    if(!String(c.repPhone||'').trim()){noPh++;lines.push({k:'phone',t:tag(c)+': no client rep phone'})}
  });
  var vseen={};
  crews.forEach(function(c){(c.vehicles||[]).forEach(function(vid){var cf=vehConflicts(vid,j,c);if(!cf.length)return;var v=vehById(vid);vseen[vid]=1;lines.push({k:'vdbl',t:crewLong(j,c)+': '+(v?v.name:'Vehicle')+' is also on '+cf.join(', ')})})});
  var dbl={};
  jobDays(j).forEach(function(d){var dm=map[d]||{};crews.forEach(function(c){membersOn(j,c,d).forEach(function(pid){
    var others=(dm[pid]||[]).filter(function(o){return !(o.job.id===j.id&&o.c.id===c.id)});if(!others.length)return;
    var x=dbl[pid]=dbl[pid]||{days:[],with:[]};if(x.days.indexOf(d)<0)x.days.push(d);
    others.forEach(function(o){var w=crewFull(o.job,o.c)+' ('+crewLong(o.job,o.c)+')';if(x.with.indexOf(w)<0)x.with.push(w)});
  })})});
  var dk=Object.keys(dbl);
  dk.forEach(function(pid){var p=byId[pid],x=dbl[pid];lines.push({k:'dbl',t:(p?niceName(p.name):'Someone')+' is also on '+x.with.join(', ')+' ('+x.days.map(fmt).join(', ')+')'})});
  var jn=Object.assign({},j,{reqs:j.reqs||[]}),expP={},badP={};
  crews.forEach(function(c){(c.members||[]).forEach(function(pid){var p=byId[pid];if(!p)return;var e=evalPerson(p,jn,c);
    e.fails.forEach(function(f){var soon=/^Expires /.test(f.why);(soon?expP:badP)[pid]=1;lines.push({k:soon?'exp':'bad',t:niceName(p.name)+': '+f.label+' \u2013 '+f.why})});
  })});
  var nb=Object.keys(badP).length,ne=Object.keys(expP).length;
  if(short)badges.push(short+' short');
  var lmap=ertLeaveMap(),onLv={};
  crews.forEach(function(c){(c.members||[]).forEach(function(pid){if(onLv[pid])return;var ds=crewDaysOf(j,c,pid).filter(function(k){return jobDays(j).indexOf(k)>-1});var L=ertLeaveOnDays(pid,ds,lmap);if(!L.length)return;onLv[pid]=1;var p=byId[pid];lines.push({k:'leave',t:(p?niceName(p.name):'Someone')+' is on '+stLvText(L[0])})})});
  var nlv=Object.keys(onLv).length,scanCov=0;
  crews.forEach(function(c){if(!(c.members||[]).length)return;crewDays(j,c).forEach(function(day){if(crewDayTicket(j,c,day,''))return;var u=unlinkedTicketsFor(j,c,day);if(u.length){scanCov++;lines.push({k:'scan',t:crewLong(j,c)+' '+fmt(day)+': a ticket in the ER Log may already cover this. Open the job and link it instead of completing it again.'})}})});
  var nv=Object.keys(vseen).length;
  if(scanCov)badges.push('Ticket may already be logged');
  if(nlv)badges.push(nlv+' on leave');
  if(dk.length)badges.push(dk.length+' double-booked');
  if(nv)badges.push(nv===1?'Vehicle double-booked':nv+' vehicles double-booked');
  if(nb)badges.push(nb+(nb===1?' person':' people')+' expired or missing requirements');
  if(ne)badges.push(ne+(ne===1?' person':' people')+' expiring during job');
  if(noLead)badges.push(noLead===crews.length&&crews.length===1?'No team lead':noLead+' without team lead');
  if(noVeh)badges.push(noVeh===crews.length&&crews.length===1?'No vehicle':noVeh+' without vehicle');
  if(noPh)badges.push(noPh===crews.length&&crews.length===1?'No rep phone':noPh+' without rep phone');
  var ord={scan:-1,leave:0.5,vdbl:1.5,short:0,dbl:1,bad:2,exp:3,lead:4,veh:5,phone:6};lines.sort(function(a,b){return ord[a.k]-ord[b.k]});
  return {badges:badges,lines:lines};
}
function jobChecksCard(j){
  if(!j||j.done||(S.js&&S.js.completing)||(isDate(j.end)&&j.end<iso(TODAY)))return '';
  var ck=jobChecks(j);if(!ck.lines.length)return '';
  return '<div class="card jchk"><h3>Before this job goes out</h3>'+ck.lines.map(function(l){return '<div class="jchkl jk-'+l.k+'">\u26A0 '+esc(l.t)+'</div>'}).join('')+(S.canWrite?'<div class="none" style="margin-top:8px">Tap Edit to fix these.</div>':'')+'</div>';
}
function jobMatch(j,q,byId){
  if(!q)return true;
  var parts=[jobName(j),jobRef(j),siteText(j),j.place,j.notes,j.jobNo?String(j.jobNo):''];
  (j.crews||[]).forEach(function(c){parts.push(c.title,crewRef(j,c),c.repName,c.jobNo?String(c.jobNo):'');(c.members||[]).forEach(function(id){var p=byId[id];if(p)parts.push(p.name)})});
  var hay=parts.filter(Boolean).join(' ').toUpperCase();
  return String(q).toUpperCase().split(/\s+/).filter(Boolean).every(function(w){return hay.indexOf(w)>-1});
}
function jobGroupOf(j,t,tom,wk,now){
  if(!isDate(j.start))return 'none';
  var e=isDate(j.end)?j.end:j.start;
  var ph=j.done?'':v504Phase(j,now);  /* 5.04: the heading follows the pill */
  if(ph==='over')return 'over';if(ph==='yes')return 'yes';if(ph==='fin'||ph==='act'||ph==='tod')return 'today';
  if(e<t)return e===addDays(t,-1)?'yes':'over';
  if(j.start<=t)return 'today';
  if(j.start===tom)return 'tom';
  if(j.start<=wk)return 'week';
  return 'later';
}
function jobFoot(j){
  var st=jobState(j),L=jobLog(j);
  var txt=st==='signed'?'Signed':st==='unlogged'?'Completed, not signed':st==='overdue'?'Overdue':'Not completed';
  var ph=(st==='todo'||st==='overdue')?v504Phase(j):'';if(ph){st=V504_WORD[ph][1];txt=V504_WORD[ph][0]}  /* 5.04: the ladder from the shift times */
  var stSt=st;
  var sub=(j.done&&!jobFinishReady(j))?'Finish time required':'';
  if(!sub&&L.n){sub=j.done?(L.signed+' of '+L.exp+(L.exp===1?' ticket signed':' tickets signed')):(L.n+(L.n===1?' ticket is':' tickets are')+' still in the ER Log')}
  var armed=!!(S.delArm&&S.delArm.kind==='job'&&S.delArm.id===j.id);
  var btns='';
  if(S.canWrite){
    btns=(stSt==='unlogged'?(L.n>0?'<span class="jtknote">Has a ticket \u2022 edit it in the ER Log</span>':'<button class="mini" data-act="job-reopen-list" data-jid="'+esc(j.id)+'">Reopen</button>'):'<button class="btn jbtn" data-act="job-done-list" data-jid="'+esc(j.id)+'">Complete job</button>')+
      (S.canWrite?(jobWorked(j)?'<button class="mini jarch" data-act="job-arch" data-jid="'+esc(j.id)+'">Archive</button>':'<button class="mini jcxl" data-act="job-del" data-jid="'+esc(j.id)+'">Cancel job</button>'):'');
  }
  return '<div class="jbf"><div class="jstw"><span class="jst '+st+'">'+txt+'</span>'+(sub?'<span class="jsub">'+esc(sub)+'</span>':'')+'</div><div class="jbb">'+btns+'</div></div>';
}
function jobConfChips(j,byId){
  if(!j||j.done||!S.canWrite||S.isErt||!S.ertConf)return '';
  var t=iso(TODAY),lim=addDays(t,13),first='';
  (j.crews||[]).forEach(function(c){crewDays(j,c).forEach(function(d){if(d>=t&&d<=lim&&(!first||d<first)&&membersOn(j,c,d).length)first=d})});
  if(!first)return '';
  if(!byId){byId={};S.people.forEach(function(p){byId[p.id]=p})}
  var cs=crewOrder(j).filter(function(c){return crewDays(j,c).indexOf(first)>-1&&membersOn(j,c,first).length});
  return cs.map(function(c){
    var mem=membersOn(j,c,first).map(function(id){return byId[id]}).filter(Boolean);if(!mem.length)return '';
    var ok=mem.filter(function(p){return cfStatus(p,j,c,first)==='ok'}).length,lab=cs.length>1?c.shift+(crewCount(j,c.shift)>1?' '+crewNum(j,c):'')+': ':'';
    return '<span class="jcc '+(ok===mem.length?'jcc-ok':'jcc-wait')+'" title="Confirmations for '+esc(shortDay(first))+'">'+esc(lab+ok+' of '+mem.length+' confirmed')+'</span>';
  }).join('');
}
