  requestAnimationFrame(function(){try{var hh=el.offsetHeight;if(sh&&hh)sh.style.setProperty('--cpanh',(hh+22)+'px');document.documentElement.style.setProperty('--cpanh',(hh+22)+'px')}catch(x){}});
