    for(var i=0;i<n;i++){
      R.push({h:36,cells:b.map(function(col){var p=col.ppl[i];var rl=p?roleOf(col.c,p.id):'';return {lines:p?[{t:p.name+(p.id===col.c.lead?' (Lead)':'')+(rl?' ('+roleLabel(rl)+')':''),font:'500 17px '+FONT,color:rl?ROLEC[rl].fg:undefined}]:[],fill:rl?ROLEC[rl].bg:undefined}})});
    }
    if(b.some(function(col){return col.c.meetAt}))simple(function(col){return String(col.c.meetAt||'').toUpperCase()},'800 16px '+FONT);
    if(b.some(function(col){return col.c.startTime}))simple(function(col){return time12(col.c.startTime)},'800 16px '+FONT);
    var vt=function(col){return (col.c.vehicles||[]).map(function(id){var q=vehById(id);return q?q.name:''}).filter(Boolean).join(', ')};
    if(b.some(function(col){return vt(col)}))simple(vt,'800 16px '+FONT);
    var eqp=function(col){var e=(col.c.equip||[]).map(function(x){return String(x).toUpperCase()}),o=[],q=0;m.font='500 16px '+FONT;while(q<e.length){var pr=q+1<e.length?e[q]+'  \u2022  '+e[q+1]:null;if(pr&&m.measureText(pr).width<=IW){o.push(pr);q+=2}else{o.push(e[q]);q+=1}}return o};
    var en=Math.max.apply(null,b.map(function(col){return eqp(col).length}).concat([0]));
    if(en>0)R.push({h:26,band:true,cells:b.map(function(col){return {lines:[],band:(col.c.equip||[]).length>0}})});
