function csCard(c,d){var i=(c.days||[]).indexOf(d),n=(c.regs||[]).length,mx=+c.max||0,over=mx&&n>mx;
  return '<button type="button" class="cscard csc-'+csColor(c.course)+(over?' over':'')+'" data-act="cs-view" data-id="'+esc(c.id)+'"><b>'+esc(csShort(c.course))+((c.days||[]).length>1?' ('+(i+1)+' of '+c.days.length+')':'')+'</b><small>'+esc(c.from||'')+'\u2013'+esc(c.to||'')+(c.room?' \u2022 '+esc(c.room):'')+'</small><small>\uD83D\uDC64 '+esc(csTeamText(c))+'</small><span class="n">'+n+(mx?' of '+mx:'')+'</span>'+(over?'<small class="ov">Over the maximum</small>':'')+'</button>'}
