async function nextJobNumber(count){
  count=Math.max(1,+count||1);
  var max=+((S.seq&&S.seq.jobLast)||0);
  (S.jobs||[]).forEach(function(j){max=Math.max(max,+j.jobNo||0);(j.crews||[]).forEach(function(c){max=Math.max(max,+c.jobNo||0)})});
  var first=max+1;
  if(S.db&&S.db.runTransaction){var ref=S.db.doc('config/sequences');first=await S.db.runTransaction(function(tx){return tx.get(ref).then(function(s){var cur=s.exists?(+s.data().jobLast||0):0,start=Math.max(cur,max)+1;tx.set(ref,{jobLast:start+count-1,updated:new Date().toISOString()},{merge:true});return start})})}
  S.seq=S.seq||{};S.seq.jobLast=first+count-1;
  return first;
}
async function assignCrewNumbers(d){
  var cs=crewOrder(d),used={},seen={};
  if(d.id&&S.seq&&S.seq.crewJobNos)(S.erlog||[]).concat(S.erarchive||[]).forEach(function(t){if(t.jobId===d.id&&t.crewId&&+t.jobNo>0)seen[t.crewId]=+t.jobNo});
  cs.forEach(function(c){if(!(+c.jobNo>0)&&seen[c.id])c.jobNo=seen[c.id]});
  cs.forEach(function(c){if(+c.jobNo>0){if(used[+c.jobNo])c.jobNo=null;else used[+c.jobNo]=1}});
  if(+d.jobNo>0&&!used[+d.jobNo]){var f=cs.filter(function(c){return !(+c.jobNo>0)})[0];if(f&&!(S.seq&&S.seq.crewJobNos)){f.jobNo=+d.jobNo;used[+d.jobNo]=1}}
  var need=cs.filter(function(c){return !(+c.jobNo>0)});
  if(need.length){var n=await nextJobNumber(need.length);need.forEach(function(c,i){c.jobNo=n+i})}
  var all=cs.map(function(c){return +c.jobNo}).filter(Boolean);
  d.jobNo=all.length?Math.min.apply(null,all):(d.jobNo||null);
  return d;
}
