function defaultDays(job,c,pid){var av=S.avail[pid]||{};return jobDays(job).filter(function(k){return avState(av[k]||'',c.shift)!=='no'})}
function syncCrewDays(job,oldList){
  if(!isMulti(job))return;
  var nl=jobDays(job),oldSet={},nset={};
  oldList.forEach(function(k){oldSet[k]=1});nl.forEach(function(k){nset[k]=1});
  job.crews.forEach(function(c){
    c.days=c.days||{};
    c.members.forEach(function(pid){
      var cur=(c.days[pid]||[]).filter(function(k){return nset[k]}),av=S.avail[pid]||{};
      nl.forEach(function(k){if(!oldSet[k]&&cur.indexOf(k)<0&&avState(av[k]||'',c.shift)!=='no')cur.push(k)});
      cur.sort();c.days[pid]=cur;
    });
  });
}
function normJob(o){
  var st=isDate(o.start)?o.start:'',en=isDate(o.end)?o.end:st;
  if(st&&en<st)en=st;
  var mode=(o.mode==='multi'||o.mode==='single')?o.mode:(st&&en>st?'multi':'single');
  o.mode=mode;
  if(mode==='multi'){
    var n=+o.days||(st?Math.round((pd(en)-pd(st))/86400000)+1:2);
    o.days=Math.max(2,Math.min(62,n));o.end=st?addDays(st,o.days-1):'';
  }else{o.days=1;o.end=st}
  var all=rangeDates(o.start,o.end).list;
  o.crews.forEach(function(c){
    c.days=c.days||{};
    if(mode==='multi')c.members.forEach(function(id){if(!c.days[id])c.days[id]=all.slice()});
  });
  return o;
}
function daysLabel(list){
  var ks=list.slice().sort(),runs=[],cur=null;
  ks.forEach(function(k){if(cur&&addDays(cur.e,1)===k)cur.e=k;else{cur={s:k,e:k};runs.push(cur)}});
  return runs.map(function(r){
    var a=pd(r.s),b=pd(r.e);
    if(r.s===r.e)return a.getDate()+' '+MON[a.getMonth()];
    if(a.getMonth()===b.getMonth())return a.getDate()+'-'+b.getDate()+' '+MON[b.getMonth()];
    return a.getDate()+' '+MON[a.getMonth()]+' - '+b.getDate()+' '+MON[b.getMonth()];
  }).join(', ');
}
function gridLabel(job,c){return crewCount(job,c.shift)>1?c.shift+' \u2022 '+crewLabel(job,c):c.shift+' shift'}
function cxPeople(ids){var by={};(S.people||[]).forEach(function(p){by[p.id]=p});var seen={},out=[];(ids||[]).forEach(function(id){if(!id||seen[id])return;seen[id]=1;var p=by[id];out.push({id:id,name:p?niceName(p.name):'Someone'})});return out}
