function rosterChanges(oldJ,newJ){
  var a=jobShiftMap(oldJ),b=jobShiftMap(newJ),per={};
  function put(pid,kind,s){(per[pid]=per[pid]||{add:[],chg:[],rem:[]})[kind].push(s)}
  Object.keys(b).forEach(function(k){if(!a[k])put(b[k].pid,'add',b[k]);else if(a[k].sig!==b[k].sig)put(b[k].pid,'chg',b[k])});
  Object.keys(a).forEach(function(k){if(!b[k])put(a[k].pid,'rem',a[k])});
  return per;
}
async function notifyRosterChanges(oldJ,newJ){
  try{
    if(!window.HHSL_STANDALONE||!S.db)return;
    var per=rosterChanges(oldJ,newJ),ids=Object.keys(per).filter(function(pid){var p=(S.people||[]).filter(function(x){return x.id===pid})[0];return p&&ertCanSignIn(p)});
    if(!ids.length)return;
    var toks=[];for(var i=0;i<ids.length;i+=10){var snap=await S.db.collection('pushtokens').where('ertId','in',ids.slice(i,i+10)).get();snap.docs.forEach(function(d){var x=d.data();toks.push({id:d.id,ertId:x.ertId,token:x.token})})}
    if(!toks.length)return;
    var base=location.origin+location.pathname.replace(/index\.html$/,'');
    var msgs=toks.map(function(tk){return {token:tk.token,title:'HHSL Command',body:pushText(per[tk.ertId]),url:base}});
    var idt=await window.HHSL_getToken();
    var r=await fetch('/.netlify/functions/notify',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({idToken:idt,messages:msgs})});
    var res=await r.json().catch(function(){return {}});
    if(r.ok&&res.sent)toast('Notification sent to '+res.sent+(res.sent===1?' phone':' phones'));
    (res.invalid||[]).forEach(function(bad){toks.filter(function(x){return x.token===bad}).forEach(function(x){S.db.doc('pushtokens/'+x.id).delete().catch(function(){})})});
  }catch(e){}
}
function cfPh(j,c,pid,d){return !!(j&&j.phoneConf&&j.phoneConf[c.id+'|'+pid+'|'+d])}
function cfAppOk(p,j,c,d){var v=S.ertConf&&S.ertConf[p.id+'|'+j.id+'|'+c.id+'|'+d];return v===true||v===shiftSig(d,c.shift,c.startTime,siteText(j))}
function cfPhOnly(p,j,c,d){return cfPh(j,c,p.id,d)&&!cfAppOk(p,j,c,d)}
function cfDeclReason(p,j,c,d){var v=S.ertDecl&&S.ertDecl[p.id+'|'+j.id+'|'+c.id+'|'+d];return v?String(v.reason||''):''}
function cfStatus(p,j,c,d){
  var sg=shiftSig(d,c.shift,c.startTime,siteText(j)),v=S.ertConf&&S.ertConf[p.id+'|'+j.id+'|'+c.id+'|'+d];
  if(v===true||v===sg)return 'ok';
  if(cfPh(j,c,p.id,d))return 'ok';
  if(S.ertDecl&&S.ertDecl[p.id+'|'+j.id+'|'+c.id+'|'+d])return 'declined';
  if(!ertEmail(p))return 'noemail';
  if(!ertCanSignIn(p))return 'blocked';
  if(!S.ertSeen[p.id])return 'unreg';
  return v?'changed':'wait';
}
async function cfRemindCards(pairs,cap){
  var files=[],seen={};
  for(var i=0;i<pairs.length;i++){
    var jid=pairs[i][0],cid=pairs[i][1],k=jid+'|'+cid;if(seen[k])continue;seen[k]=1;
    var j=(S.jobs||[]).filter(function(x){return x.id===jid})[0];if(!j)continue;var one=j.crews.filter(function(c){return c.id===cid})[0];if(!one)continue;
    var jj=Object.assign({},j,{crews:[one]}),cv=jobCanvas(jj),blob=await new Promise(function(r){cv.toBlob(r,'image/png')});if(!blob)continue;
    var nm='crew-card-'+(isDate(j.start)?j.start+'-':'')+(one.shift||'crew').toLowerCase()+'-'+(files.length+1)+'.png';
    files.push(new File([blob],nm,{type:'image/png'}));
  }
  if(!files.length){toast('Could not build the crew card');return}
  cap=cap||(files.length===1?'Please confirm this job.':'Please confirm these jobs.');
  try{if(navigator.canShare&&navigator.canShare({files:files})){await navigator.share({files:files,text:cap});return}}catch(e){if(e&&e.name==='AbortError')return}
  var dl=null;try{dl=await window.claude.use('downloads')}catch(e){dl=null}
  if(!dl){toast('Sharing pictures is not available on this device');return}
  try{for(var f=0;f<files.length;f++)await dl.save({kind:'crewimage',filename:files[f].name,data:files[f]});var cp=await copyText(cap);toast((files.length===1?'Crew card saved.':files.length+' crew cards saved.')+' Attach in WhatsApp'+(cp?'; the reminder line is copied, paste it with the picture.':'.'))}
  catch(e){if(e&&e.code==='declined')return;toast('Could not save the crew card')}
}
