  var c=ertCalc(f),sites=S.isErt?((S.ertRates&&S.ertRates.sites)||[]):(S.ertSitesStaff||(S.ertSitesStaff=ertRateSitesBuild())),y=yardCfg();
  var h='<div class="ertform"><h4>'+(f.id?'Edit ':'Add ')+ERT_TYPES[f.type]+'</h4><div class="erttimes"><div class="f"><label for="ertf-start">On duty</label><input id="ertf-start" type="time" data-ertf="start" value="'+esc(f.start||'')+'"></div><div class="f"><label for="ertf-end">Off duty</label><input id="ertf-end" type="time" data-ertf="end" value="'+esc(f.end||'')+'"></div></div>';
