  if(!f.lunchPaid){var mv=ertMeal(f),md=ertMealDefault(f);h+='<div class="mealrow"><span>Unpaid lunch</span><button type="button" class="chip kindchip" data-act="ert-meal" data-v="0.5" aria-pressed="'+(mv===0.5)+'">30 min</button><button type="button" class="chip kindchip" data-act="ert-meal" data-v="1" aria-pressed="'+(mv===1)+'">1 hour</button><span class="was">'+(f.type==='yard'?'HHSL Compound':'Location')+' default: '+(md===1?'1 hour':'30 min')+'</span></div>'}
  if(f.type==='yard'&&S.isErt)f.instructor=allowAt(S.myErtId,f.date).instr;
