  if(f.type==='yard'&&!S.isErt)h+='<label class="echk"><input type="checkbox" data-ertf="instructor"'+(f.instructor?' checked':'')+'> Instructor rate</label>';
  h+='<div class="ecalc"><div><span>Hours</span><b>'+stNum(c.hours)+' h</b></div>'+(!S.isErt||ertShowPay()?'<div><span>Estimated pay</span><b>'+(c.est!=null?'\u2248 '+money(c.est):'\u2014')+'</b></div>':'')+'</div>';
  h+='<div class="was" style="padding:2px 0 6px">'+(f.type==='yard'?'HHSL Compound is paid as a full day'+(!S.isErt||ertShowPay()?' ('+money(y.rate)+', or '+money(y.instr)+' at the instructor rate)':'')+'. Hours count from '+esc(y.from)+'. ':f.siteId&&f.siteId!=='__other'?'Worked out with this site\u2019s ERT rate and overtime rules'+(c.hol?' \u2013 <b>public holiday rate</b> ('+esc((S.erc.holidays||[]).filter(function(x){return x.d===f.date}).map(function(x){return x.n}).join(', ')||'holiday')+')':'')+'. ':f.siteId==='__other'?'No pay estimate for a location that is not on the list. ':'')+(f.lunchPaid?'':'Lunch not paid: the unpaid lunch is taken off. ')+'Estimates are confirmed by the office.</div>';
  return h+'<div class="actions"><button class="btn ghost" data-act="ert-e-cancel">Cancel</button><button class="btn" data-act="ert-e-save">Save</button></div></div>';
