  var x=Object.assign({},e,{_tk:t});if(!x.jobNo&&t.no)x.jobNo=t.no;if(t.start&&t.end){x.start=t.start;x.end=t.end;try{var c=ertCalc({type:'medic',date:e.date,start:t.start,end:t.end,siteId:e.siteId||'__other',location:e.location,lunchPaid:!!e.lunchPaid,meal:e.meal});if(c.hours){x.hours=c.hours;if(c.est!=null)x.est=c.est}}catch(er){}}
  else{var th=(t.tx||[]).reduce(function(a,v){return a+(+v||0)},0);if(th)x.hours=th}
  return x;
