function ertSeenKey(){return 'ert_seen_'+S.myErtId}
function ertRosterDiff(){
  var t=iso(TODAY),cur={},seen=null;(S.ertShifts||[]).forEach(function(s){if(s.d>=t&&!s.done&&s.jobId)cur[confId(s)]={sig:sShiftSig(s),s:s}});
  try{seen=JSON.parse(localStorage.getItem(ertSeenKey())||'null')}catch(e){}
  if(!seen){ertRosterSeen(cur);return {add:[],chg:[],rem:[],upd:[]}}
  var add=[],chg=[],rem=[];
  Object.keys(cur).forEach(function(k){if(!seen[k])add.push(cur[k].s);else if(seen[k].sig!==cur[k].sig)chg.push(cur[k].s)});
  var upd=[];Object.keys(seen).forEach(function(k){if(cur[k]||seen[k].d<t)return;var s0=(S.ertShifts||[]).filter(function(s){return confId(s)===k})[0];if(s0&&s0.done)upd.push(s0);else rem.push(seen[k])});
  return {add:add,chg:chg,rem:rem,upd:upd};
}
function ertRosterSeen(cur){var o={};Object.keys(cur).forEach(function(k){var s=cur[k].s;o[k]={sig:cur[k].sig,d:s.d,sh:s.sh,site:s.site,start:s.start}});try{localStorage.setItem(ertSeenKey(),JSON.stringify(o))}catch(e){}}
