function t24pSync(smooth){var w=document.getElementById('t24pk');if(!w)return;T24P.sync=Date.now()+(smooth?600:250);
  [].forEach.call(w.querySelectorAll('.t24w'),function(wh){var i=t24pIdx(wh.dataset.w);wh.scrollTo({top:i*T24_IH,behavior:smooth?'smooth':'auto'});t24pMark(wh,i)});t24pShow(false)}
function t24pMark(wh,i){[].forEach.call(wh.children,function(it,k){it.classList.toggle('on',k===i);it.classList.toggle('n1',Math.abs(k-i)===1);it.setAttribute('aria-selected',k===i)})}
