function dashTickets(m,loc){return (S.erlog||[]).filter(function(d){return d.status==='SIGNED'&&!d.archived&&!d.exportExcluded&&d.month===m&&(loc==='all'||erAreaOf(d)===loc)})}
function dashEntries(m){var mine=(S.ertEntriesAll||[]).filter(function(e){return String(e.date).slice(0,7)===m});return ertLive(mine)}
function entErtEntered(e){return e.source!=='job'&&!(e.status==='approved'||e.approved===true)}
function dashCalc(m,loc){
  var R={hours:0,cost:0,bands:[0,0,0,0],bandH:[0,0,0,0],sites:{},hol:{h:0,c:0},cm:{n:0,h:0,c:0},cy:{n:0,h:0,c:0},ppl:{},allow:{},est:{n:0,h:0,c:0}};
  function site(k){return R.sites[k]=R.sites[k]||{h:0,c:0,jobs:{},ppl:{},bands:[0,0,0,0],billH:0}}
  dashTickets(m,loc).forEach(function(d){var cc=ticketRateClient(d),s=site(String(d.client||'Other').toUpperCase()),hol=!!holName(d.date);if(d.jobNo)s.jobs[d.jobNo]=1;
    (d.rows||[]).forEach(function(r){var tx=(r.tx||[]).map(function(v){return +v||0}),h=tx.reduce(function(a,b){return a+b},0),c=0;
      for(var i=0;i<4;i++){if(!tx[i])continue;var mask=[0,0,0,0];mask[i]=tx[i];var bc=0;try{bc=rowPay(Object.assign({},r,{tx:mask}),d.date,cc)}catch(e){}R.bands[i]+=bc;R.bandH[i]+=tx[i];s.bands[i]+=bc;c+=bc}
      R.hours+=h;R.cost+=c;s.h+=h;s.c+=c;if(r.pid){s.ppl[r.pid]=1;var P=R.ppl[r.pid]=R.ppl[r.pid]||{h:0,c:0};P.h+=h;P.c+=c;var al=allowAt(r.pid,d.date);if(al.lead||al.instr){var A=R.allow[r.pid]=R.allow[r.pid]||{h:0,lead:al.lead,instr:al.instr};A.h+=h}}
      if(hol){R.hol.h+=h;R.hol.c+=c}})});
  if(loc==='all')dashEntries(m).forEach(function(e){var h=+e.hours||0,c=+e.est||0,cm=e.type==='medic',s=site(cm?String(e.location||'Client Medic').toUpperCase()+' (MEDIC)':'HHSL COMPOUND');s.h+=h;s.c+=c;s.ppl[e.ertId]=1;R.hours+=h;R.cost+=c;R.bands[0]+=c;R.bandH[0]+=h;var X=cm?R.cm:R.cy;X.n++;X.h+=h;X.c+=c;if(entErtEntered(e)){R.est.n++;R.est.h+=h;R.est.c+=c}var P=R.ppl[e.ertId]=R.ppl[e.ertId]||{h:0,c:0};P.h+=h;P.c+=c});
  return R;
}
