async function dailyCleanup(){
  try{
    if(!S.db||S.isErt||!S.canWrite)return;
    var k='hhsl_cleanup_'+iso(TODAY);if(localStorage.getItem(k))return;localStorage.setItem(k,'1');
    var cut2=(function(){var d=new Date(TODAY);d.setMonth(d.getMonth()-2);return iso(d)})();
    /* shift confirmations older than 2 months */
    try{var c=await S.db.collection('ertconfirm').where('date','<',cut2).limit(400).get();for(var i=0;i<c.docs.length;i++){try{await c.docs[i].ref.delete()}catch(e){}}}catch(e){}/* download record older than 3 months (Owner and Executives) */
    if(S.isExec||S.isOwner){try{var cut3=Date.now()-92*86400000,cut3i=new Date(cut3).toISOString();var l=await S.db.collection('dllog').where('at','<',cut3i).limit(400).get();for(var m=0;m<l.docs.length;m++){var x=l.docs[m].data()||{};if(S.isOwner||(typeof x.ms==='number'&&x.ms<cut3)){try{await l.docs[m].ref.delete()}catch(e){}}
    if(S.isExec||S.isOwner){try{var cut4=Date.now()-92*86400000;var l4=await S.db.collection('signins').where('ms','<',cut4).limit(400).get();for(var m4=0;m4<l4.docs.length;m4++){try{await l4.docs[m4].ref.delete()}catch(e){}}}catch(e){}}}}catch(e){}}
  }catch(e){}
}
