function updSummaryOn(c){return c[4]===1||(c[4]===2&&typeof hp==='function'&&hp('ertHours'))}
function updCatOn(key){var P=updPref(),c=UPD_CATS.filter(function(x){return x[0]===key})[0];if(!c)return true;
  if(P.view==='all')return true;if(P.view==='summary')return updSummaryOn(c);return P.cats&&key in P.cats?!!P.cats[key]:updSummaryOn(c)}
