  var den=Notification.permission==='denied',btns='<div class="actions" style="padding:14px 0 0;flex-direction:column;align-items:stretch"><button class="btn" data-act="spp-on">Turn on</button><button class="btn ghost" data-act="spp-later">Maybe later</button></div>';
