function alertTracked(path){var c=String(path||'').split('/')[0];return c==='leavereq'||c==='jobletter'||c==='linkreq'||c==='staffupd'||c==='ertupd'||c==='ertconfirm'||c==='tkphoto'||c==='ertentries'||c==='staffleave'}
function alertKindFor(path,prev,next){var c=String(path||'').split('/')[0],ps=prev&&prev.status,ns=next&&next.status;if(!next)return '';
  if(c==='leavereq'){if(ns==='pending'&&ps!=='pending')return next.conv?'lvx':'lvq';if(ps==='pending'&&(ns==='approved'||ns==='declined'||ns==='recorded'))return 'lvd';if(ns==='cancelask'&&ps!=='cancelask')return 'lvx';if(ps==='cancelask'&&ns==='cancelled')return 'lvcd';if(ns==='awol'&&!prev)return 'awol';if(ns==='awol'&&prev&&ps==='awol'&&next.mistakeAt&&next.mistakeAt!==prev.mistakeAt)return 'awm'}
  if(c==='staffleave'){if(!prev&&next.kind==='leave'&&next.byOffice===true&&next.atl!==true)return 'lvrec';return ''}
  if(c==='jobletter'){if(next.onBehalf){return (ns!==ps&&ns==='revoked')?'jlme':''}if(ns==='requested'&&ps!=='requested')return 'jlq';if(ns!==ps&&(ns==='issued'||ns==='declined'||ns==='revoked'))return 'jlme'}
  if(c==='linkreq'){if(!prev||((ns==='pending'||!ns)&&ns!==ps))return 'lnk';if(ns!==ps&&(ns==='approved'||ns==='declined'))return 'lnkme'}
  if(c==='staffupd'){if(ns==='applied'&&ps!=='applied')return 'mpa';if(ns==='pending'&&ps!=='pending')return 'mpc';if(ps==='pending'&&(ns==='approved'||ns==='declined'))return 'mpd'} if(c==='ertupd'){if(ns==='pending'&&ps!=='pending')return 'pup'} if(c==='ertconfirm'){if(ns==='declined'&&ps!=='declined')return 'unconf'} if(c==='tkphoto'){if(ns==='sent'&&ps!=='sent')return 'tlp'} if(c==='ertentries'){if(!prev&&next&&next.ertId)return 'ertpend'} if(path==='config/erlog'&&next&&next.__rtchg)return 'rtchg'; return ''}
