function updPending(){return (S.updList||[]).filter(function(x){return x.status==='pending'}).sort(function(a,b){return String(a.created).localeCompare(String(b.created))})}
function updLockOf(x){if(!x||!x.reviewBy)return null;var age=Date.now()-Date.parse(x.reviewAt||0);if(!(age<4*3600e3))return null;return {by:x.reviewBy,name:x.reviewByName||x.reviewBy,at:x.reviewAt,mine:x.reviewBy===String((S.me&&S.me.email)||'').toLowerCase()}}
function updHomeRow(){if(S.isErt||!window.HHSL_STANDALONE||!hp('upd'))return '';var xs=updPending();var mine=xs.filter(function(x){var l=updLockOf(x);return l&&l.mine}).length;
  return '<button class="hrow" data-act="upd-open"><span class="hic"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M16 3h5v5"/><path d="M21 3l-7 7"/><path d="M11 5H6a2 2 0 0 0-2 2v11a2 2 0 0 0 2 2h11a2 2 0 0 0 2-2v-5"/></svg></span><span class="hmain"><b>ERT profile updates</b><span>'+(!xs.length?'No updates waiting':(mine?'You have a review in progress \u2022 ':'')+xs.length+(xs.length===1?' update waiting for approval':' updates waiting for approval'))+'</span></span>'+(xs.length?'<span class="hbadgenum">'+xs.length+'</span>':'')+'<span class="hchev" aria-hidden="true">\u203A</span></button>'}
function updPersonOf(x){return (S.people||[]).filter(function(p){return p.id===x.ertId})[0]||null}
