  if(canDecide)h+='<div class="card"><div class="f"><label for="upd-reason">Reason if you reject (the ERT sees this)</label><input id="upd-reason" type="text" maxlength="200" placeholder="For example: the photo is not clear" value="'+esc(R.reason||'')+'"></div><div class="actions"><button class="btn danger" data-act="upd-reject">Reject</button><button class="btn" data-act="upd-approve">Approve and save</button></div></div>';
