    var res=await fetch('/.netlify/functions/scan',{method:'POST',signal:ctl.signal,headers:{'content-type':'application/json',authorization:'Bearer '+token},body:JSON.stringify({kind:'document',mediaType:'image/jpeg',image:img})});var data=null;try{data=await res.json()}catch(e){}
