  if(ch.chg.length)parts.push((ch.chg.length===1?'Shift changed: '+d(ch.chg[0])+', '+ch.chg[0].sh+' shift, '+ch.chg[0].site+(ch.chg[0].start?', '+time12(ch.chg[0].start):''):ch.chg.length+' shifts changed')+'. Please confirm again.');
  if(ch.rem.length)parts.push(ch.rem.length===1?'Shift removed: '+d(ch.rem[0])+' at '+ch.rem[0].site+'.':ch.rem.length+' shifts removed.');
