function loadPhoto(id){
  if(!S.db)return;
  S.db.doc('photos/'+id).get().then(function(s){
    var u=s.exists?((s.data()||{}).data||null):null;
    if(S.photos[id]!==u){S.photos[id]=u;refreshPhoto(id)}else if(S.photos[id]===undefined){S.photos[id]=null;refreshPhoto(id)}
  }).catch(function(){});
}
