  try{listFor('orient').forEach(function(x){var k=keyOf('orient',x),lab=rateNorm(labelOf('orient',x)||k);out.push({id:locId('o',k),kind:'o',key:k,name:lab,alt:rateNorm(k),label:labelOf('orient',x)});
    placesOf(k).forEach(function(p){var pn=rateNorm(p);out.push({id:locId('place',k,p),kind:'p',key:k,place:p,name:pn,alt:'',label:p,parent:lab})})})}catch(e){}
  return out;
