function tscanPplPaint(){var el=$('#tscan-ppl');if(el)el.innerHTML=tscanPeopleHtml();var nt=$('#tscan-notes');var sc=S.tscan;if(nt&&sc&&!sc.notesTouched){nt.value=tscanAutoNotes(sc.result.fields).map(function(x){return '\u2022 '+x}).join('\n')}}
