function normalClient(c,legacy){c=c||{};var n=String(c.n||'').trim().toUpperCase(),atl=n==='ATLANTIC',plnl=c.profile==='plnl',hasRates=Array.isArray(c.rates),rates=hasRates?c.rates.map(function(r){var bv=r.base===''||r.base==null?null:Math.max(0,+r.base||0),lv=r.lead===''||r.lead==null?null:Math.max(0,+r.lead||0);return {y:+r.y||2026,base:bv,lead:lv}}):(atl?defaultClientRates(n,legacy):[]),current=yearRate(rates,new Date().getFullYear()),baseRate=c.baseRate===''||c.baseRate==null?(current&&current.base!=null?current.base:null):Math.max(0,+c.baseRate||0),leadRate=c.leadRate===''||c.leadRate==null?(current&&current.lead!=null?current.lead:null):Math.max(0,+c.leadRate||0),fallback=atl?atlanticPayRules():(plnl?plnlPayRules():standardPayRules()),rules=cleanPayRules(c.rules,fallback),profile=(atl||c.profile==='atlantic')?'atlantic':(plnl||JSON.stringify(rules)===JSON.stringify(plnlPayRules())?'plnl':(JSON.stringify(rules)===JSON.stringify(standardPayRules())?'standard':'custom'));if(c.profile==='custom')profile='custom';if(/^preset_/.test(String(c.profile||''))||['standard','plnl','atlantic'].indexOf(c.profile)>-1)profile=String(c.profile);return {id:String(c.id||rateSiteId(n)),active:c.active!==false,n:n,site:String(c.site||defaultWorkSite(n)).trim().toUpperCase(),meal:Math.max(0,+c.meal||0),none:!!c.none,min:(c.min==null?(n==='CGCL'?4:5):Math.max(0,+c.min||0)),profile:profile,baseRate:baseRate,leadRate:leadRate,rates:rates,rules:rules,medicProfile:(function(){var mp=c.medicProfile||(c.medicOt==='8x4'?'medic84':c.medicOt==='same'?'same':(n==='PLNL'?'medic84':'same'));return mp})(),medicRules:(function(){var mp=c.medicProfile||(c.medicOt==='8x4'?'medic84':c.medicOt==='same'?'same':(n==='PLNL'?'medic84':'same'));if(mp==='same')return null;if(c.medicRules)return cleanPayRules(c.medicRules,rules);return medic84Rules(rules)})()}}
