      var wasExcluded=!!d.exportExcluded,wasReason=d.exportExcludeReason||'';d.archivedWasExcluded=wasExcluded;d.archivedPreviousExcludeReason=wasReason;d.archivedPreviousExcludedAt=d.exportExcludedAt||'';d.archivedPreviousExcludedBy=d.exportExcludedBy||'';d.archivedPreviousExcludedOwner=!!d.exportExcludedOwner;
