async function saveErDoc(d){
  if(!S.db)return false;
  try{if(d&&d.status==='SIGNED'){var was1=(S.erlog||[]).concat(S.erarchive||[]).filter(function(x){return x.id===d.id})[0];if(!(was1&&was1.status==='SIGNED')){var mi1=missingTicketData(d);if(mi1.length){toast('Complete '+mi1.join(', ')+' before signing');return false}}}}catch(e){}
  if(d.status==='SIGNED'&&erFutureSign(d)){var was0=(S.erlog||[]).filter(function(x){return x.id===d.id})[0];if(!was0||was0.status!=='SIGNED'||was0.date!==d.date){toast(erFutureMsg(d));return false}}
  var id=d.id,body=Object.assign({},d);delete body.id;
  try{await S.db.doc('erlog/'+id).set(body);return true}
  catch(e){toast(e&&e.code==='invalid_argument'?'You do not have permission to change the log':'Could not save. Try again.');return false}
}
