  var styles=ER_STYLES_XML.replace(/numFmtId="14"/g,'numFmtId="166"').replace('<numFmts count="1">','<numFmts count="3">').replace('</numFmts>',function(){return '<numFmt numFmtId="165" formatCode="&quot;$&quot;#,##0.00"/><numFmt numFmtId="166" formatCode="d/m/yyyy"/></numFmts>'}).replace('<cellXfs count="38">','<cellXfs count="39">').replace('</cellXfs>','<xf borderId="2" fillId="0" fontId="4" numFmtId="165" xfId="0" applyAlignment="1" applyBorder="1" applyFont="1" applyNumberFormat="1"><alignment horizontal="right" vertical="center"/></xf></cellXfs>');
