async function exportErLog(given){
  ernTouch();var docs=docsWithNumbers((given||monthDocs()).filter(function(d){return d.status==='SIGNED'&&!d.exportExcluded&&!d.archived}));if(!docs.length){toast('Nothing signed and included to export this month');return}
  var dl=null;try{dl=await window.claude.use('downloads')}catch(e){dl=null}
  if(!dl){toast('Saving files is not available in this view');return}
  var blob;try{blob=await buildErWorkbook(docs,S.erm,S.era)}catch(e){toast('Could not build the spreadsheet');return}
  var areaFile=S.era==='Atlantic'?'ATLANTIC':'POINT-LISAS';
  try{await dl.save({kind:'erlog',filename:'ER-LOG-'+areaFile+'-'+S.erm+'.xlsx',data:blob});toast(erAreaLabel(S.era)+' spreadsheet saved')}
  catch(e){if(e&&e.code==='declined')return;toast('Could not save the spreadsheet')}
}
function multOptions(v){return [1,1.5,2,3].map(function(n){return '<option value="'+n+'"'+(+v===n?' selected':'')+'>'+n+'x</option>'}).join('')}
function clientRateSummary(c){var base=rateFor(iso(TODAY),'ERT',c),lead=rateFor(iso(TODAY),'TEAM LEAD',c),kind=c.baseRate==null&&c.leadRate==null?'Uses default rates':'Site override';return kind+' • ERT '+money(base)+'/hr • lead '+money(lead)+'/hr'}
function defaultRatesHtml(dis){var ert=+S.erc.defaultErt||0,lead=S.erc.defaultLead==null?ert:+S.erc.defaultLead||0;return '<div class="defaultbox"><h4>Default hourly rates</h4><p class="hint">These rates are copied into each new job and then locked. Changing a default later affects only jobs created afterward.</p><div class="erc2"><label>Default ERT rate per hour<input type="number" step="0.01" min="0" inputmode="decimal" data-drt="ert" value="'+ert+'"'+dis+'></label><label>Default lead rate per hour<input type="number" step="0.01" min="0" inputmode="decimal" data-drt="lead" value="'+lead+'"'+dis+'></label></div><div class="calc-rate">ERT: 1x '+money(ert)+' • 1.5x '+money(ert*1.5)+' • 2x '+money(ert*2)+' • 3x '+money(ert*3)+'<br>Lead: 1x '+money(lead)+' • 1.5x '+money(lead*1.5)+' • 2x '+money(lead*2)+' • 3x '+money(lead*3)+'</div></div>'+'<div class="card" id="sec-ertpay"><h3>ERT pay estimates</h3><label class="echk" style="margin:4px 14px 12px"><input type="checkbox" data-ertshowpay="1"'+(S.erc.ertShowPay!==false?' checked':'')+dis+'> Show pay estimates to ERTs</label><div class="none">On: ERTs see estimated pay on My hours and pay, their shifts and their Client Medic and Compound entries. Off: they see hours only, no amounts.</div></div>'}
function payRuleRow(c,k,label,i,isNew,dis){var r=c.rules[k],nn=isNew?' data-new="1"':'',ix=isNew?'new':i,group=k.indexOf('project')===0?'project-rule':'regular-rule';return '<div class="ercrule '+group+'"><h4>'+label+'</h4><div class="rulegrid">'+
  '<label>First hours<input type="number" step="0.25" min="0" inputmode="decimal" data-rule="'+k+'" data-rf="h1" data-i="'+ix+'"'+nn+' value="'+r.h1+'"'+dis+'></label>'+ 
  '<label>First rate<select data-rule="'+k+'" data-rf="m1" data-i="'+ix+'"'+nn+dis+'>'+multOptions(r.m1)+'</select></label>'+ 
  '<label>Next hours<input type="number" step="0.25" min="0" inputmode="decimal" data-rule="'+k+'" data-rf="h2" data-i="'+ix+'"'+nn+' value="'+r.h2+'"'+dis+'></label>'+ 
  '<label>Next rate<select data-rule="'+k+'" data-rf="m2" data-i="'+ix+'"'+nn+dis+'>'+multOptions(r.m2)+'</select></label>'+ 
  '<label>Remaining rate<select data-rule="'+k+'" data-rf="m3" data-i="'+ix+'"'+nn+dis+'>'+multOptions(r.m3)+'</select></label></div></div>'}
function clientEditor(c,i,isNew,dis){var nn=isNew?' data-new="1"':'',ix=isNew?'new':i,ruleKey=String(ix),sites=workSiteOptions(c.site||c.n),base=c.baseRate==null?'':c.baseRate,lead=c.leadRate==null?'':c.leadRate,eb=c.baseRate==null?+S.erc.defaultErt||0:c.baseRate,el=c.leadRate==null?(S.erc.defaultLead==null?+S.erc.defaultErt||0:+S.erc.defaultLead||0):c.leadRate,rates='<div class="ercrate"><div class="erc1"><b>Optional site rate override</b></div><div class="erc2"><label class="rateoverride">Site ERT rate per hour<input type="number" step="0.01" min="0" inputmode="decimal" data-crate="base" data-i="'+ix+'"'+nn+' value="'+base+'" placeholder="Leave blank to use default"'+dis+'><span class="rate-default">Blank uses default: '+money(S.erc.defaultErt)+'/hr</span></label><label class="rateoverride">Site lead rate per hour<input type="number" step="0.01" min="0" inputmode="decimal" data-crate="lead" data-i="'+ix+'"'+nn+' value="'+lead+'" placeholder="Leave blank to use default"'+dis+'><span class="rate-default">Blank uses default: '+money(S.erc.defaultLead)+'/hr</span></label></div><div class="calc-rate">Effective ERT: 1x '+money(eb)+' • 1.5x '+money(eb*1.5)+' • 2x '+money(eb*2)+' • 3x '+money(eb*3)+'<br>Effective lead: 1x '+money(el)+' • 1.5x '+money(el*1.5)+' • 2x '+money(el*2)+' • 3x '+money(el*3)+'</div></div>';
  return '<div class="ercedit">'+(isNew?'<div class="erc2"><label class="wide">Client/site name<input type="text" maxlength="40" data-erc="name" data-i="new" data-new="1" value="'+esc(c.n)+'" placeholder="For example, ATLANTIC"'+dis+'></label></div>':'')+
    '<div class="erc2"><label class="wide">Name shown for work hours<input type="text" list="erc-sites-'+ix+'" maxlength="60" data-erc="site" data-i="'+ix+'"'+nn+' value="'+esc(c.site||defaultWorkSite(c.n))+'"'+dis+'><datalist id="erc-sites-'+ix+'">'+sites.map(function(n){return '<option value="'+esc(n)+'">'+esc(workSiteDisplay(n))+'</option>'}).join('')+'</datalist></label><label>Meal break'+mealPick('data-erc="meal" data-i="'+ix+'"'+nn+dis,c.meal,true)+'</label><label>Minimum hours<input type="number" step="0.25" min="0" inputmode="decimal" data-erc="min" data-i="'+ix+'"'+nn+' value="'+minFor(c)+'"'+dis+'></label><label class="chk wide"><input type="checkbox" data-erc="none" data-i="'+ix+'"'+nn+(c.none?' checked':'')+dis+'> Skip automatic pay calculation</label></div><p class="hint"><b>Skip automatic pay calculation:</b> The app will not divide time into 1x, 1.5x, 2x or 3x and estimated pay will be $0 for this site. Start and finish times are still saved, and signed tickets still add actual worked hours to staff profiles.</p><p class="hint">Signed hours are grouped under “Name shown for work hours” on roster profiles and CVs.</p>'+ 
    '<div class="ercrates">'+rates+'</div>'+ 
    '<div class="f"><label>Pay-rule starting point<select data-erc="preset" data-i="'+ix+'"'+nn+dis+'>'+presetOptions(c.profile)+'</select></label><p class="hint">Choosing a starting point fills the schedule below. You can then change any hour band. Create or edit starting points under Pay-rule starting points at the top of Rates.</p>'+(!isNew&&S.canRates?'<div class="actions" style="padding-left:0"><button class="mini" data-act="erc-save-preset" data-i="'+i+'">Save as starting point</button></div>':'')+'</div>'+ 
    '<details class="ercdetails" data-erc-rules="'+ruleKey+'"'+(S.ercRulesOpen===ruleKey?' open':'')+'><summary>Edit when 1x, 1.5x, 2x and 3x apply</summary><p class="hint">Regular rows are blue. Turnaround / Project rows are gold. “First hours” set to 0 means every hour uses the first rate. “Next hours” set to 0 skips that band and sends later hours to the remaining rate.</p>'+ 
    payRuleRow(c,'shiftWeekday','Regular • Monday–Friday',i,isNew,dis)+payRuleRow(c,'shiftSaturday','Regular • Saturday',i,isNew,dis)+payRuleRow(c,'shiftSunday','Regular • Sunday',i,isNew,dis)+payRuleRow(c,'shiftHoliday','Regular • Public holiday',i,isNew,dis)+payRuleRow(c,'projectWeekday','Turnaround / Project • Monday–Friday',i,isNew,dis)+payRuleRow(c,'projectSaturday','Turnaround / Project • Saturday',i,isNew,dis)+payRuleRow(c,'projectSunday','Turnaround / Project • Sunday',i,isNew,dis)+payRuleRow(c,'projectHoliday','Turnaround / Project • Public holiday',i,isNew,dis)+'</details>'+
    '<div class="medicpay"><div class="f"><label>Client Medic pay-rule starting point<select data-erc="mpreset" data-i="'+ix+'"'+nn+dis+'>'+medicPresetOptions(c.medicProfile||'same')+'</select></label></div>'+
    (function(){var mc={medicRules:(c.medicProfile&&c.medicProfile!=='same'&&c.medicRules)?c.medicRules:cleanPayRules(c.rules,standardPayRules())};return '<details class="ercdetails" data-erc-rules="m'+ruleKey+'"'+(S.ercRulesOpen==='m'+ruleKey?' open':'')+'><summary>Edit when 1x, 1.5x, 2x and 3x apply for Client Medic</summary>'+medicRuleRow(mc,'shiftWeekday','Client Medic \u2022 Monday\u2013Friday',i,isNew,dis)+medicRuleRow(mc,'shiftSaturday','Client Medic \u2022 Saturday',i,isNew,dis)+medicRuleRow(mc,'shiftSunday','Client Medic \u2022 Sunday',i,isNew,dis)+medicRuleRow(mc,'shiftHoliday','Client Medic \u2022 Public holiday',i,isNew,dis)+'</details>'})()+'</div>'+ 
    (isNew?'<div class="actions"><button class="btn ghost" data-act="erc-add-cancel">Cancel</button><button class="btn" data-act="erc-add-save">Save client/site</button></div>':'<div class="actions"><button class="btn ghost" data-act="erc-done">Done</button></div>')+'</div>'}
function allowList(pid){var a=S.isErt?((S.ertAllow)||[]):(((S.erc&&S.erc.allow)||{})[pid]||[]);return a.slice().sort(function(x,y){return String(x.from).localeCompare(String(y.from))||String(x.at||'').localeCompare(String(y.at||''))})}
function medic84Rules(site){var r=JSON.parse(JSON.stringify(site||standardPayRules()));r.shiftWeekday=payRule(8,1,4,1.5,2);r.projectWeekday=payRule(8,1,4,1.5,2);return r}
function medicPresetOptions(cur){return '<option value="same"'+(cur==='same'?' selected':'')+'>Same as ERT pay rules</option><option value="medic84"'+(cur==='medic84'?' selected':'')+'>Client Medic: 8 h 1x, 4 h 1.5x, then 2x (weekdays)</option>'+presetOptions(cur==='same'||cur==='medic84'?'__none':cur).replace(/<option value="custom"[^>]*>Custom<\/option>$/,'<option value="custom"'+(cur==='custom'?' selected':'')+'>Custom</option>')}
function medicRuleRow(c,k,label,i,isNew,dis){return payRuleRow({rules:c.medicRules},k,label,i,isNew,dis).replace(/data-rule="/g,'data-mrule="')}
function offshoreRatesHtml(dis){var o=offshoreCfg(),w=S.canRates&&!dis;function inp(k,lab){return '<div class="f"><label for="os-'+k+'">'+lab+'</label><input id="os-'+k+'" type="number" min="0" step="1" data-offs="'+k+'" value="'+esc(o[k])+'"'+(w?'':' disabled')+'></div>'}
  return '<div class="card" id="sec-offshore"><h3>Offshore</h3><div class="none">For crews marked <b>Offshore</b> in the job builder. Every person is paid this flat day rate for each day on the signed ticket, whatever their role, lead status, special allowance or hours.</div><div class="erttimes" style="padding:0 14px">'+inp('day','Any day, Sunday to Sunday ($ per person)')+inp('hol','Public holiday ($ per person)')+'</div>'+(w?'':'<div class="none ratesro"><b>View only.</b> Only Executives, and Admins given Rates permission and the pay switch, can change these.</div>')+'</div>'}
function allowRatesHtml(dis){
  var w=S.canRates&&!dis,A=(S.erc&&S.erc.allow)||{},t=iso(TODAY);
  var aq=String(S.allowQ||'').trim().toLowerCase();
  var active=Object.keys(A).filter(function(id){var l=allowList(id);return l.length&&!l[l.length-1].removed});
  var ids=active.filter(function(id){if(!aq)return true;var p=(S.people||[]).filter(function(x){return x.id===id})[0];return String(p?p.name:'').toLowerCase().indexOf(aq)>-1}).sort(function(a,b){var pa=(S.people||[]).filter(function(x){return x.id===a})[0],pb=(S.people||[]).filter(function(x){return x.id===b})[0];return String(pa?pa.name:a).localeCompare(String(pb?pb.name:b))});
  var rows=ids.map(function(id){var p=(S.people||[]).filter(function(x){return x.id===id})[0],cur=allowAt(id,addDays(t,1)),hist=allowList(id).slice(-4).reverse().map(function(x){return fmt(x.from)+': '+(x.removed?'removed':x.lead&&x.instr?'lead rate + instructor rate':x.lead?'lead rate':x.instr?'instructor rate':'no special rate')}).join(' \u2022 '),arm=S.allowDelArm===id;
    return '<div class="setrow alrow"><div class="nm2"><b>'+esc(p?p.name:'(removed from roster)')+'</b><span class="was">'+esc(hist)+'</span></div><div class="alchk"><label><input type="checkbox" data-allow="lead" data-id="'+esc(id)+'"'+(cur.lead?' checked':'')+(w?'':' disabled')+'> Always lead rate</label><label><input type="checkbox" data-allow="instr" data-id="'+esc(id)+'"'+(cur.instr?' checked':'')+(w?'':' disabled')+'> Instructor rate</label>'+(w?'<button class="mini'+(arm?' danger':'')+'" data-act="al-del" data-id="'+esc(id)+'">'+'Remove'+'</button>':'')+'</div></div>'}).join('');
  var opts=(S.people||[]).filter(function(p){return active.indexOf(p.id)<0}).sort(function(a,b){return String(a.name).localeCompare(String(b.name))}).map(function(p){return '<option value="'+esc(p.id)+'">'+esc(p.name)+'</option>'}).join('');
  return '<div class="card" id="sec-allow"><h3>Special allowances</h3>'+(active.length?'<div class="search" style="margin:8px 14px 0"><input id="al-q" type="search" placeholder="Search by name" autocomplete="off" aria-label="Search special allowances by name" value="'+esc(S.allowQ||'')+'"></div>':'')+'<div class="none"><b>Always lead rate:</b> paid the team lead rate on every job and ticket, even when not the lead. <b>Instructor rate:</b> every HHSL Compound day is paid at the instructor day rate. A change applies <b>from the day it is made</b>; earlier days keep the rate they had.</div>'+
    (rows||(aq?'<div class="none">No one on this list matches \u201C'+esc(S.allowQ)+'\u201D.</div>':'<div class="none">No one has a special allowance yet.</div>'))+
    alSuggestHtml(w)+(w?'<div class="f"><label for="al-add">Add an ERT</label><div class="addrow"><select id="al-add"><option value="">Choose from the roster</option>'+opts+'</select><button class="btn" data-act="al-add">Add</button></div></div>':'<div class="none ratesro"><b>View only.</b> Only Executives, and Admins given Rates permission and the pay switch, can change these.</div>')+'</div>';
}
