  var sealedM=docs.every(function(d){var n=erNumOf(d);return n&&n.sealed}),sd0=sealDateOf(S.erm);
  try{var blob=await buildErWorkbook(docs,S.erm,S.era),M=xlsxModel(await readZip(blob));if(!hp('pay'))M.sheets=M.sheets.filter(function(s){return !/by person/i.test(s.name)});openSheetViewer(erAreaLabel(S.era)+' ER Log \u2013 '+MONF[+S.erm.slice(5,7)-1]+' '+S.erm.slice(0,4),M,(sealedM?'Ticket numbers are final.':'Ticket numbers are shown as they would print now.')+(hp('pay')?'':' The By person pay sheet is for people allowed to see pay.'))}catch(e){toast('Could not open the preview')}
