async function pinHash(salt,pin){
  var s=salt+':'+pin;
  try{var buf=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s));return Array.from(new Uint8Array(buf)).map(function(b){return b.toString(16).padStart(2,'0')}).join('')}
  catch(e){var x=5381;for(var i=0;i<s.length;i++)x=((x<<5)+x+s.charCodeAt(i))|0;return 'x'+(x>>>0).toString(16)}
}
function pinFailsGet(){try{return +localStorage.getItem('hhsl_pin_fails')||0}catch(e){return S.pinFails||0}}
function pinFailsSet(n){try{if(n)localStorage.setItem('hhsl_pin_fails',String(n));else localStorage.removeItem('hhsl_pin_fails')}catch(e){}}
async function pinTry(){
  var inp=$('#pin-in'),err=$('#pin-err');if(!inp||!S.pin)return;
  if(Date.now()<S.pinLockUntil){err.textContent='Too many tries. Wait a moment and try again.';return}
  var v=inp.value.trim(),hx=await pinHash(S.pin.salt,v);
  if(hx===S.pin.hash){S.unlocked=true;S.pinFails=0;pinFailsSet(0);S.lastAct=Date.now();try{sessionStorage.setItem('ert_unlock',S.pin.updated||'legacy')}catch(e){}renderHome();pinAfterUnlock();return}
  var nf=pinFailsGet()+1;pinFailsSet(nf);S.pinFails=nf;inp.value='';
  if(nf>=PIN_MAX){pinFailsSet(0);err.textContent='Too many wrong PINs. Signing you out for safety\u2026';inp.disabled=true;var bt=document.querySelector('[data-act="pin-go"]');if(bt)bt.disabled=true;try{sessionStorage.setItem('hhsl_pin_out','1')}catch(e){}setTimeout(function(){if(window.HHSL_signOut)window.HHSL_signOut()},1200);return}
  var left=PIN_MAX-nf;err.textContent='That PIN is not right.'+(left<=3?' '+left+(left===1?' try':' tries')+' left before you are signed out.':'');
}
function whoParts(v){var s=String(v==null?'':v).trim(),m=s.match(/^(.*?)\s*\[id:([0-9a-f]{10})\]$/);return m?{name:m[1],tag:m[2]}:{name:s,tag:''}}
function isOwnerWho(v){try{if(!v)return false;var p=whoParts(v),s=String(p.name||'').trim(),email=p.tag?(S.tagMap[p.tag]||''):(s.indexOf('@')>-1?s.toLowerCase():''),on=displayName(OWNER_EMAIL_LC)||'';return email===OWNER_EMAIL_LC||s.toLowerCase()===OWNER_EMAIL_LC||(!!on&&s===on)||ownerAudit({by:s})}catch(e){return false}}
