function stStart(db){if(!db||typeof db.collection!=='function')return;
  if(S.stStarted)return;S.stStarted=true;
  db.collection('staff').onSnapshot(function(snap){if(snap&&snap.metadata&&!snap.metadata.fromCache)S.lastData=Date.now();
    var m={},rk=null,cvs={},meta={};
    snap.docs.forEach(function(d){var o=cvPhotoFill('staff',d.id,Object.assign({},d.data()));if(d.id==='_ranks'){rk=Array.isArray(o.ranks)?o.ranks.filter(function(x){return x&&x.id}):null}else if(d.id==='_meta'){meta=o}else if(d.id.indexOf('c_')===0){o.id=d.id;cvs[d.id]=o}else{o.id=d.id;m[d.id]=o}});
    try{S.stRawContact={};Object.keys(m).forEach(function(k){var o=m[k];if(o&&['phone','email','address'].some(function(f){return typeof o[f]==='string'&&o[f].trim()}))S.stRawContact[k]=true})}catch(e){S.stRawContact={}}S.stdocsAll=m;S.stdocs=v589Live(m);stContactOverlay();S.stranks=rk;S.pcvdocs=cvs;S.stmeta=meta;S.stload=true;if(!S._cvMigT)S._cvMigT=setTimeout(cvPhotoMigrate,20000);
    if(typeof pMerge==='function')pMerge();
    if(typeof pMaybeMigrate==='function')pMaybeMigrate();
    stRefresh();
    if(S.tab==='prop'&&!S.pp.d&&typeof pRender==='function')pRender();
    if(S.tab==='home')renderHome();
  },function(){S.stload=true});
  if(S.sl&&S.sl!=='none')stLeaveStart(db);
}
function stContactOverlay(){try{var P=S.stpriv||{},D=S.stdocs||{};Object.keys(D).forEach(function(k){var p=P[k],o=D[k];if(!p||!o)return;['phone','email','address'].forEach(function(f){if(typeof p[f]==='string'&&(p[f]||!S.stRawContact||!S.stRawContact[k]))o[f]=p[f]})})}catch(e){}}
async function stContactMigrate(){
  if(S._ctMig)return {busy:true,moved:0,failed:0};
  if(!S.db||S.isErt||!(S.isOwner||S.isExec)||!S.stload||!S.stlload)return {moved:0,failed:0,skip:true};
  S._ctMig=true;var moved=0,failed=0,lastErr='';
  try{
    var keys=Object.keys(S.stRawContact||{}),FV=window.firebase&&firebase.firestore&&firebase.firestore.FieldValue,del=FV?FV.delete():null;
    for(var i=0;i<keys.length;i++){var k=keys[i],o=S.stdocs&&S.stdocs[k];if(!o)continue;
      try{var raw={},pv0=(S.stpriv&&S.stpriv[k])||{};['phone','email','address'].forEach(function(f){var pv=pv0[f];if(typeof o[f]==='string'&&!(typeof pv==='string'&&pv))raw[f]=o[f]});
        if(Object.keys(raw).length)await S.db.doc('staffleave/d_'+k).set(Object.assign({kind:'private',person:k,updated:pNow()},raw),{merge:true});
        if(del)await S.db.doc('staff/'+k).update({phone:del,email:del,address:del});
        moved++;delete S.stRawContact[k]}
      catch(e){failed++;lastErr=String((e&&(e.code||e.message))||e).slice(0,160);try{if(typeof errRecord==='function')errRecord('failed','Moving staff contact details: '+lastErr,'staff/'+k)}catch(x){}}}
  }catch(e){failed++;lastErr=String(e&&e.message||e).slice(0,160)}
  S._ctMig=false;return {moved:moved,failed:failed,lastErr:lastErr};
}
async function stContactMoveNow(btn){
  try{if(btn){btn.disabled=true;btn.textContent='Moving\u2026'}
    var r=await stContactMigrate();
    if(r.busy)return;
    toast(r.failed?(r.moved+' moved, '+r.failed+' could not be moved. The reason is in Settings, Error log.'):(r.moved===1?'1 person\u2019s contact details moved':r.moved+' people\u2019s contact details moved')+' to private records');
  }catch(e){toast('Could not move the contact details. Try again.')}
  try{stRender()}catch(e){}
}
