function pStart(db){
  if(S.pStarted)return;S.pStarted=true;
  db.collection('proposals').onSnapshot(function(snap){if(snap&&snap.metadata&&!snap.metadata.fromCache)S.lastData=Date.now();
    var cv={},leg={},bids=[],co={};
    snap.docs.forEach(function(d){var o=cvPhotoFill('proposals',d.id,Object.assign({},d.data()));o.id=d.id;if(d.id==='company')co=o;else if(d.id.indexOf('b_')===0)bids.push(o);else if(d.id.indexOf('r_')===0){}else if(d.id.indexOf('p_')===0)leg[d.id]=o;else cv[d.id]=o});
    bids.sort(function(a,b){return String(b.updated||'').localeCompare(String(a.updated||''))});
    S.pcvBase=cv;S.pleg=leg;S.pbids=bids;S.pco=co;pMerge();S.pload=true;pMaybeMigrate();
    if(S.tab==='prop'&&!S.pp.d)pRender();
    if(S.tab==='home')renderHome();
  },function(){S.pload=true});
}
