    if(page==='locations'){var pl=ORIENT.reduce(function(n,k){return n+placesOf(k).length},0),rp=Object.keys(S.reps||{}).reduce(function(n,k){return n+(S.reps[k]||[]).length},0);return ORIENT.length+' orientations \u2022 '+pl+' places \u2022 '+rp+' site reps'}
    if(page==='erlog'){var act=(S.erc.clients||[]).filter(function(c){return c.active!==false}).length,hol=(S.erc.holidays||[]).filter(function(x){return String(x.d).slice(0,4)===yr}).length;return act+' active sites \u2022 '+hol+' public holidays in '+yr+(S.canRates?'':' \u2022 view only')}
