    if(page==='backup')return bkCanSee()?(bkDue()?'\u26A0 ':'')+bkWhen():'Save or restore a copy of app data';
    if(page==='changes')return 'Latest: Version '+APP_VERSION;
    if(page==='about')return 'Version '+APP_VERSION+' \u2022 app name and installed version';
