  var done=false;function fin(v){if(done)return;done=true;document.removeEventListener('keydown',kd,true);w.remove();if(typeof syncLock==='function')syncLock();try{if(prev&&prev.focus&&document.body.contains(prev))prev.focus({preventScroll:true})}catch(e){}res(v)}
