  function kd(ev){if(ev.key==='Escape'){ev.preventDefault();ev.stopPropagation();w._cancel();return}
    if(ev.key==='Enter'&&!ev.shiftKey){var t=ev.target;if(t&&t.tagName==='BUTTON'&&t.dataset.hh==='x')return;ev.preventDefault();ev.stopPropagation();ok();return}
    if(ev.key==='Tab'){var f=[].slice.call(w.querySelectorAll('button:not([disabled]),input,textarea'));if(!f.length)return;var i=f.indexOf(document.activeElement);if(ev.shiftKey&&(i<=0)){ev.preventDefault();f[f.length-1].focus()}else if(!ev.shiftKey&&i===f.length-1){ev.preventDefault();f[0].focus()}}}
