    w.innerHTML=frame('<p id="hh-b">'+hhTxt(body)+'</p>'+(last&&o.match?'<label for="hh-in">Type <b>'+esc(o.match)+'</b> to continue</label><input id="hh-in" type="text" autocomplete="off" autocapitalize="characters" spellcheck="false" class="hhmono"><div class="hhhint">Type it exactly. The button turns on when it matches.</div>':''),last?(o.ok||'Continue'):'Continue',false);
    var okB=w.querySelector('[data-hh="ok"]'),inE=w.querySelector('#hh-in');
