  r2[0]=cS(sub,A2s);r2[1]=cS('',hB);r2[2]=cS('EXPIRED',hC);r2[3]=cS('<30 DAYS',hD);r2[4]=cS('ORIENTATION',hG);r2[5]=cS(oriLab,hG);r2[6]=cS('OEUK taken',hMed);
  CERTS.forEach(function(k,i){r2[f0+i]=cS(cl('cert',k),hCert)});
