  var topLine=sb.xf({font:{sz:10},border:3});
  for(var c2=0;c2<i0+infoDef.length;c2++)if(!r2[c2])r2[c2]=cB(topLine);
  var rows=[r1,r2];
  var cE=colName(3+CERTS.length-1),oE=colName(3+ORIENT.length-1),mE=colName(3+MED.length);
  var certRng='Certificates!$D$4:$'+cE+'$'+X,certHdr='Certificates!$D$3:$'+cE+'$3';
