    row[hc]=cFC('IFERROR(MATCH(ROWS('+AH+'$3:'+AH+r+'),Calc!$H$4:$H$'+X+',0),"")',p?(people.length?1:''):'',hid);
    row[hc+1]=cFC('IF($A'+r+'="","",IFERROR(MATCH($A'+r+',Certificates!$A$4:$A$'+X+',0),""))','',hid);
