function buildCalc(sb,dim){
  var cap=dim.cap,X=3+cap,oE=colName(3+ORIENT.length-1),cols=[];
  for(var i=0;i<13;i++)cols.push({w:14});
  var st=sb.xf({font:{sz:10}}),rows=[[],[],[cS('Helper sheet for the Dashboard tab. Please do not edit.',st)]];
  var atl=['All','Pool 1/2','Alpha Shift','Bravo Shift','Charlie Shift','Delta Shift','Duty Pool','Extended Pool','ER Planner'];
  var ptl=['All','Team Lead','HQ'],nOri=ORIENT.length,listN=Math.max(atl.length,3+nOri);
  var a1='Dashboard!$A$1',a2='Dashboard!$A$2',rngM='$M$4:$M$'+(3+listN);
  var hdr=['Name','Location','Shift / Pool','Role','Include','Orientation valid','Sort key','Position','','Atlantic list','Pt.Lisas list','All list','Sub-filter list'];
  rows[2]=hdr.map(function(t){return cS(t,st)});
  for(var i=0;i<cap;i++){
    var r=4+i,row=[];
    row[0]=cF('IF(\'ERT Info\'!A'+r+'="","",\'ERT Info\'!A'+r+')','s','',st);
    row[1]=cF('IF(A'+r+'="","",\'ERT Info\'!O'+r+'&"")','s','',st);
    row[2]=cF('IF(A'+r+'="","",\'ERT Info\'!P'+r+'&"")','s','',st);
    row[3]=cF('IF(A'+r+'="","",\'ERT Info\'!Q'+r+'&"")','s','',st);
    var loc='OR('+a1+'="All",AND('+a1+'="Atlantic",OR(B'+r+'="Atlantic",B'+r+'="Atlantic / Pt.Lisas")),AND('+a1+'="Pt.Lisas",B'+r+'<>"Atlantic"),AND('+a1+'="Unassigned",B'+r+'=""))';
    var sb2='OR('+a2+'="All",'+a2+'="",ISNA(MATCH('+a2+','+rngM+',0)),AND('+a1+'="Atlantic",OR(C'+r+'='+a2+',AND('+a2+'="Pool 1/2",OR(C'+r+'="Duty Pool",C'+r+'="Extended Pool")))),AND('+a1+'="Pt.Lisas",OR(AND('+a2+'="Team Lead",D'+r+'="Team Lead"),AND('+a2+'="HQ",B'+r+'="HQ"),F'+r+')))';
    row[4]=cF('IF(A'+r+'="",0,IF(AND('+loc+','+sb2+'),1,0))','n',0,st);
    row[5]=cF('IF(A'+r+'="",FALSE,IFERROR(N(INDEX(Orientation!$D$4:$'+oE+'$'+X+',MATCH(A'+r+',Orientation!$A$4:$A$'+X+',0),MATCH('+a2+',Orientation!$D$3:$'+oE+'$3,0)))>TODAY(),FALSE))','s','FALSE',st);
    row[6]=cF('IF(E'+r+'=1,IF(D'+r+'="Supervisor",1,IF(D'+r+'="Asst. Supv.",2,3))*10000+ROW(),"")','s','',st);
    row[7]=cF('IF(E'+r+'=1,COUNTIFS($E$4:$E$'+X+',1,$G$4:$G$'+X+',"<="&G'+r+'),"")','s','',st);
    if(i<listN){
      row[9]=i<atl.length?cS(atl[i],st):null;
      row[10]=i<3?cS(ptl[i],st):(i-3<nOri?cF('Orientation!'+colName(3+i-3)+'3','s','',st):null);
      row[11]=i===0?cS('All',st):null;
      row[12]=cF('IF('+a1+'="Atlantic",IF(J'+r+'="","",J'+r+'),IF('+a1+'="Pt.Lisas",IF(K'+r+'="","",K'+r+'),IF(L'+r+'="","",L'+r+')))','s','',st);
    }
    rows.push(row);
  }
  return {name:'Calc',cols:cols,rows:rows,heights:{},nrows:cap,lastRow:3+cap,filter:false,pane:false,cf:[],hidden:true};
}
