    buildItemSheet(sb,{name:'Medical',color:'FF0000FF',sz:16,title:'MEDICAL',text:'MEDICAL EXPIRY DATES',textCol:1,people:list,items:medItems,nameW:26,itemW:14.4,plain:true,taken:true,heights:{1:18,2:15.75,3:37.5},cf:{red:'FFFF1A00',orange:'FFFF9C00',blue:'FF00BBE3',blueDays:60}}),
    buildCalc(sb,dim)
