    await step('sign-out on their devices',async function(){try{var tok=await window.HHSL_getToken();await fetch('/.netlify/functions/signout-all',{method:'POST',headers:{'content-type':'application/json',authorization:'Bearer '+tok},body:JSON.stringify({email:em})})}catch(e){}await S.db.doc('signout/'+em).set({at:now,by:by})});
