function addMonths(s,m){var d=pd(s);if(!d)return null;var day=d.getDate();d.setMonth(d.getMonth()+m);if(d.getDate()!==day)d.setDate(0);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function statusOf(it){
  if(it.flag==='exp')return 'expired';
  if(it.flag==='sched')return 'sched';
  if(!it.date)return 'none';
  var n=days(pd(it.date));
  if(n<0)return 'expired';
  if(n<=30)return 'soon';
  return 'ok';
}
function itemsOf(p){
  var out=[];
  function add(cat,key,label,v){
    if(!v)return;
    var it={cat:cat,key:key,label:label,date:null,flag:null,mon:!S.unmon[cat+':'+key]};
    if(v==='EXP')it.flag='exp';else if(v==='SCHEDULED')it.flag='sched';else it.date=v;
    it.st=statusOf(it);it.n=it.date?days(pd(it.date)):null;
    if(it.st!=='none')out.push(it);
  }
  var c=p.certs||{},o=p.orientation||{},m=p.medical||{};
  CERTS.forEach(function(k){add('cert',k,cl('cert',k),c[k])});
  ORIENT.forEach(function(k){add('orient',k,cl('orient',k),o[k])});
  MED.forEach(function(x){add('medical',x[0],x[1],m[x[0]])});
  add('doc','dpExpiry','Driver\u2019s permit',p.dpExpiry);
  add('doc','pleaExpiry','PLEA',p.pleaExpiry);
  if(p.coc)add('doc','coc','COC (valid 6 months)',addMonths(p.coc,6));
  return out;
}
