function whoLabel(v,fb){
  if(isOwnerWho(v))return 'the office';
  var p=whoParts(v),s=p.name;if(!s)return fb||'App user';
  var email=p.tag?(S.tagMap[p.tag]||''):(s.indexOf('@')>-1?s.toLowerCase():'');
  var name=s.indexOf('@')>-1?(displayName(s)||''):s;
  if(S.isExec){if(!name)return email||s;return email&&email!==name.toLowerCase()?name+' \u2022 '+email:name}
  if(name)return name;
  return 'Team member ('+s.split('@')[0].slice(0,1).toUpperCase()+'\u2022\u2022\u2022)';
}
