  var k=t.dataset.aclear?null:t.dataset.atile;S.atile=(k&&S.atile!==k)?k:null;S.n=60;var y=window.scrollY;renderAttn();
  var m=$('#attn-stk-s'),tb=$('#topbar'),h=tb&&!tb.hidden?tb.getBoundingClientRect().height:0;if(m){var top=m.getBoundingClientRect().top+window.scrollY-h;window.scrollTo(0,y>top?top:y)}
