function availText(e){
  if(!e.total)return 'Set job dates to check availability';
  if(e.atl&&e.atl.length)return e.atl[0]+(e.atl.length>1?' (+'+(e.atl.length-1)+' more)':'');
  if(e.yes===e.total)return 'Free all '+e.total+(e.total===1?' day':' days');
  var parts=[];
  if(e.yes)parts.push(e.yes+' free');
  if(e.maybe)parts.push(e.maybe+' tentative');
  if(e.blank)parts.push(e.blank+' not set');
  if(e.no)parts.push(e.no+' unavailable');
  return parts.join(', ');
}

 
async function armDelete(kind,id){
  if(!S.canWrite||!S.db)return;if(!hp('del')){toast('You do not have permission to delete');return}
  var redraw=function(){if(kind==='job')renderCrewsHome();else renderErLog()};
  if(kind==='tk'){ticketDeleteAsk(id);return}
  var old=(S.jobs||[]).filter(function(x){return x.id===id})[0];if(!old)return;
  if(!(await hhConfirm('',{title:'Delete '+((jobRef(old)?jobRef(old)+' ':'')+jobName(old)).trim()+'?',body:'It will be removed for everyone. You can Undo for 6 seconds after deleting.',ok:'Delete job',cancel:'Keep it',danger:true})))return;
  S.jobs=S.jobs.filter(function(x){return x.id!==id});redraw();
  delWithUndo('jobs/'+id,'Job deleted','Job restored').catch(function(){if(old){S.jobs.push(old);redraw()}toast('Could not delete. Try again.')});
}
 
