function openRepeatJob(j){
  if(!S.canWrite||!j)return;
  var t=iso(TODAY),end=isDate(j.end)?j.end:(isDate(j.start)?j.start:''),ns=end?addDays(end,1):'';if(ns&&ns<t)ns=t;
  var off=(isDate(j.start)&&ns)?Math.round((pd(ns)-pd(j.start))/86400000):0;
  var src=jobClone(j);
  src.crews.forEach(function(c){var had=(c.members||[]).length;c.id=uid();c.jobNo=null;c.tickets={};c.ind={};c.endTime='';c.need=(+c.need||0)>0?+c.need:(had||'');c.members=(c.members||[]).slice();c.lead=c.members.indexOf(c.lead)>-1?c.lead:'';c.roles=Object.assign({},c.roles||{});
    var nd={};c.members.forEach(function(pid){var ks=((c.days||{})[pid]||[]).map(function(k){return isDate(k)?addDays(k,off):k}).filter(isDate);if(ks.length)nd[pid]=ks});c.days=nd});
  src.id=null;src.jobNo=null;src.created='';src.done=false;src.doneAt='';src.logged=false;src.paySnapshot=null;src.payHistory=[];
  if(ns){src.start=ns;src.end=isMulti(src)?addDays(ns,Math.max(2,+src.days||2)-1):ns}
  closeSummary();openBuilder(src);
  if(!S.cb)return;
  S.cb.isNew=true;S.cb.repeat=true;S.cb.originalPay='';S.cb.job.id=null;S.cb.orig=null;renderBuilder();
  toast('Repeat of '+jobName(j)+(ns?' for '+fmt(ns):'')+'. Same crew copied: check who is available, then save.');
}
 
 
 
 
 
