function jcWhen(j){
  if(!isDate(j.start))return 'No date set';
  var t=iso(TODAY),e=isDate(j.end)?j.end:j.start;
  function one(k){var n=Math.round((pd(k)-pd(t))/864e5);var dm=pd(k).getDate()+' '+MON[pd(k).getMonth()];return n===0?'Today \u00B7 '+dm:n===1?'Tomorrow \u00B7 '+dm:n===-1?'Yesterday \u00B7 '+dm:shortDay(k)+(k.slice(0,4)!==t.slice(0,4)?' '+k.slice(0,4):'')}
  if(e===j.start)return one(j.start);
  var a=pd(j.start),b=pd(e),y=(a.getFullYear()!==TODAY.getFullYear()||b.getFullYear()!==TODAY.getFullYear())?' '+b.getFullYear():'';
  return (a.getMonth()===b.getMonth()&&a.getFullYear()===b.getFullYear()?a.getDate()+'\u2013'+b.getDate()+' '+MON[a.getMonth()]:a.getDate()+' '+MON[a.getMonth()]+' \u2013 '+b.getDate()+' '+MON[b.getMonth()])+y;
}
