function changeCount(shift,delta){
  var d=S.cb.job;
  var same=d.crews.filter(function(c){return c.shift===shift});
  if(delta>0){d.crews.push(newCrew(shift))}
  else{
    if(d.crews.length<=1){toast('A job needs at least one crew');return}
    var last=same[same.length-1];
    if(!last){return}
    if(last.members.length){toast('Remove the names from '+crewLong(d,last)+' before removing that crew');return}
    d.crews=d.crews.filter(function(c){return c.id!==last.id});
  }
  var act=activeCrew();
  d.crews=d.crews.filter(function(c){return c.shift==='Day'}).concat(d.crews.filter(function(c){return c.shift==='Night'}));
  S.cb.active=Math.max(0,d.crews.indexOf(act));
  renderCrewFields();renderCbLists();
}
