S.photos={};
/* 3.63: one high-quality square photo step for profile photos (staff-added and ERT-sent) and thumbnails.
   Square crop (centred, slightly towards the top for faces), stepped downscaling for sharpness, then the
   best JPEG quality that stays under the size cap. 560 x 560 keeps today's sharpness at roughly half the size. */
var PHOTO_PX=560,PHOTO_MAX=110000;
function hqCropSquare(bmp,size){
  var w=bmp.width||bmp.naturalWidth,h=bmp.height||bmp.naturalHeight,side=Math.min(w,h);
  var sx=Math.round((w-side)/2),sy=Math.round(Math.max(0,(h-side)*0.15));
  function cv(n){var c=document.createElement('canvas');c.width=n;c.height=n;var g=c.getContext('2d');g.imageSmoothingEnabled=true;try{g.imageSmoothingQuality='high'}catch(e){}return [c,g]}
  var first=Math.max(size,Math.min(side,size*4)),a=cv(first),c=a[0];a[1].fillStyle='#fff';a[1].fillRect(0,0,first,first);a[1].drawImage(bmp,sx,sy,side,side,0,0,first,first);
  var cur=first;while(cur/2>=size){var n=Math.round(cur/2),b=cv(n);b[1].drawImage(c,0,0,n,n);c=b[0];cur=n}
  if(cur!==size){var z=cv(size);z[1].drawImage(c,0,0,size,size);c=z[0]}
  return c;
}
function jpegUnder(c,maxChars,q0,qMin){var q=q0,u=c.toDataURL('image/jpeg',q);while(u.length>maxChars&&q>qMin+0.001){q=Math.round((q-0.04)*100)/100;u=c.toDataURL('image/jpeg',q)}return u}

async function resizeToDataUrl(file){
  var bmp;
  try{bmp=await createImageBitmap(file,{imageOrientation:'from-image'})}
  catch(e){bmp=await new Promise(function(res,rej){var im=new Image();im.onload=function(){res(im)};im.onerror=rej;im.src=URL.createObjectURL(file)})}
  var w=bmp.width||bmp.naturalWidth,h=bmp.height||bmp.naturalHeight,s=Math.min(1,560/Math.max(w,h));
  var c=document.createElement('canvas');c.width=Math.round(w*s);c.height=Math.round(h*s);
  c.getContext('2d').drawImage(bmp,0,0,c.width,c.height);
  var q=0.82,u=c.toDataURL('image/jpeg',q);
  while(u.length>180000&&q>0.4){q-=0.1;u=c.toDataURL('image/jpeg',q)}
  return u;
}
