function renderBoard(el){
  var d=S.bd,byId={};S.people.forEach(function(p){byId[p.id]=p});
  if(S.bview==='week'){renderWeekBoard(el,byId);return}
  var list=crewsOnDay(d);
  var assigned={};list.forEach(function(x){x.c.members.forEach(function(id){assigned[id]=1})});
  var busy={};crewsOnDay(d,true).forEach(function(x){x.c.members.forEach(function(id){busy[id]=1})});
  var free=S.people.filter(function(p){var v=(S.avail[p.id]||{})[d]||'';return !busy[p.id]&&(v.indexOf('Day')>-1||v.indexOf('Night')>-1)}).length;
  var html='<div class="bdnav"><button class="chip" data-act="bd-prev" aria-label="Previous day">&lsaquo;</button><label class="ermonth"><h3 style="margin:0;font-size:18px">'+esc(longDate(d))+' <span aria-hidden="true">\\u25BE</span></h3><input type="date" id="bd-date" data-bd="1" aria-label="Choose a day" value="'+d+'"></label><button class="chip" data-act="bd-next" aria-label="Next day">&rsaquo;</button></div>'+
    '<div class="bdtools">'+(list.length?'<button class="chip" data-act="bd-copy">Copy day</button>':'')+'</div>'+
    viewToggle(true)+
    '<div class="note">'+Object.keys(assigned).length+' assigned \u2022 '+free+' available and not assigned'+(function(){var s=dayShort(d);return s.n?' \u2022 <b class="bdshort">'+s.n+' short across '+s.crews+(s.crews===1?' crew':' crews')+'</b>':''})()+'</div>';
  if(!list.length){
    var nx=null;S.jobs.forEach(function(j){if(isDate(j.start)&&j.start>d&&jobArea(j)===boardArea()&&(!nx||j.start<nx))nx=j.start});
    el.innerHTML=html+'<div class="list"><div class="empty">No '+boardArea()+' crews scheduled on this day.'+(nx?'<div style="margin-top:12px"><button class="btn ghost" data-act="bd-goto" data-d="'+nx+'">Go to next scheduled day, '+esc(fmt(nx))+'</button></div>':'')+'</div></div>';return}
  if(S.bview==='sheet'){html+=sheetTable(list,byId,true,d);el.innerHTML=html;return}
  ['Day','Night'].forEach(function(s){
    var xs=list.filter(function(x){return x.c.shift===s}).sort(function(a,b){return jobName(a.job).localeCompare(jobName(b.job))||crewLabel(a.job,a.c).localeCompare(crewLabel(b.job,b.c),undefined,{numeric:true})});
    if(!xs.length)return;
    html+='<div class="h2">'+s+' shift</div>'+xs.map(function(x){return crewCard(x.job,x.c,byId,true)}).join('');
  });
  el.innerHTML=html;
}
