function normAv(v){
  var s=String(v==null?'':v).toLowerCase();
  if(!s.trim())return null;
  if(s.indexOf('unavail')>-1||s.indexOf('not avail')>-1)return 'Unavailable';
  if(s.indexOf('tentative')>-1)return 'Tentative';
  var d=s.indexOf('day')>-1,n=s.indexOf('night')>-1;
  if(d&&n)return 'Day, Night';
  if(d)return 'Day';
  if(n)return 'Night';
  return null;
}
function parseDelim(text,delim){
  var rows=[],row=[],f='',q=false,i;
  text=text.replace(/^\uFEFF/,'');
  for(i=0;i<text.length;i++){
    var c=text[i];
    if(q){if(c==='"'){if(text[i+1]==='"'){f+='"';i++}else q=false}else f+=c}
    else if(c==='"')q=true;
    else if(c===delim){row.push(f);f=''}
    else if(c==='\n'||c==='\r'){if(c==='\r'&&text[i+1]==='\n')i++;row.push(f);f='';rows.push(row);row=[]}
    else f+=c;
  }
  if(f!==''||row.length){row.push(f);rows.push(row)}
  return rows;
}
function parseText(text){
  var first=(text.split(/\r?\n/)[0]||'');
  var tabs=(first.match(/\t/g)||[]).length,commas=(first.match(/,/g)||[]).length;
  return parseDelim(text,(tabs>0&&tabs>=commas)?'\t':',');
}

 
