function cvfCompCard(d,dis,pfx){
  var h='<div class="card"><h3>Core competencies</h3><div class="none">Group related skills under a heading, for example "Safety &amp; Compliance". Included professionally in every CV style.</div>';
  h+=(d.comp||[]).map(function(g,i){
    return '<div class="pent"><div class="f"><label>Category</label><input data-a="comp" data-i="'+i+'" data-k="c" value="'+esc(g.c)+'" placeholder="For example, Safety &amp; Compliance"'+dis+'></div><div class="f"><label>Skills (comma separated)</label><input data-a="comp" data-i="'+i+'" data-k="i" value="'+esc(g.i)+'"'+dis+'></div>'+(dis?'':'<div class="actions"><button class="btn danger" data-act="'+pfx+'-arr-rm" data-a="comp" data-i="'+i+'">Remove</button></div>')+'</div>';
  }).join('')+(d.comp&&d.comp.length?'':'<div class="none">Nothing added.</div>')+(dis?'':'<div class="actions"><button class="btn ghost" data-act="'+pfx+'-arr-add" data-a="comp">Add competency</button></div>')+'</div>';
  return h;
}
function cvfCertSource(){
  return [['Certificates',CERTS.slice()],['Medical',MED.map(function(x){return x[1]})]];
}
function cvfCertPicker(d,dis,pfx,open){
  if(dis)return '';
  var h='<div class="actions"><button class="btn ghost" data-act="'+pfx+'-certpick" aria-expanded="'+(open?'true':'false')+'">Add from list</button></div>';
  if(!open)return h;
  var have={};(d.certs||[]).forEach(function(c){have[String(c.n||'').trim().toLowerCase()]=true});
  h+='<div class="exlist"><div class="none">Tick certificates to add, then tap Add checked. Already-added ones are ticked and greyed out.</div>';
  cvfCertSource().forEach(function(g){
    if(!g[1].length)return;
    h+='<div class="rephead">'+esc(g[0])+'</div>'+g[1].map(function(n){var got=have[n.toLowerCase()];return '<label class="f chk pchk"><input type="checkbox" data-cpk="'+esc(n)+'"'+(got?' checked disabled':'')+'><span>'+esc(n)+'</span></label>'}).join('');
  });
  h+='<div class="actions"><button class="btn" data-act="'+pfx+'-certadd">Add checked</button></div></div>';
  return h;
}
function cvfCertGather(){
  return [].map.call(document.querySelectorAll('[data-cpk]:checked:not(:disabled)'),function(x){return x.dataset.cpk});
}
function cvfAddErtCerts(d){
  var have={};(d.certs||[]).forEach(function(c){have[String(c.n||'').trim().toLowerCase()]=true});var n=0;
  [].forEach.call(document.querySelectorAll('[data-ertcp]:checked:not(:disabled)'),function(x){var name=x.dataset.ertcp||'',k=name.toLowerCase();if(name&&!have[k]){d.certs.push({n:name,d:x.dataset.date||''});have[k]=true;n++}});return n;
}







