/* ===== 3.71 Walk-in PIN (separate from the app lock PIN; set by anyone with Training registrations) ===== */
async function wpSet(){if(!trainOk()||!S.db)return;
  var a=await wpAsk(S.walkPin?'Change walk-in PIN':'Set walk-in PIN','New walk-in PIN (4 to 6 digits)','Next');if(a==null)return;a=String(a).trim();
  if(!/^\d{4,6}$/.test(a)){await hhAlert('',{title:'Use 4 to 6 digits',body:'The walk-in PIN must be 4 to 6 numbers.'});return}
  var b=await wpAsk('Type it again','Type the same PIN again','Save PIN');if(b==null)return;if(String(b).trim()!==a){await hhAlert('',{title:'The PINs do not match',body:'Nothing was changed. Try again.'});return}
  var salt=Array.from(crypto.getRandomValues(new Uint8Array(12))).map(function(x){return x.toString(16).padStart(2,'0')}).join('');
  try{await S.db.doc('config/walkin').set({salt:salt,hash:await pinHash(salt,a),by:String((S.me&&S.me.email)||'').toLowerCase(),byName:String((S.me&&S.me.name)||'').slice(0,120),at:new Date().toISOString()});toast('Walk-in PIN saved. It works on every device straight away.')}
  catch(e){toast('Could not save. Check your permissions and that the latest database rules are published.')}}
async function wpDel(){if(!trainOk()||!S.db)return;if(!(await hhConfirm('',{title:'Remove the walk-in PIN?',body:'Staff will leave walk-in registration with the team PIN, or with Leave if there is none.',ok:'Remove PIN',danger:true})))return;
  try{await S.db.doc('config/walkin').delete();toast('Walk-in PIN removed')}catch(e){toast('Could not remove. Check your permissions.')}}
