var HHSL_POS=['Managing Director','Director','General Manager','Department Manager','Coordinator','Supervisor','Instructor'];
var POS_PRE={'Managing Director':'director','Director':'director','General Manager':'exec','Department Manager':'dadmin','Coordinator':'staff','Supervisor':'staff','Instructor':'staff'};
document.addEventListener('change',async function(ev){var t=ev.target;if(!t)return;
  if(t.id==='acc-pos'){var r=stRanks().filter(function(x){return x.id===t.value})[0];if(!r)return;var rs=$('#acc-role'),sc=$('#acc-sec');var lv=r.lv==='view'?'staff':r.lv;if(rs&&lv&&[].some.call(rs.options,function(o){return o.value===lv}))rs.value=lv;if(sc&&r.dp)sc.value=r.dp;return}
  if(t.dataset&&t.dataset.poslv){posSave(t.dataset.poslv,{lv:t.value});return}
  if(t.dataset&&t.dataset.posdp){posSave(t.dataset.posdp,{dp:t.value});return}
  if(t.dataset&&t.dataset.accrole&&t.value==='dadmin'){var em=t.dataset.accrole;setTimeout(function(){dadminSync(em)},1500);return}});
document.addEventListener('click',async function(ev){var t=ev.target.closest&&ev.target.closest('[data-act]');if(!t)return;var a=t.dataset.act;
  if(a==='dept-open'){deptSheet();return}
  if(a==='dept-x'){var d=$('#dsheet');if(d)d.remove();return}
  if(a==='dept-go'){deptSetCur(t.dataset.id);var d2=$('#dsheet');if(d2)d2.remove();try{secApply()}catch(e){}goTab('home');renderHome();try{deptSideSync()}catch(e){}return}
  if(a==='dept-req'){deptRequest(t.dataset.id);return}
  if(a==='pos-hhsl'){t.disabled=true;posUseHhsl();return}
  if(a==='sec-emo'){if(S.secDraft){S.secDraft.icon=t.dataset.e;var nm=$('#sec-name');if(nm)S.secDraft.name=nm.value||S.secDraft.name;renderSettings()}return}
  if(a==='acc-drole'){if(!S.db)return;var em=t.dataset.email,cur=(S.access||[]).filter(function(x){return x.email===em})[0]||{},dr=Object.assign({},cur.deptRoles||{});dr[t.dataset.id]=t.dataset.r;try{await S.db.doc('access/'+em).update({deptRoles:dr});cur.deptRoles=dr;await dadminSync(em)}catch(e){toast('Could not save. Check your permissions.')}return}
});

/* ===== 3.82 Access and permissions: People, By department, ERTs, Requests; a page per person; guided add ===== */
var ACC_F=[['all','All'],['exec','Executives'],['director','Directors'],['admin','Admins'],['dadmin','Dept Admins'],['staff','Staff']];
function accessSettingsHtml(){if(!window.HHSL_STANDALONE||!S.isAdmin)return '';var v=S.accView||'people',nreq=(S.secReqs||[]).length+(S.lnkReqs||[]).length,body='';
  var tabs='<div class="acctabs" role="tablist" aria-label="Access and permissions">'+[['people','People'],['dept','Departments'],['ranks','Ranks'],['pos','Positions'],['req','Requests'+(nreq?' ('+nreq+')':'')]].map(function(t){var on=v===t[0]||((v==='one'||v==='add'||v==='give'||v==='ert')&&t[0]==='people')||(v==='links'&&t[0]==='req');return '<button type="button" role="tab" aria-selected="'+on+'" data-act="acc-view" data-v="'+t[0]+'">'+t[1]+'</button>'}).join('')+'</div><div class="acchelpbar"><button type="button" class="mini" data-act="acc-help" aria-expanded="'+(!!S.accHelp)+'">? What each level can do</button></div>'+(S.accHelp?accLevelsHtml().replace('<details class="card acclev">','<details class="card acclev" open>'):'');
  try{
    if(v==='give'){body='<button class="btn ghost accback" data-act="acc-view" data-v="people">\u2039 All people</button>'+accCardHtml()}
    else if(v==='one'&&S.accPerson){S.accMode='one';S.accOnly=S.accPerson;body='<button class="btn ghost accback" data-act="acc-view" data-v="people">\u2039 All people</button>'+accCardHtml(S.accPerson)+'<details class="card accadv"><summary><h3>More options</h3></summary>'+accPersonTop(S.accPerson)+accessLegacyHtml()+'</details>'}
    else if(v==='add'){S.accMode='add';S.accOnly='';body='<button class="btn ghost accback" data-act="acc-view" data-v="people">\u2039 All people</button><div class="card accsteps"><b>Add a person in three steps</b><ol><li>Type the email they sign in with.</li><li>Pick their position: the level and department fill in.</li><li>Check them, then tap Add and send invite.</li></ol></div>'+accPickHtml()+accessLegacyHtml()}
    else if(v==='dept')body=peDeptsHtml();else if(v==='ranks')body=peRanksHtml();
    else if(v==='ert')body=ertAccessCardHtml()||'<div class="card"><div class="none" style="padding:14px">ERT app access is managed by Executives.</div></div>';
    else if(v==='pos')body=accPosHtml();
    else if(v==='links')body=accLinksHtml();
    else if(v==='sec')body=accSecHtml();
    else if(v==='req')body=lnkReqCardHtml()+(secReqCardHtml()||'<div class="card"><div class="none" style="padding:14px">No department requests waiting.</div></div>')+accInvitedHtml()+'<div class="pe-lbl" style="margin:16px 4px 6px">Profile links</div>'+accLinksHtml();
    else body='<div class="pe-bt"><button type="button" class="mini" data-act="acc-view" data-v="ert">ERT sign-ins \u203A</button></div>'+accPeopleHtml();
  }finally{S.accMode='';S.accOnly=''}
  return tabs+body}
document.addEventListener('click',async function(ev){var t=ev.target.closest&&ev.target.closest('[data-act]');if(!t)return;var a=t.dataset.act;
  if(a==='acc-view'){S.accView=t.dataset.v;if(S.accView!=='one')S.accPerson='';S.accOpen='';renderSettings();var sh=$('#setsheet');if(sh)sh.scrollTop=0;return}
  if(a==='acc-person'){S.accPerson=t.dataset.email;S.accView='one';S.accOpen=t.dataset.email;renderSettings();var sh2=$('#setsheet');if(sh2)sh2.scrollTop=0;return}
  if(a==='acc-help'){S.accHelp=!S.accHelp;renderSettings();return}
  if(a==='acc-f'){S.accF=t.dataset.f;renderSettings();return}
  if(a==='acc-dx'){var em=t.dataset.email,id=t.dataset.id,p=(S.access||[]).filter(function(x){return x.email===em})[0],x=secById(id);if(!p)return;
    if(!(await hhConfirm('',{title:'Remove '+accName(p)+' from '+(x?x.name:'this department')+'?',body:'They keep their other departments and their access to the app.',ok:'Remove from department',cancel:'Keep',danger:true})))return;accSecChange(em,id,false);return}
});
document.addEventListener('change',function(ev){var t=ev.target;if(!t||!t.dataset)return;
  if(t.dataset.accdadd&&t.value){accSecChange(t.value,t.dataset.accdadd,true);return}
  if(t.dataset.accdto&&t.value){accSecChange(t.dataset.accdto,t.value,true);return}});
document.addEventListener('input',function(ev){var t=ev.target;if(!t||t.id!=='accq')return;S.accQ=t.value;var pos=t.selectionStart;renderSettings();var n=$('#accq');if(n){n.focus();try{n.setSelectionRange(pos,pos)}catch(e){}}});
