/* ===== 3.83 First-time tour, first-visit tips and help cards ===== */
function tuGet(k){try{return localStorage.getItem(tuKey(k))}catch(e){return null}}
document.addEventListener('click',function(ev){var t=ev.target.closest&&ev.target.closest('[data-act]');if(!t)return;var a=t.dataset.act;
  if(a==='tu-next'){if(!S.tourRun)return;S.tourRun.i++;if(S.tourRun.i>=S.tourRun.steps.length)tuEnd();else tuPaint();return}
  if(a==='tu-skip'){tuEnd();return}
  if(a==='tu-off'){tuEnd({off:true});toast('Tips are off. Turn them back on in Settings \u2192 About.');return}
  if(a==='tu-again'){tuSet('tour',null);tuSet('tipsoff',null);Object.keys(TIPS).forEach(function(k){tuSet('tip_'+k,null)});closeSettings();if(S.isErt){try{ertSetTab('shifts')}catch(e){}}else goTab('home');setTimeout(tourMaybe,700);return}
  if(a==='hp-open'){helpOpen(t.dataset.k);return}
  if(a==='hp-x'){var h=document.getElementById('hpcard');if(h)h.remove();return}});
document.addEventListener('keydown',function(ev){if(ev.key==='Escape'&&S.tourRun)tuEnd()});
