function pwEyes(){try{[].forEach.call(document.querySelectorAll('#auth-gate input[type=password]'),function(i){if(i.dataset.eye)return;i.dataset.eye='1';var w=document.createElement('div');w.className='pwwrap';i.parentNode.insertBefore(w,i);w.appendChild(i);var b=document.createElement('button');b.type='button';b.className='pweye';b.setAttribute('aria-label','Show password');b.setAttribute('aria-pressed','false');b.innerHTML=PW_EYE;w.appendChild(b)})}catch(e){}}
