  if(a!=='cs-trole'&&a!=='cs-tdel'&&a!=='cs-tadd')return;try{csKeep()}catch(e){}if(!E.team)E.team=csTeam(E);
  if(a==='cs-trole'){var x=E.team[+t.dataset.i];if(x)x.role=t.dataset.r==='assistant'?'assistant':'instructor'}
