/* WhatsApp: on phones open the WhatsApp app directly (not the WhatsApp web page) */
function waOpen(text){var enc=encodeURIComponent(text);if(isPhoneUA()){var gone=false,h=function(){if(document.hidden)gone=true};document.addEventListener('visibilitychange',h);location.href='whatsapp://send?text='+enc;
  setTimeout(function(){document.removeEventListener('visibilitychange',h);if(!gone&&!document.hidden){toast('WhatsApp did not open. Is it installed on this phone?')}},1800);return true}return false}
/* Remove an ERT's account (Executives and the Owner; the server deletes the sign-in) */
document.addEventListener('click',async function(ev){var t=ev.target.closest&&ev.target.closest('[data-act=ert-remove],[data-act=ert-allow]');if(!t||!S.db)return;ev.preventDefault();var a=t.dataset.act,id=t.dataset.id,p=(S.people||[]).filter(function(x){return x.id===id})[0];if(!p||!(S.isExec||S.isOwner))return;var em=ertEmail(p),nm=niceName(p.name||'this ERT');
  var rm=((S.ertApp&&S.ertApp.removed)||[]).slice(),bl=((S.ertApp&&S.ertApp.blocked)||[]).slice();
  if(a==='ert-remove'){
    if(!(await hhConfirm('',{title:'Remove '+nm+'\u2019s account?',body:'Their sign-in is deleted and they can no longer use HHSL Command. Their roster profile, shifts, tickets, hours and pay stay for your records. They cannot create a new account unless you tap Allow to sign up again later.',ok:'Remove account',cancel:'Keep account',danger:true})))return;
    t.disabled=true;t.textContent='Removing\u2026';
    try{var idt=await window.HHSL_getToken();var r=await fetch('/.netlify/functions/ert-remove',{method:'POST',headers:{'content-type':'application/json',authorization:'Bearer '+idt},body:JSON.stringify({email:em})});var d={};try{d=await r.json()}catch(e){}
      if(!r.ok||!d.ok){t.disabled=false;t.textContent='Remove account';toast(d.error||'Could not remove the account. Try again.');return}
      if(rm.indexOf(id)<0)rm.push(id);bl=bl.filter(function(x){return x!==id});
      await S.db.doc('config/ertapp').set({removed:rm,blocked:bl},{merge:true});S.ertApp=S.ertApp||{};S.ertApp.removed=rm;S.ertApp.blocked=bl;
      if(em){await Promise.all([S.db.doc('ertlink/'+em).delete(),S.db.doc('ertok/'+em).set({removed:true}),S.db.doc('ertpub/'+id).delete(),S.db.doc('ertshifts/'+id).delete(),S.db.doc('signout/'+em).set({at:new Date().toISOString(),by:String((S.me&&S.me.email)||'')}).catch(function(){})]);
        if(S.ertCache){delete S.ertCache.link[em];delete S.ertCache.pub[id];if(S.ertCache.shifts)delete S.ertCache.shifts[id];S.ertCache.blk=S.ertCache.blk||{};S.ertCache.blk[em]=1}}
      toast(nm+'\u2019s account has been removed.');renderSettings()}catch(e){t.disabled=false;t.textContent='Remove account';toast('Could not remove the account. Check your connection.')}
    return}
  if(a==='ert-allow'){t.disabled=true;rm=rm.filter(function(x){return x!==id});
    try{await S.db.doc('config/ertapp').set({removed:rm},{merge:true});S.ertApp=S.ertApp||{};S.ertApp.removed=rm;if(em){await S.db.doc('ertok/'+em).delete().catch(function(){});if(S.ertCache&&S.ertCache.blk)delete S.ertCache.blk[em]}
      S.ertSyncing=false;try{await ertSyncRun()}catch(e){}toast(nm+' can create an account again.');renderSettings()}catch(e){t.disabled=false;toast('Could not save. Try again.')}}});
