/* Remember emails on this device: tap the empty email box to pick one you signed in with before (never the password) */
var REM_KEY='hhsl_recent_emails';
function remList(){try{var a=JSON.parse(localStorage.getItem(REM_KEY)||'[]');return Array.isArray(a)?a.filter(function(x){return typeof x==='string'&&x.indexOf('@')>0}).slice(0,5):[]}catch(e){return []}}
function remSave(a){try{localStorage.setItem(REM_KEY,JSON.stringify(a.slice(0,5)))}catch(e){}}
function remRecord(){try{if(!S.me||!S.me.email)return;var em=String(S.me.email).toLowerCase();if(S.remRecorded===em)return;S.remRecorded=em;var a=remList().filter(function(x){return x!==em});a.unshift(em);remSave(a)}catch(e){}}
setInterval(remRecord,2000);
function remClose(){var d=document.getElementById('remdrop');if(d)d.remove()}
function remShow(){try{var e=document.getElementById('ag-email');if(!e)return;var q=String(e.value||'').toLowerCase().trim(),L=remList().filter(function(x){return !q||x.indexOf(q)===0||x.indexOf(q)>-1});remClose();if(!L.length||(L.length===1&&L[0]===q))return;
  var w=e.parentNode;if(getComputedStyle(w).position==='static')w.style.position='relative';var d=document.createElement('div');d.id='remdrop';d.className='remdrop';d.setAttribute('role','listbox');d.style.top=(e.offsetTop+e.offsetHeight+4)+'px';
  d.innerHTML=L.map(function(x){return '<div class="remrow" role="option"><button type="button" class="rempick" data-act="rem-pick" data-e="'+esc(x)+'"><span aria-hidden="true">\u21BA</span>'+esc(x)+'</button><button type="button" class="remdel" data-act="rem-del" data-e="'+esc(x)+'" aria-label="Forget '+esc(x)+' on this device">\u2715</button></div>'}).join('');w.appendChild(d)}catch(x){}}
document.addEventListener('focusin',function(ev){if(ev.target&&ev.target.id==='ag-email')remShow()});
document.addEventListener('input',function(ev){if(ev.target&&ev.target.id==='ag-email')remShow()});
document.addEventListener('pointerdown',function(ev){if(!document.getElementById('remdrop'))return;if(ev.target.closest&&(ev.target.closest('#remdrop')||ev.target.id==='ag-email'))return;remClose()},true);
document.addEventListener('click',function(ev){var t=ev.target.closest&&ev.target.closest('[data-act=rem-pick],[data-act=rem-del]');if(!t)return;ev.preventDefault();var em=t.dataset.e;
  if(t.dataset.act==='rem-pick'){var e=document.getElementById('ag-email');if(e)e.value=em;remClose();var p=document.getElementById('ag-pass');if(p)try{p.focus()}catch(x){}return}
  remSave(remList().filter(function(x){return x!==em}));var e2=document.getElementById('ag-email');remShow();if(!document.getElementById('remdrop')&&e2)try{e2.focus()}catch(x){}});
