function lnkListen(){if(S.lnkOn||!S.db||!lvApprover())return;S.lnkOn=true;try{S.db.collection('linkreq').where('status','==','pending').onSnapshot(function(sn){var _sg=sn.docs.map(function(d){return d.id}).sort().join('|'),_ch=_sg!==(S._lnkSig||'');S._lnkSig=_sg;S.lnkReqs=sn.docs.map(function(d){var o=Object.assign({},d.data());o.id=d.id;return o}).sort(function(a,b){return String(a.at).localeCompare(String(b.at))});try{updBadges()}catch(e){}if(_ch&&S.set&&S.setPage==='leave')renderSettings();if(_ch&&S.tab==='home')try{renderHome()}catch(e){}},function(){S.lnkReqs=[]})}catch(e){}}
