function lnkSuggest(r){var em=String(r.email||'').toLowerCase(),docs=S.stdocs||{},best='';Object.keys(docs).forEach(function(k){var d=docs[k]||{};if(!best&&String(d.email||'').trim().toLowerCase()===em)best=k});
  if(!best)Object.keys(docs).forEach(function(k){var d=docs[k]||{};if(!best&&d.name&&r.name&&namesAlike(String(d.name),String(r.name)))best=k});return best}
