function atlRegister(){if(S._atlReg)return;try{if(uniRegisterTab({key:'atl',name:'Atlantic',desc:'Atlantic crews: who is on shift, the cycle and ranks',
 help:{about:'Who is working now and next at Atlantic, the shift cycle, the Atlantic people from the roster, their certificates, leave and contracts.',
  can:[['See which shift is working now, which is next, who is in charge and who is off'],['See the Atlantic roster by rank and the certificates that need attention'],['Managers: quick edit Role, Shift and Location, and set the shift cycle with the gear',1],['Contracts (with the Contracts key): see contract dates; with Atlantic Manage, change them']],
  tips:['Times follow your phone\u2019s clock; shifts change at 7 a.m. and 7 p.m.','Leave opens the Leave page on the Atlantic side; anyone with Leave: Atlantic at Manage approves, an Executive too (never your own)','Atlantic needs Roster access as well.']},
 helpKey:'atl',collections:[{id:'atlantic',name:'Atlantic settings'},{id:'atlcontract',name:'Atlantic contracts'}],
 guide:'Atlantic needs Roster access too. View shows the shifts, the Atlantic people, their certificates and Atlantic leave; Manage (with Roster Manage) lets someone edit them, record and approve Atlantic leave (never their own) and set the shift cycle and who is in charge with the gear. Contracts need the Contracts key (Executives give it in a person\u2019s access card); changing contract dates also needs Atlantic Manage. Only Executives set leave allowances.',
 /* Atlantic leave waiting -> Executives (Needs you, phone atlq); the decision -> the person who recorded it (For you, phone atld). Shifts, roster, certificates and contracts send nothing. */
 updates:[{prefix:'atlq',kind:'needs',need:'exec'},{prefix:'atld',kind:'foryou'}]}))S._atlReg=true}catch(e){}}
