if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',atlRegister);else setTimeout(atlRegister,0);
function atlLv(){atlRegister();if(S.isErt||!window.HHSL_STANDALONE)return 'none';if(S.isOwner||S.isExec)return 'manage';if(S.isDirector)return 'view';try{var l=peMyLevels()||{},a=l.atl||'none',r=l.roster||'none';if(a==='none'||r==='none')return 'none';return a==='manage'&&r==='manage'?'manage':'view'}catch(e){return 'none'}}
function atlOk(){return atlLv()!=='none'}
function atlMan(){return atlLv()==='manage'}
function atlPeople(){return (S.people||[]).filter(function(p){var l=String(p.location||'');return l==='Atlantic'||l==='Atlantic / Pt.Lisas'})}
function atlSet(){return Object.assign({supRole:'Supervisor',asstRole:'Asst. Supv.'},S.atlSet||{})}
function atlOrder(){var o=atlSet().order;return Array.isArray(o)&&o.length===4&&ATL_SHIFTS.every(function(x){return o.indexOf(x)>-1})?o.slice():ATL_SHIFTS.slice()}
function atlLoad(){if(!S.db||S.atlLoading)return;S.atlLoading=true;S.db.collection('atlantic').doc('settings').get().then(function(d){S.atlSet=d.exists?(d.data()||{}):{};S.atlErr=false}).catch(function(){S.atlSet=S.atlSet||{};S.atlErr=true}).then(function(){S.atlLoading=false;S.atlLoaded=true;if(S.tab==='atl')atlRender()})}
function atlNoon(d){var x=new Date(d);x.setHours(12,0,0,0);return x}
function atlShiftDay(now){var d=new Date(now);if(d.getHours()<7)d.setDate(d.getDate()-1);return atlNoon(d)}
function atlIdx(day){var st=atlSet().cycleStart;if(!isDate(st))return null;var a=new Date(st+'T12:00:00'),n=Math.round((atlNoon(day)-a)/864e5);return ((n%8)+8)%8}
function atlPos(idx,i){return ((idx-2*i)%8+8)%8}
function atlFind(idx,k){for(var i=0;i<4;i++){var p=atlPos(idx,i);if(k==='d'&&p<2)return {i:i,n:p+1,k:'d'};if(k==='n'&&(p===2||p===3))return {i:i,n:p-1,k:'n'}}return null}
function atlNow(now){now=now||new Date();var sd=atlShiftDay(now),idx=atlIdx(sd);if(idx===null)return null;var h=now.getHours(),day=h>=7&&h<19,nx=new Date(sd);nx.setDate(nx.getDate()+1);var r={off:[],sd:sd};
 if(day){r.cur=atlFind(idx,'d');r.next=atlFind(idx,'n');r.end=new Date(now);r.end.setHours(19,0,0,0)}
 else{r.cur=atlFind(idx,'n');r.next=atlFind(atlIdx(nx),'d');r.end=new Date(nx);r.end.setHours(7,0,0,0)}
 for(var i=0;i<4;i++){if(atlPos(idx,i)>=4)r.off.push(i)}return r}
function atlOnLeave(p){return false}
function atlIc(shift){var s=atlSet(),pp=atlPeople().filter(function(p){return p.group===shift});function pick(r){r=String(r||'').trim().toLowerCase();if(!r)return null;return pp.filter(function(p){return String(p.role||'').trim().toLowerCase()===r&&!atlOnLeave(p)})[0]||null}return pick(s.supRole)||pick(s.asstRole)}
function atlIni(n){return String(n||'').trim().split(/\s+/).slice(0,2).map(function(w){return w.charAt(0).toUpperCase()}).join('')||'?'}
function atlLeft(end){var m=Math.max(0,Math.round((end-new Date())/6e4)),h=Math.floor(m/60);return (h?h+' h ':'')+(m%60)+' min'}
function atlTime(d){var h=d.getHours(),m=d.getMinutes(),ap=h<12?'a.m.':'p.m.';h=h%12||12;return h+':'+pad(m)+' '+ap}
function atlShort(nm){return String(nm||'').replace(/ Shift$/,'')}
function atlTitle(){return S.atlView==='certs'?'Certificates':S.atlView==='certfilter'?'Show these certificates':S.atlView==='roster'?'Roster':S.atlView==='shifts'?'Shifts':S.atlView==='cycle'?'Shift cycle':'Atlantic'}
var ATL_SUN='<svg width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1.5 1.5M17.5 17.5L19 19M5 19l1.5-1.5M17.5 6.5L19 5"/></svg>',ATL_MOON='<svg width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20 14.5A8 8 0 0 1 9.5 4a8 8 0 1 0 10.5 10.5z"/></svg>';
function atlBig(c,o){var nm=atlOrder()[c.i],ic=atlIc(nm),d=c.k==='d';return '<div class="atlbig '+(d?'atld':'atln')+'"><div class="atlr1"><div class="atlnmr"><i class="atldot" aria-hidden="true"></i><span class="atlvh">Working now: </span><span class="atlnm">'+esc(nm)+'</span></div>'+(d?ATL_SUN:ATL_MOON)+'</div><div class="atll1">'+(d?'Days':'Nights')+' \u2022 '+(d?'day':'night')+' '+c.n+' of 2 \u2022 ends in '+atlLeft(o.end)+'</div><div class="atlic"><div class="atlav">'+(ic&&ic.thumb?'<img src="'+esc(ic.thumb)+'" alt="">':esc(ic?atlIni(ic.name):'?'))+'</div><div><div class="atlicl">In charge</div><div class="atlicn">'+esc(ic?ic.name:'Not set')+'</div></div></div></div>'}
function atlSmall(c){var nm=atlOrder()[c.i],ic=atlIc(nm),d=c.k==='d';return '<div class="atlsm"><div class="atlsl"><i class="atlsw '+(d?'atlcd':'atlcn')+'"></i>UP NEXT \u2022 '+(d?'DAYS 7 A.M.':'NIGHTS 7 P.M.')+'</div><div class="atlsn">'+esc(nm)+'</div><div class="atlss">I/c '+esc(ic?ic.name:'not set')+'</div></div>'}
function atlTileList(){return [['roster','Roster','<circle cx="9" cy="8" r="3.5"/><path d="M2.5 20c.6-3.6 3.2-5.5 6.5-5.5s5.9 1.9 6.5 5.5"/><path d="M16 5a3.2 3.2 0 0 1 0 6M18 14.8c2 .6 3.2 2.3 3.5 5.2"/>',''],['shifts','Shifts','<path d="M16 14v2.2l1.6 1"/><path d="M16 2v4"/><path d="M21 7.5V6a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h3.5"/><path d="M3 10h5"/><path d="M8 2v4"/><circle cx="16" cy="16" r="6"/>','']]}
function atlTiles(){var t=atlTileList();return '<div class="atlrow4">'+t.map(function(x){return '<button type="button" class="card atlt" data-act="atl-go" data-v="'+x[0]+'">'+(x[3]?'<span class="atlbd">'+x[3]+'</span>':'')+'<span class="atlti"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+x[2]+'</svg></span><span class="atltt">'+x[1]+'</span></button>'}).join('')+'</div>'}
function atlNotSet(){return '<div class="card"><div class="none" style="padding:14px">Shift cycle not set yet.'+(atlMan()?' Set it once and the shifts follow from it.':' An Atlantic manager sets it once.')+'</div>'+(atlMan()?'<div class="actions" style="padding:0 14px 14px"><button type="button" class="btn" data-act="atl-go" data-v="cycle">Set the shift cycle</button></div>':'')+'</div>'}
function atlHomeHtml(){var o=atlNow(),now=new Date(),h='<div class="atltop"><span class="atllab">Today\u2019s shifts</span><span class="atlclk">'+esc(now.toLocaleDateString(undefined,{weekday:'short',day:'numeric',month:'short'}))+' \u2022 '+atlTime(now)+' <span class="atlmut">phone time</span></span></div>';
 if(!o)h+=atlNotSet();else h+='<div class="atlstage">'+atlBig(o.cur,o)+atlSmall(o.next)+'</div><div class="atloff">Also not on duty today: '+o.off.map(function(i){return '<b>'+esc(atlShort(atlOrder()[i]))+'</b>'}).join(' and ')+'</div>';
 return h+atlTiles()+atlAttnCard()}
function atlShiftsHtml(){var o=atlNow(),ord=atlOrder(),ppl=atlPeople(),h='';if(!o)return atlNotSet();
 var days=[];for(var k=0;k<8;k++){var d=new Date(o.sd);d.setDate(d.getDate()+k);days.push(d)}
 h+='<div class="atlleg"><span><i class="atlc atlcd">D</i>Days 7 a.m. to 7 p.m.</span><span><i class="atlc atlcn">N</i>Nights 7 p.m. to 7 a.m.</span><span><i class="atlc atlco">\u2013</i>Off</span></div>';
 h+='<div class="card atlscroll"><div class="atlg"><div></div>'+days.map(function(d,k){return '<div class="atldh'+(k?'':' atltd')+'"><span>'+esc(d.toLocaleDateString(undefined,{weekday:'short'}))+'</span><b>'+d.getDate()+'</b></div>'}).join('');
 ord.forEach(function(nm,i){h+='<button type="button" class="atlrn atlrnb" data-act="atl-gor" data-v="'+esc(nm)+'">'+esc(atlShort(nm))+'</button>'+days.map(function(d,k){var p=atlPos(atlIdx(d),i),c=p<2?'d':p<4?'n':'o';return '<div class="atlc atlc'+c+(k?'':' atltdc')+'">'+(c==='d'?'D':c==='n'?'N':'\u2013')+'</div>'}).join('')});
 h+='</div></div><div class="card"><div class="none" style="padding:12px 14px">2 days, 2 nights, then 4 rest days. The morning after the second night is the first day off. Each shift starts two days after the one before.</div></div>';
 h+='<div class="card">'+ord.concat(ATL_POOLS,[ATL_PLAN]).map(function(g){var n=ppl.filter(function(p){return p.group===g}).length,nc=ATL_POOLS.indexOf(g)>-1||g===ATL_PLAN;return '<button type="button" class="atlpool atlpoolb" data-act="atl-gor" data-v="'+esc(g)+'"><div><b>'+esc(g)+'</b>'+(nc?'<div class="atlmut">Listed here, not on the cycle</div>':'')+'</div><span class="atlpr"><span class="atltag">'+n+' '+(n===1?'person':'people')+'</span><span class="atlchev" aria-hidden="true">\u203A</span></span></button>'}).join('')+'</div>';
 if(atlMan())h+='<div class="actions"><button type="button" class="btn ghost" data-act="atl-go" data-v="cycle">Change the shift cycle</button></div>';return h}
function atlCycDraft(){if(S.atlCyc)return S.atlCyc;var s=atlSet();S.atlCyc={start:isDate(s.cycleStart)?s.cycleStart:iso(new Date()),order:atlOrder(),sup:s.supRole||'',asst:s.asstRole||'',reorder:false};return S.atlCyc}
function atlCycKeep(){var D=S.atlCyc;if(!D)return;var g=function(i){var e=document.getElementById(i);return e?e.value:null},v;
 if((v=g('atl-start'))!=null)D.start=v;if((v=g('atl-sup'))!=null)D.sup=v;if((v=g('atl-asst'))!=null)D.asst=v;
 var f=g('atl-first');if(f!=null&&D.order[0]!==f){var k=D.order.indexOf(f);if(k>0)D.order=D.order.slice(k).concat(D.order.slice(0,k))}}
function atlCycPlan(D){if(!isDate(D.start))return [];var b=new Date(D.start+'T12:00:00');return D.order.map(function(nm,i){var d=new Date(b);d.setDate(d.getDate()+2*i);return {nm:nm,d:d}})}
function atlCycleHtml(){if(!atlMan())return '<div class="card"><div class="none" style="padding:14px">Only an Atlantic manager can change the shift cycle.</div></div>';
 var D=atlCycDraft(),roles={};atlPeople().forEach(function(p){var r=String(p.role||'').trim();if(r)roles[r]=1});[D.sup,D.asst].forEach(function(r){if(r)roles[r]=1});var rl=Object.keys(roles).sort();
 var sel=function(id,val,opts,blank){return '<select id="'+id+'">'+(blank?'<option value="">'+blank+'</option>':'')+opts.map(function(o){return '<option'+(o===val?' selected':'')+'>'+esc(o)+'</option>'}).join('')+'</select>'};
 var h='<div class="card" style="padding:14px"><label class="atlf"><span class="atlfl">When does the cycle start?</span><input type="date" id="atl-start" value="'+esc(D.start)+'"></label>';
 h+='<label class="atlf"><span class="atlfl">Which shift starts its days on that date?</span>'+sel('atl-first',D.order[0],ATL_SHIFTS)+'</label>';
 var P=atlCycPlan(D);
 if(P.length)h+='<div class="atlplan"><div class="atlmut" style="margin:0 0 4px">The others follow, two days apart. First day shift:</div>'+P.map(function(x){return '<div class="atlprow"><b>'+esc(x.nm)+'</b><span>'+esc(x.d.toLocaleDateString(undefined,{weekday:'short',day:'numeric',month:'short'}))+'</span></div>'}).join('')+'</div>';
 if(D.reorder){h+='<div class="atlplan atlplan0"><div class="atlmut" style="margin:0 0 4px">Order of the shifts. Use the arrows to move one.</div>'+D.order.map(function(nm,i){return '<div class="atlorow"><span class="atlon">'+(i+1)+'</span><span class="atlonm">'+esc(nm)+'</span>'+(i>0?'<button type="button" class="atlmv" data-act="atl-cyc-mv" data-i="'+i+'" data-d="-1" aria-label="Move '+esc(nm)+' up">\u2191</button>':'<span class="atlmv0"></span>')+(i<3?'<button type="button" class="atlmv" data-act="atl-cyc-mv" data-i="'+i+'" data-d="1" aria-label="Move '+esc(nm)+' down">\u2193</button>':'<span class="atlmv0"></span>')+'</div>'}).join('')+'</div><button type="button" class="atllink" data-act="atl-cyc-ord">Done with the order</button>'}
 else h+='<button type="button" class="atllink" data-act="atl-cyc-ord">Change the order of the shifts</button>';
 h+='<label class="atlf"><span class="atlfl">Who is in charge (Role)</span>'+sel('atl-sup',D.sup,rl,'Choose a role')+'</label><label class="atlf"><span class="atlfl">If they are away (Role)</span>'+sel('atl-asst',D.asst,rl,'Choose a role')+'</label><div class="atlmut" style="margin-top:4px">Roles come from the roster. When the person in charge is on leave, the next Role steps in.</div></div><div class="actions atlsavebar"><button type="button" class="btn" data-act="atl-save">Save</button></div>';return h}
function atlPageHtml(){if(!S.atlLoaded)atlLoad();atlTick();var v=S.atlView||'';if(!S.atlLoaded)return '<div class="atlw"><div class="none" style="padding:14px">Loading\u2026</div></div>';var h=S.atlErr?'<div class="card"><div class="none" style="padding:12px 14px">Could not load the Atlantic settings. Showing what is known.</div></div>':'';return '<div class="atlw">'+h+(v==='certs'?atlCertsHtml():v==='certfilter'?atlCertFilterHtml():v==='roster'?atlRosterHtml():v==='shifts'?atlShiftsHtml():v==='cycle'?atlCycleHtml():atlHomeHtml())+'</div>'}
function atlTick(){if(S._atlT)return;S._atlT=setTimeout(function(){S._atlT=null;if(S.tab==='atl'&&!S.atlView&&!S.set&&!document.getElementById('hhdlg'))atlRender()},60000)}
async function atlSave(){if(!atlMan()||!S.db)return;atlCycKeep();var D=atlCycDraft();if(!isDate(D.start)){toast('Choose the day the cycle starts');return}
 if(D.order.length!==4||D.order.some(function(x,i){return ATL_SHIFTS.indexOf(x)<0||D.order.indexOf(x)!==i})){toast('Each shift must appear once in the order');return}
 var d={cycleStart:D.start,order:D.order.slice(),supRole:D.sup,asstRole:D.asst,by:(S.me&&S.me.email)||'',at:Date.now()};
 try{await S.db.doc('atlantic/settings').set(d,{merge:true});S.atlSet=Object.assign({},S.atlSet||{},d);toast('Shift cycle saved');atlBackStep()}catch(e){toast(e&&e.code==='permission-denied'?'This change was not allowed. Ask an Executive if you think it should be.':'Could not save. Check the connection and try again.')}}
function atlRender(){var b=document.getElementById('atl-body');if(!b)return;if(!atlOk()){b.innerHTML='<div class="atlw"><div class="none" style="padding:14px">You do not have access to Atlantic.</div></div>';return}
 b.innerHTML=atlPageHtml();var h=document.querySelector('#view-atl header h1');if(h&&h.textContent!==atlTitle())h.textContent=atlTitle();var g=document.getElementById('atl-gear');if(g)g.hidden=!(atlMan()&&!S.atlView);
 setTimeout(function(){try{topBarSync()}catch(e){}try{helpBtnSync()}catch(e){}},0)}
function atlEnter(){if(!atlOk()){goTab('home');return}if(!S._atlKeep){S.atlView='';S._atlFrom='';S.atlF='all';S.atlCf='all';S.atlQe=false;S.atlQeIds=null}S._atlKeep=false;atlRender()}
function atlBackStep(){if(S.atlView==='roster'){S.atlQe=false;S.atlQeIds=null}S.atlView=(S.atlView==='cycle'&&S._atlFrom==='shifts')?'shifts':S.atlView==='certfilter'?'certs':'';S._atlFrom='';atlRender();window.scrollTo(0,0)}
document.addEventListener('click',function(ev){var t=ev.target.closest&&ev.target.closest('[data-act^="atl-"]');if(!t)return;var a=t.dataset.act;
 if(a==='atl-back'){ev.preventDefault();if(S.atlView)atlBackStep();else appBack();return}
 if(a==='atl-gear'){ev.preventDefault();if(!atlMan())return;S._atlFrom=S.atlView||'';S.atlView='cycle';atlRender();window.scrollTo(0,0);return}
 if(a==='atl-go'){ev.preventDefault();S._atlFrom=S.atlView||'';S.atlView=t.dataset.v||'';atlRender();window.scrollTo(0,0);return}
 if(a==='atl-save'){ev.preventDefault();atlSave();return}});
/* the phone's back: one step back inside Atlantic before leaving the tab */
var _appBackAtl=appBack;appBack=function(){if(!S.set&&S.tab==='atl'&&S.atlView&&!S.menu&&!S.drw&&!document.getElementById('hhdlg')&&!document.getElementById('hhprompt')){atlBackStep();return true}return _appBackAtl.apply(this,arguments)};
/* the top-bar back goes through navCanBack/navBack (capture handler): an inner Atlantic page steps back one level first */
var _ncbAtl=navCanBack;navCanBack=function(){if(!S.set&&S.tab==='atl'&&S.atlView)return true;return _ncbAtl.apply(this,arguments)};
var _nbAtl=navBack;navBack=function(){if(!S.set&&S.tab==='atl'&&S.atlView){atlBackStep();return}return _nbAtl.apply(this,arguments)};
/* live: the roster changing redraws Atlantic */
var _renderAllAtl=renderAll;renderAll=function(){var r=_renderAllAtl.apply(this,arguments);try{if(!S.isErt&&S.tab==='atl')atlRender()}catch(e){}return r};
(function(){try{if(document.getElementById('atlcss'))return;var st=document.createElement('style');st.id='atlcss';st.textContent=ATL_CSS;document.head.appendChild(st)}catch(e){}})();

/* ===== 4.75 Atlantic step 2: Roster by rank, Quick edit (the main Roster's own boxes and saving), Role lock ===== */
function atlShiftPerson(p){var l=String(p&&p.location||'');return (l==='Atlantic'||l==='Atlantic / Pt.Lisas')&&ATL_SHIFTS.indexOf(p.group)>-1}
function atlCanQe(){return atlMan()&&!!S.db&&hp('profiles')}
function atlStatus(p){if(ATL_POOLS.indexOf(p.group)>-1)return ['Pool','atlpo'];var i=atlOrder().indexOf(p.group);if(i<0)return ['No shift','atlpo'];var o=atlNow();if(!o)return null;var pos=atlPos(atlIdx(o.sd),i);return pos<2?['On days','atlpd']:pos<4?['On nights','atlpn']:['Off duty','atlpo']}
var ATL_LOCQ=[['Atlantic','Atlantic'],['Atlantic / Pt.Lisas','Atlantic / Pt.Lisas'],['Pt.Lisas','Pt. Lisas (leaves Atlantic)'],['HQ','HQ (leaves Atlantic)'],['','Unassigned (leaves Atlantic)']];
function atlQsel(p,f,opts,lab){var cur=p[f]||'',o=opts.slice();if(!o.some(function(x){return x[0]===cur}))o.push([cur,cur||'Not set']);var dis=ATL_LF.indexOf(f)>-1&&atlLocked(p)&&!atlMan();return '<select class="qsel" data-qid="'+esc(p.id)+'" data-qf="'+f+'" aria-label="'+lab+' for '+esc(p.name)+'"'+(dis?' disabled':'')+'>'+o.map(function(x){return '<option value="'+esc(x[0])+'"'+(x[0]===cur?' selected':'')+'>'+esc(x[1])+'</option>'}).join('')+'</select>'}
function atlRosterList(){var ppl=atlPeople().slice(),f=S.atlF||'all',snap=S.atlQe&&S.atlQeIds;if(snap){var have={};ppl.forEach(function(p){have[p.id]=1});(S.people||[]).forEach(function(p){if(snap[p.id]!==undefined&&!have[p.id])ppl.push(p)})}
 if(f!=='all')ppl=ppl.filter(function(p){return p.group===f||(snap&&snap[p.id]===f)});return ppl}
function atlRowHtml(p){var still=atlPeople().some(function(x){return x.id===p.id}),av=avatar(p);
 if(S.atlQe){if(!still)return '<div class="atlr atlgone">'+av+'<div class="atlrm"><div class="atlrn2">'+esc(p.name)+'</div><div class="atlrem"><span>No longer in Atlantic</span><button type="button" class="mini" data-act="atl-undo" data-id="'+esc(p.id)+'">Undo</button></div></div></div>';
  var lb=function(t,x){return '<label class="atlql"><span>'+t+'</span>'+x+'</label>'};
  return '<div class="atlr atlrq"><div class="atlqhead">'+av+'<span class="atlrn2">'+esc(p.name)+'</span></div><div class="atlsels">'+lb('Role',atlQsel(p,'role',ROLE_OPTS.map(function(r){return [r,r||'No role']}),'Role'))+lb('Shift or pool',atlQsel(p,'group',GROUP_OPTS.map(function(g){return [g,g||'No shift']}),'Shift or pool'))+lb('Location',atlQsel(p,'location',ATL_LOCQ,'Location'))+'</div></div>'}
 var st=atlStatus(p);return '<button type="button" class="atlr" data-act="atl-open" data-id="'+esc(p.id)+'">'+av+'<span class="atlrm"><span class="atlrn2">'+esc(p.name)+'</span><span class="atlsub">'+esc((p.group||'No shift')+' \u2022 '+(locTxt(p.location)||p.location||''))+'</span></span>'+(st?'<span class="atlpill '+st[1]+'">'+st[0]+'</span>':'')+'</button>'}
function atlRosterHtml(){var s=atlSet(),list=atlRosterList(),qe=!!S.atlQe,f=S.atlF||'all',chips=[['all','All']].concat(atlOrder().map(function(g){return [g,atlShort(g)]})).concat(ATL_POOLS.map(function(g){return [g,g]})).concat([[ATL_PLAN,ATL_PLAN]]);
 var h='<div class="chips atlcx" role="group" aria-label="Show">'+chips.map(function(c){return '<button type="button" class="chip" data-act="atl-f" data-v="'+esc(c[0])+'" aria-pressed="'+(c[0]===f)+'">'+esc(c[1])+'</button>'}).join('')+'</div>';
 h+='<div class="atlqrow"><span class="atllab">Atlantic people \u2022 '+list.length+' shown</span>'+(atlCanQe()?'<button type="button" class="rqe'+(qe?' on':'')+'" data-act="atl-qe" aria-pressed="'+qe+'"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 20h4L19 9l-4-4L4 16z"/><path d="M13.5 6.5l4 4"/></svg><span>'+(qe?'Done':'Quick edit')+'</span></button>':'')+'</div>';
 if(qe)h+='<div class="atlhint">Quick edit is on: change Role, Shift or Location and it saves straight away. Tap Done when finished.</div>';
 if(!list.length)return h+'<div class="card"><div class="none" style="padding:14px">No Atlantic people'+(f==='all'?'':' in '+esc(f))+'. People show here when their Location on the Roster is Atlantic or Atlantic / Pt.Lisas.</div></div>';
 var lv={};if(!qe){try{atlTodayLeave().forEach(function(x){var id=String(x.staff||'');if(id.indexOf('a_')===0)lv[id.slice(2)]=x})}catch(e){}}
 var main=list.filter(function(p){return !lv[p.id]}),away=list.filter(function(p){return !!lv[p.id]}),byName=function(a,b){return String(a.name||'').localeCompare(String(b.name||''))};
 var sup=String(s.supRole||''),asst=String(s.asstRole||''),groups={},order=[];
 function key(p){var r=String(p.role||'').trim();return r&&r===sup?'1|Supervisors':r&&r===asst?'2|Assistant Supervisors':'3|ERTs'}
 main.forEach(function(p){var k=key(p);if(!groups[k]){groups[k]=[];order.push(k)}groups[k].push(p)});order.sort();
 order.forEach(function(k){var ps=groups[k].sort(byName);h+='<div><div class="atlgh"><span class="atllab">'+esc(k.split('|')[1])+'</span><span class="atltag">'+ps.length+'</span></div><div class="card atllist">'+ps.map(atlRowHtml).join('')+'</div></div>'});
 if(away.length)h+='<div><div class="atlgh"><span class="atllab">On leave</span><span class="atltag">'+away.length+'</span></div><div class="card atllist">'+away.sort(byName).map(function(p){return atlLeaveRow(p,lv[p.id])}).join('')+'</div></div>';
 return h}
document.addEventListener('click',function(ev){var t=ev.target.closest&&ev.target.closest('[data-act="atl-f"],[data-act="atl-qe"],[data-act="atl-open"],[data-act="atl-undo"]');if(!t)return;ev.preventDefault();var a=t.dataset.act;
 if(a==='atl-f'){S.atlF=t.dataset.v||'all';atlRender();return}
 if(a==='atl-qe'){if(!atlCanQe())return;S.atlQe=!S.atlQe;if(S.atlQe){var m={},o={};atlPeople().forEach(function(p){m[p.id]=p.group||'';o[p.id]=p.location||''});S.atlQeIds=m;S.atlQeOld=o}else{S.atlQeIds=null}atlRender();return}
 if(a==='atl-open'){open(t.dataset.id);return}
 if(a==='atl-undo'){var id=t.dataset.id,old=(S.atlQeOld||{})[id];if(old!==undefined)rosterQuickSave(id,'location',old);return}});
/* Atlantic lock (agreed 10 Oct): Location "Atlantic" (alone) plus Alpha, Bravo, Charlie or Delta locks Role, Shift and Location to
   people who manage Atlantic. Atlantic / Pt.Lisas, the pools and everything else stay open. Rules 4.11 enforce it too. */
var ATL_LF=['role','group','location'];
function atlLocked(p){return !!p&&String(p.location||'')==='Atlantic'&&ATL_SHIFTS.indexOf(p.group)>-1}
var ATL_LOCKMSG='Only someone who manages Atlantic can change the role, shift or location of a person on an Atlantic shift.';
function atlLockAsk(name){return hhConfirm('',{title:'Lock '+(name||'this person')+' to Atlantic?',body:'Saving puts them on an Atlantic shift. After that, only someone who manages Atlantic can change their role, shift or location, and you cannot undo this yourself.',ok:'Save',cancel:'Cancel'})}
var _rqsAtl=rosterQuickSave;rosterQuickSave=async function(id,f,v){var p=(S.people||[]).filter(function(x){return x.id===id})[0];
 if(p&&ATL_LF.indexOf(f)>-1&&!atlMan()){
  if(atlLocked(p)){toast(ATL_LOCKMSG);renderAll();return}
  var nl=f==='location'?v:p.location,ng=f==='group'?v:p.group;
  if(String(nl||'')==='Atlantic'&&ATL_SHIFTS.indexOf(ng)>-1){var ok=await atlLockAsk(p.name);if(!ok){renderAll();return}}}
 return _rqsAtl.apply(this,arguments)};
function atlLockBoxes(sel){if(atlMan())return;[].forEach.call(document.querySelectorAll(sel),function(e){var p=(S.people||[]).filter(function(x){return x.id===e.dataset.qid})[0];if(p&&atlLocked(p)){e.disabled=true;e.title=ATL_LOCKMSG}})}
