document.addEventListener('click',function(ev){var t=ev.target.closest&&ev.target.closest('[data-act^=pc-]');if(!t)return;var a=t.dataset.act;ev.preventDefault();ev.stopPropagation();
  if(a==='pc-open'){S.pcCycle='';openSettings('unpaid');return}
  if(a==='pc-step'){S.pcCycle=pcStep(S.pcCycle||pcCycleFor(iso(TODAY)),+t.dataset.v||0);renderSettings();return}
  if(a==='pc-xlsx'){pcDownload('xlsx');return}if(a==='pc-pdf'){pcDownload('pdf')}},true);
document.addEventListener('change',function(ev){var t=ev.target;if(!t||!t.classList||!t.classList.contains('pcsel'))return;var v=String(t.value||'').slice(0,7);if(!/^\d{4}-\d{2}$/.test(v))return;S.pcCycle=v;renderSettings()},true);
