/* ===== 4.56 Testing mode: records made while it is On are hidden from everyone else (rule 46) ===== */
/* One Proxy around the database object the app receives (window.claude.use('db')): it marks NEW records (add, or set on a document that does not exist yet) in the work collections below with byOwner:true while Testing mode is On, and drops every record marked byOwner from what anyone else is shown. Nothing else is touched. Leave requests, job letters and training are not in the list because their database rules accept only fixed fields. A batch or a transaction is not marked. If anything goes wrong the plain database is used. */
var TM_COLLS=['ert','staff','jobs','erlog','vehicles','proposals','staffleave'];
document.addEventListener('click',function(ev){var t=ev.target.closest&&ev.target.closest('[data-act=tm-set]');if(!t||!S.isOwner)return;ev.preventDefault();
  try{if(t.dataset.v==='yes')localStorage.setItem('hhsl_testmode','1');else localStorage.removeItem('hhsl_testmode')}catch(e){}
  tmPaint();toast(t.dataset.v==='yes'?'Testing mode On: new records are hidden from others':'Testing mode Off');if(S.set)renderSettings()},true);
setInterval(tmPaint,3000);

/* ===== 4.65 iPhone: headings drawn at their final size when a sheet opens; no page zoom except in the file viewers ===== */
/* iPhone and iPad are recognised by name (not only by a style test), so the 16px field rule is certain to apply there */
try{if(/iPhone|iPad|iPod/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1))document.documentElement.classList.add('ios')}catch(e){}
/* uniSizes() used to run up to 0.7 s after a sheet opened, so a big heading was drawn first and then shrank. Now it runs in the same task as the change. */
function uniWatch(){try{['setsheet','sheet','crewsheet','logsheet','pimpsheet'].forEach(function(id){var el=document.getElementById(id);if(!el||el._uniW)return;el._uniW=true;new MutationObserver(function(){try{uniSizes(el)}catch(e){}}).observe(el,{childList:true,subtree:true})})}catch(e){}}
uniWatch();setTimeout(uniWatch,800);setInterval(uniWatch,3000);
/* No pinch or double-tap zoom anywhere, except while a file viewer (PDF, Excel, Word view) is open. */
var ZOOM_ON='width=device-width,initial-scale=1,maximum-scale=5,viewport-fit=cover',ZOOM_OFF='width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no,viewport-fit=cover';
function zoomSet(on){try{if(window.__zoomOk===on)return;window.__zoomOk=on;var m=document.querySelector('meta[name=viewport]');if(m)m.setAttribute('content',on?ZOOM_ON:ZOOM_OFF);document.documentElement.classList.toggle('zoomok',on)}catch(e){}}
function zoomCheck(){zoomSet(!!(document.documentElement.classList.contains('xlopen')||document.getElementById('pv-host')))}
['gesturestart','gesturechange','gestureend'].forEach(function(t){document.addEventListener(t,function(e){if(!window.__zoomOk)e.preventDefault()},{passive:false})});
try{new MutationObserver(zoomCheck).observe(document.documentElement,{attributes:true,attributeFilter:['class']});new MutationObserver(zoomCheck).observe(document.body,{childList:true,subtree:true})}catch(e){}
window.__zoomOk=false;zoomCheck();

/* ===== 4.93 Payroll (registered tab) ===== */
/* ===== 4.93 (Akeem, 13 Oct 2026): PAYROLL, part 1. A department tab (payroll manager = Manage, payroll staff = View; Executives always).
   Time sheets: every ERT with Client Medic, HHSL Compound or other job days in the month, one line per job, tick boxes, one Excel file with a tab
   per person (alphabetical). Payroll manager can correct, add or remove lines (payroll's copy only: collection payroll, History, nobody is told,
   the ERT's records are never changed). Unpaid days: every unpaid day with its reason, read-only. No pay amounts anywhere.
   Part 2 (V4.94): the automatic pull at 8 a.m. on the 2nd, its notifications and Pull now. ===== */
function payRegister(){if(window.__payReg)return;window.__payReg=1;try{uniRegisterTab({key:'payroll',name:'Payroll',desc:'Time sheets and unpaid days for payroll (no pay amounts)',
  help:{about:'Every ERT who recorded Client Medic, HHSL Compound or other job days in a month, their time sheets to download, and every unpaid day with its reason. No pay amounts.',
    can:[['See each ERT\u2019s days for a month and download one, some or all time sheets (one Excel file, a tab per person)'],['See every unpaid day and why it is unpaid'],['Payroll manager: correct, add or remove a time sheet line before downloading (payroll\u2019s copy only)',1]],
    tips:['Days lock at midnight going into the 2nd; from then the month is final.','Corrections are kept in History. The ERT\u2019s own records never change.','Unpaid days are read-only here: they come from the leave records.']},
  helpKey:'set_payroll',collections:[{id:'payroll',name:'Payroll copies (corrected time sheet lines)'}],files:[['payroll','Payroll time sheets and unpaid days']],
  guide:'Payroll: the time sheets of every ERT who recorded days, and unpaid days with their reasons, with no pay amounts. View sees and downloads; Manage (the payroll manager) can correct time sheet lines.',
  updates:'none: nothing happens that others need to know yet (the automatic pull and its notifications come with part 2)'});}catch(e){window.__payReg=0}}

