/* Version 2.80: one Back for the whole app.
   Tapping something that opens another screen remembers where you were (tab, open panels, scroll).
   Back on the screen you landed on returns you there; Done closes everything you opened since you started. */
var NAV={j:[],evt:null,busy:false,pend:null};
document.addEventListener('click',function(ev){var b=ev.target.closest&&ev.target.closest('button');if(!b)return;
  if(b.closest('nav.tabs')||b.closest('.sidenav')||['side-go','side-set','ert-tab'].indexOf(b.dataset.act)>-1){NAV.j=[];NAV.evt=null;return}
  if(navIsDone(b)&&!navEditing()){ev.preventDefault();ev.stopImmediatePropagation();navDone();return}
  if(navIsBack(b)){NAV.evt={back:true,t:Date.now()};var top=NAV.j[NAV.j.length-1],cur=navSigX();
    if(top&&!top.sig&&cur!==top.from.sig)top.sig=cur;
    if(top&&top.sig===cur){NAV.pend=top;setTimeout(function(){if(NAV.pend!==top)return;NAV.pend=null;if(navSigX()!==top.sig){var i=NAV.j.indexOf(top);if(i>-1)NAV.j.splice(i);navRestore(top.from)}else navDoneSync()},10)}
    else setTimeout(function(){navPrune();navDoneSync()},150);return}
  NAV.evt={t:Date.now(),from:navCapture(),pushed:false};
  setTimeout(function(){navPrune();navDoneSync()},260)},true);
(function(){var t=null;try{new MutationObserver(function(){if(NAV.syncing||!NAV.j.length)return;clearTimeout(t);t=setTimeout(function(){if(!document.querySelector('.navdone'))navDoneSync()},60)}).observe(document.body,{childList:true,subtree:true})}catch(e){}})();
