/* ===== 4.89 (Akeem, 12 Oct 2026): design template part 1 on the rest of the app. Statuses that were plain text are pills (certificates
   and documents on a person's profile, the Crews job footer, training registrations, the leave request Status line); the Atlantic Back
   button goes back to where you came from (or Home); pop-up titles 22 px; short "nothing here" messages become the compact empty state
   (a neutral icon and one bold line, never a tick), app-wide. ===== */
/* the leave request Status line: the status as a pill, the reference after it */
function v489StatusCell(v){var p=String(v||'').split(' \u2022 ');var lab=p.shift();return stp(lab)+(p.length?' <span class="v489ref">'+esc(p.join(' \u2022 '))+'</span>':'')}
/* Atlantic: Back steps out of an inner view first, then goes to the tab you came from (or Home) */
function v489AtlBack(){try{if(S.atlView){atlBackStep();return}var t=S._v489Prev;if(!t||t==='atl')t='home';goTab(t)}catch(e){try{goTab('home')}catch(x){}}}
if(typeof goTab==='function'){var _v489Go=goTab;goTab=function(t){var from=S.tab;var r=_v489Go.apply(this,arguments);try{if(t==='atl'&&from&&from!=='atl')S._v489Prev=from}catch(e){}return r}}
window.addEventListener('click',function(ev){if(S.tab!=='atl'||S.set||S.sel||S.edit)return;var t=ev.target.closest&&ev.target.closest('#tb-back,#atl-hb,[data-act="atl-back"]');if(!t)return;ev.preventDefault();ev.stopPropagation();ev.stopImmediatePropagation();v489AtlBack()},true);
/* the compact empty state for short "nothing here" messages, wherever they appear */
var V489_EMPTY=/^(nothing|no |none|nobody|not yet|no one)[^<]{0,70}$/i;
function v489Icon(t){t=t.toLowerCase();if(/leave|holiday|absen/.test(t))return 'cal';if(/ticket|letter|document|file|certificate|report|signature/.test(t))return 'doc';if(/people|staff|ert|person|nobody|no one|member/.test(t))return 'user';return 'inbox'}
function v489Empty(root){try{var list=[];if(root.nodeType!==1)return;if(root.matches&&root.matches('.none'))list.push(root);if(root.querySelectorAll)[].push.apply(list,root.querySelectorAll('.none'));
  list.forEach(function(el){if(el.dataset.v489||el.children.length)return;var tx=String(el.textContent||'').trim();if(!tx||tx.length>80||!V489_EMPTY.test(tx))return;el.dataset.v489='1';
    if(el.closest('select,option,.v487pop,.nmcard,#hhdlg,.lvkv,.setgrid,.rpbars'))return;el.classList.add('v489e');el.innerHTML=tplEmpty(v489Icon(tx),tx.replace(/\.$/,''),'')})}catch(e){}}
(function(){try{if(typeof MutationObserver!=='function'||typeof tplEmpty!=='function')return;var mo=new MutationObserver(function(muts){for(var i=0;i<muts.length;i++){var ad=muts[i].addedNodes;for(var j=0;j<ad.length;j++){var n=ad[j];if(n.nodeType===1&&!(n.classList&&n.classList.contains('tplempty')))v489Empty(n)}}});mo.observe(document.body,{childList:true,subtree:true});v489Empty(document.body)}catch(e){}})();

/* ===== 4.91 (Akeem, 12 Oct 2026): who is told what. Leave the office records for someone tells that person (staff: the new server alert
   "lvrec"; Atlantic people recorded by an Executive: the ERT push). Letters the office creates for someone who did not ask in the app send no
   "waiting" and no "ready"/"declined" alert (the Share is how the person gets it); only "revoked" still tells them. A Share button on an issued
   letter opens the phone's own share menu (WhatsApp, email...). ===== */
function v491LvText(type,start,end){var t=type==='vac'?'Vacation':type==='sick'?'Sick leave':'Casual leave',a=typeof lvShort==='function'?lvShort(start):start,b=typeof lvShort==='function'?lvShort(end):end;return 'Leave was recorded for you: '+t+', '+(!end||end===start?a:a+' to '+b)}
/* the Share button on an issued letter */
