async function v491Share(id){var x=jlFind(id);if(!x||x.status!=='issued')return;if(typeof pDl==='function'&&!pDl('jobletter')){toast('Downloading is not allowed for this sign-in.');return}
  var name=(x.ref||'Job letter')+' - '+(typeof pSafe==='function'?pSafe(x.name||''):String(x.name||''))+'.pdf',blob=null;
  try{var m=await jlModel(x,false);var b=pdfBuild(m);blob=(b instanceof Blob)?b:new Blob([b],{type:'application/pdf'})}catch(e){toast('Could not make the letter. Try again.');return}
  try{var file=new File([blob],name,{type:'application/pdf'});if(navigator.canShare&&navigator.canShare({files:[file]})){await navigator.share({files:[file],title:'Job letter',text:'Job letter for '+(x.name||'')});return}}catch(e){if(e&&e.name==='AbortError')return}
  try{await pSave(blob,name,'jobletter',false);toast('This phone cannot share files from the app, so the letter was downloaded. Send it from your Downloads.')}catch(e){toast(e&&e.code==='declined'?'Downloading is not allowed for this sign-in.':'Could not share the letter. Try again.')}}
