/* ===== 4.94 (Akeem, 13 Oct 2026): PAYROLL part 2. The pull record (payrollpull/<ym>, made at 8 a.m. Trinidad time on the 2nd by the server, or by Pull now),
   "Pulled on ..." on the Time sheets page, "Changed after the pull" on a person whose days changed afterwards, Pull now, and the bell entries
   (ERT: "Your October days were sent to payroll"; staff: "Your unpaid days for April (2: Sick) were sent to payroll"; payroll: "October is ready"). ===== */
/* the Updates bell: the staff For you line, and the Payroll department's line (only people who can open the Payroll tab see it) */
try{UPD_REG.pyn={kind:'foryou'};UPD_REG.pyp={kind:'act',tab:'payroll'}}catch(e){}
function payFp(list){var h=5381,str=list.map(function(e){return [String(e.date||'').slice(0,10),e.type,e.start||'',e.end||'',e.location||''].join('|')}).sort().join(';');for(var i=0;i<str.length;i++)h=((h<<5)+h+str.charCodeAt(i))|0;return (h>>>0).toString(36)}
function payRaw(pid,ym){return (payEntries(ym)||[]).filter(function(e){return e.ertId===pid&&String(e.date||'').slice(0,7)===ym&&(e.type==='medic'||e.type==='yard'||e.type==='other')&&e.status!=='declined'})}
function payPulled(ym){return (S._payPull||{})[ym]||null}
function payPullWhen(d){try{var x=new Date(Date.parse(d)-4*3600e3),h=x.getUTCHours(),m=x.getUTCMinutes();return x.getUTCDate()+' '+PC_MONTHS[x.getUTCMonth()].slice(0,3)+' '+x.getUTCFullYear()+', '+(h%12||12)+':'+('0'+m).slice(-2)+(h<12?' a.m.':' p.m.')}catch(e){return ''}}
function payFetchPull(ym){S._payPull=S._payPull||{};S._payPullGot=S._payPullGot||{};if(S._payPullGot[ym])return;S._payPullGot[ym]=1;
  (async function(){try{var d=await S.db.doc('payrollpull/'+ym).get();if(d.exists)S._payPull[ym]=d.data()}catch(e){}
    if(!(S._payPull[ym]&&S._payPull[ym].autoAt))payAutoPull(ym);if(S.set&&S.setPage==='payroll')renderSettings()})()}
/* the first Executive or payroll manager to open Payroll after 8 a.m. on the 2nd starts the pull if the server job did not (the server checks the time and the person) */
function payDue(ym){var n=pcStep(ym,1);return Date.now()>=Date.UTC(+n.slice(0,4),+n.slice(5,7)-1,2,12,0,0)}
function payAutoPull(ym){if(S._payAuto&&S._payAuto[ym])return;if(!(payMan()||S.isExec||S.isOwner)||!payDue(ym)||ym!==payYm0())return;S._payAuto=S._payAuto||{};S._payAuto[ym]=1;payRunPull(ym,true,'auto')}
async function payRunPull(ym,quiet,mode){try{var tok=await window.HHSL_getToken();var r=await fetch('/.netlify/functions/payroll-pull',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({idToken:tok,action:'run',ym:ym,mode:mode||'manual'})});var j=await r.json().catch(function(){return {}});
  if(!r.ok){if(!quiet)toast(j.error||'Could not pull. Try again.');return false}
  if(j.skipped&&!quiet)toast(/already/.test(j.skipped)?payMon(ym)+' was already pulled automatically':'Not time yet');
  S._payPullGot[ym]=0;payFetchPull(ym);if(!quiet&&!j.skipped)toast(payMon(ym)+' pulled: '+(j.erts||0)+' ERTs, '+(j.days||0)+' days'+(j.silent?'. Nobody was told.':''));return true}catch(e){if(!quiet)toast('Could not pull. Check your signal.');return false}}
/* the Time sheets page tells when it was pulled and flags changes after it */
var _payTsHtml=payTsHtml;payTsHtml=function(){payFetchPull(payP().ym);var h=_payTsHtml.apply(this,arguments);var P=payP(),pl=payPulled(P.ym);
  if(pl)h=h.replace(/<div class="paysub">(Locked at midnight[^<]*|Still open[^<]*)<\/div>/,function(a,t){var w='Last pulled on '+esc(payPullWhen(pl.at))+((pl.pulls||1)>1?' (pull '+pl.pulls+')':''),e=/\.$/.test(w)?'':'.';return '<div class="paysub">'+(/^Locked/.test(t)?w+e+' Final.':t+' '+w+e)+'</div>'});
  return h};
var _payPeople=payPeople;payPeople=function(ym){var L=_payPeople.apply(this,arguments);if(!L)return L;var pl=payPulled(ym);if(!pl)return L;var fps=pl.fps||{};L.forEach(function(p){var was=fps[p.pid];if(was==null)p.afterPull='Added after the pull';else if(was!==payFp(payRaw(p.pid,ym)))p.afterPull='Changed after the pull'});return L};
var _payRowPill=null;
document.addEventListener('DOMContentLoaded',function(){});
/* Pull now (Executives, and the payroll manager once it is time): in the download pop-up while the month has not been pulled */
var _payDlMenu=payDlMenu;payDlMenu=function(){var P=payP();if(P.tab==='up'||(P.selOn&&Object.keys(P.sel).some(function(k){return P.sel[k]})))return _payDlMenu.apply(this,arguments);
  var L=payPeople(P.ym)||[],can=(S.isExec||S.isOwner)||payMan(),np=true;var rows=[{t:'Download all ('+L.length+')',s:'One Excel file, a tab per person'},{t:'Choose people',s:'Tick the people you want'}];if(can&&np)rows.push({t:(payPulled(P.ym)?'Pull '+payMon(P.ym)+' again':'Pull '+payMon(P.ym)+' now'),s:'Records the month as it is now. Nobody is told.'});
  v487Pop('Download time sheets',rows,function(i){if(i===0)payDownload(L);else if(i===1){P.selOn=true;renderSettings()}else hhConfirm('Pull '+payMon(P.ym)+'?\n\nThis records '+payMon(P.ym)+' as it is now. Nobody is told. You can pull again at any time; the latest pull is the one that counts.').then(function(ok){if(ok)payRunPull(P.ym,false)})})};
