function payMarkRows(){try{if(!S.set||S.setPage!=='payroll'||!S.pay||S.pay.tab!=='ts'||S.pay.person)return;var L=payPeople(S.pay.ym)||[];[].forEach.call(document.querySelectorAll('#set-in .payrow'),function(b){var pid=b.dataset.v,p=L.filter(function(x){return x.pid===pid})[0];if(!p||!p.afterPull||b.querySelector('.pp-after'))return;var w=b.querySelector('.paypills');if(w){var s=document.createElement('span');s.className='paypill pp-soon pp-after';s.textContent=p.afterPull;w.insertBefore(s,w.firstChild)}})}catch(e){}}
