var V500_POPS=['inpk','v500w']; /* real pop-ups only (never full screens such as Settings, which is also marked as a dialog); add a pop-up's id here to keep it above a page that is raised again */
function v500IsPop(o){try{if(!o||o.nodeType!==1||o.parentNode!==document.body||o.hidden||V500_POPS.indexOf(o.id)<0)return false;var cs=getComputedStyle(o);return cs.display!=='none'&&cs.visibility!=='hidden'}catch(e){return false}}
