var V500_CSS="/* 5.00 Not registered chip / Register button (amber = the Not registered status colour) and the Send a link pop-up */\n.v500chip,.v500reg{display:inline-flex;align-items:center;gap:6px;height:26px;padding:0 13px;border-radius:999px;border:0;background:color-mix(in srgb,var(--soon) 18%,transparent)!important;color:color-mix(in srgb,var(--soon) 62%,var(--ink))!important;font:800 12.5px/1 inherit;font-family:inherit;white-space:nowrap;cursor:pointer;flex:none}\n.v500chip svg,.v500reg svg{flex:none}\n.v500w{position:fixed;inset:0;z-index:2147480900;display:flex;align-items:center;justify-content:center;padding:16px}\n.v500bg{position:absolute;inset:0;background:rgba(8,20,28,.5)}\n.v500card{position:relative;width:100%;max-width:380px;max-height:calc(100% - 24px);overflow:auto;background:var(--surface);color:var(--ink);border-radius:18px;box-shadow:0 18px 50px rgba(0,0,0,.35);padding:20px 18px 14px}\n.v500card h3{margin:0 0 4px;font-size:22px;font-weight:800}.v500nm{font-size:15px;font-weight:700;margin:0 0 2px}.v500lead{font-size:13px;color:var(--muted);margin:0 0 12px;line-height:1.4}\n.v500card label{display:block;font-size:14px;font-weight:600;color:var(--muted);margin:0 0 4px}\n.v500card input{width:100%;box-sizing:border-box;height:44px;border:1px solid var(--line);border-radius:10px;background:var(--soft);color:var(--ink);font-size:16px;padding:0 12px;margin:0 0 10px}\n.v500warn{background:color-mix(in srgb,var(--soon) 14%,transparent);color:color-mix(in srgb,var(--soon) 62%,var(--ink));border-radius:10px;padding:8px 10px;font-size:12.5px;font-weight:600;margin:2px 0 12px}\n.v500btns{display:grid;gap:8px}.v500btns .btn{width:100%;min-height:48px;margin:0;display:flex;align-items:center;justify-content:center;text-decoration:none}\n\n";(function(){try{if(document.getElementById('v500-css'))return;var st=document.createElement('style');st.id='v500-css';st.textContent=V500_CSS;document.head.appendChild(st)}catch(e){}})();

