function v502EmpEdit(p){return '<div class="card v502emp"><h3>Employment</h3><div class="f"><label for="i-joined">Date joined the company</label><input id="i-joined" data-info="joined" type="date" value="'+esc(String((p&&p.joined)||'').slice(0,10))+'"></div>'+
    (p&&p.id?v502CtrHtml(p,true):'')+'<div class="none">Job letters use Date joined. Contract dates are kept on the Atlantic tab.</div></div>'}
