/* ===== 5.04 (Akeem, 14 Oct 2026): job card status ladder from the shift times, strip colours, chip with word and date (option B).
   A shift runs from the crew start time (Day 07:00, Night 19:00 unless the crew has its own) to its end time, or 12 hours later when none is typed.
   Ladder for a job that is not completed: Upcoming (tomorrow or later), Today (a shift starts later today), In progress (a shift is running),
   Finished (the last shift ended earlier today), Yesterday (the last shift ended yesterday), Overdue (before that). ===== */
function v504Iso(d){var m=d.getMonth()+1,x=d.getDate();return d.getFullYear()+'-'+(m<10?'0':'')+m+'-'+(x<10?'0':'')+x}
function v504At(day,hm){var p=/^(\d{1,2}):(\d{2})/.exec(String(hm||''));var h=p?+p[1]:7,m=p?+p[2]:0;var q=day.split('-');return new Date(+q[0],+q[1]-1,+q[2],h,m,0,0)}
function v504Windows(j){var ws=[];try{(j.crews||[]).forEach(function(c){var st=c.startTime||(c.shift==='Night'?'19:00':'07:00');var days=[];try{days=isMulti(j)?(crewDays(j,c)||[]):jobDays(j)}catch(e){}
    if(!days.length)days=jobDays(j);days.forEach(function(d){var a=v504At(d,st),b;if(c.endTime){b=v504At(d,c.endTime);if(b<=a)b=new Date(b.getTime()+864e5)}else b=new Date(a.getTime()+432e5);ws.push([a,b])})});
  if(!ws.length&&isDate(j.start)){jobDays(j).forEach(function(d){var a=v504At(d,'07:00');ws.push([a,new Date(a.getTime()+432e5)])})}}catch(e){}return ws}
function v504Phase(j,now){if(!j||j.done||!isDate(j.start))return '';now=now||new Date();var ws=v504Windows(j);if(!ws.length)return '';
  var today=v504Iso(now),yest=v504Iso(new Date(now.getTime()-864e5)),last=0,run=false,later=false;
  ws.forEach(function(w){if(+w[1]>last)last=+w[1];if(w[0]<=now&&now<w[1])run=true;if(w[0]>now&&v504Iso(w[0])===today)later=true});
  if(now>=last){var d=v504Iso(new Date(last));return d===today?'fin':d===yest?'yes':'over'}
  return run?'act':later?'tod':'up'}
function v504Cls(j){var p=v504Phase(j);return p?' jp-'+p:''}
var V504_WORD={up:['Upcoming','fut'],tod:['Today','tod'],act:['In progress','act'],fin:['Finished','yes'],yes:['Yesterday','yes'],over:['Overdue','overdue']};
var V504_CSS="html body #view-crews .jbf .jst.fut{background:color-mix(in srgb,var(--ink) 8%,transparent)!important;color:color-mix(in srgb,var(--ink) 62%,transparent)!important}\n"+
"html body #view-crews .jbf .jst.tod{background:color-mix(in srgb,var(--brand) 14%,transparent)!important;color:var(--brand)!important}\n"+
"html body #view-crews .jbf .jst.yes{background:color-mix(in srgb,var(--soon) 18%,var(--surface))!important;color:color-mix(in srgb,var(--soon) 62%,var(--ink))!important}\n"+
"html body .jcard.jp-up,html body #crew-list .jcard.jp-up{--jce:#9AA6B0}\nhtml body .jcard.jp-tod,html body #crew-list .jcard.jp-tod{--jce:var(--brand)}\nhtml body .jcard.jp-act,html body #crew-list .jcard.jp-act{--jce:#0E7CC3}\n"+
"html body .jcard.jp-fin,html body #crew-list .jcard.jp-fin,html body .jcard.jp-yes,html body #crew-list .jcard.jp-yes{--jce:var(--soon)}\nhtml body .jcard.jp-over,html body #crew-list .jcard.jp-over{--jce:var(--exp)}\n"+
".jgh-yes{color:color-mix(in srgb,var(--soon) 70%,var(--ink))}\n"+
"html body .jcard .jc-when,html body #crew-list .jcard .jc-when{background:color-mix(in srgb,var(--ink) 7%,transparent)!important;color:color-mix(in srgb,var(--ink) 70%,transparent)!important}\n";
(function(){try{if(document.getElementById('v504-css'))return;var st=document.createElement('style');st.id='v504-css';st.textContent=V504_CSS;document.head.appendChild(st)}catch(e){}})();

/* ===== 5.05 (Akeem, 14 Oct 2026): turnarounds, Repeat job on New Job, Yesterday heading.
   A turnaround lives on its jobs (job.ta = {id, site, start}); no new collection, no new rules: whoever may edit jobs may set it.
   Tick "Turn Around (shutdown)" on day 1 to start one; a job repeated from it (or answered "Yes, part of it") joins it.
   It stays Active through the next 2 WORKING days after its last job day (Saturday, Sunday and the app's public holidays,
   S.erc.holidays, are not counted) and is Concluded after that; its end date is the last job day. One active turnaround per site.
   The data a later Reports page needs is kept on the jobs: site, first day, every job day, job numbers, crews and people per day. ===== */
function v505Hol(k){try{return ((S.erc&&S.erc.holidays)||[]).some(function(x){return x&&x.d===k})}catch(e){return false}}
function v505Work(k){var d=pd(k);if(!d)return true;var w=d.getDay();return w!==0&&w!==6&&!v505Hol(k)}
function v505GraceEnd(last){var k=last,n=0,g=0;while(n<2&&g<60){k=addDays(k,1);g++;if(v505Work(k))n++}return k}
function v505Site(j){return String((j&&j.ta&&j.ta.site)||jobClient(j)||siteText(j)||'').toUpperCase().trim()}
function v505JSite(j){return String(jobClient(j)||siteText(j)||'').toUpperCase().trim()}
function v505All(today){today=today||iso(TODAY);var m={};
  (S.jobs||[]).forEach(function(j){if(!j||!j.ta||!j.ta.id||!isDate(j.start)||j.archived)return;var x=m[j.ta.id]||(m[j.ta.id]={id:j.ta.id,site:v505Site(j),start:j.ta.start||j.start,jobs:[],days:{},first:'',last:''});
    x.jobs.push(j);jobDays(j).forEach(function(d){x.days[d]=(x.days[d]||0)+1});if(!x.first||j.start<x.first)x.first=j.start;var l=isDate(j.end)?j.end:j.start;if(!x.last||l>x.last)x.last=l});
  Object.keys(m).forEach(function(k){var x=m[k];x.dayList=Object.keys(x.days).sort();x.n=x.dayList.length;x.graceEnd=v505GraceEnd(x.last);x.active=today<=x.graceEnd;
    x.jobs.sort(function(a,b){return String(b.start).localeCompare(String(a.start))||String(b.created||'').localeCompare(String(a.created||''))});x.latest=x.jobs[0]});
  return m}
function v505Active(today){var m=v505All(today);return Object.keys(m).map(function(k){return m[k]}).filter(function(x){return x.active}).sort(function(a,b){return a.site.localeCompare(b.site)})}
function v505DayNo(x,d){return x.dayList.filter(function(k){return k<=d}).length}
