function v507PopChip(pop){var q='button.cfst.cftap';['j','c','p','d'].forEach(function(a){if(pop.dataset[a]!=null)q+='[data-'+a+'="'+String(pop.dataset[a]).replace(/"/g,'\\"')+'"]'});try{return document.querySelector(q)}catch(e){return null}}
