function v509Fld(id,label,opts,cur,dis){return '<label class="v508lab" for="'+id+'">'+label+'</label><select id="'+id+'" class="v508sel"'+(dis?' disabled':'')+'>'+opts.map(function(o){return '<option value="'+esc(o[0])+'"'+(o[0]===cur?' selected':'')+'>'+esc(o[1])+'</option>'}).join('')+'</select>'}
