 "#view-atl .atlrm>span.atlrn2{font-size:15px!important;font-weight:600!important}.smn b{font-size:15px!important}.lvrow .main .name{font-size:15px!important}#view-roster #roster-list .rqrow .name{font-size:15px!important}.acctmain b{font-size:15px!important}";
