/* ===== Sick Leave Record (office-added sick leave): a RECORD that the person asked the office to put them on sick leave, signed by the manager ===== */
async function lvRecPdfModel(r,draft){var B=[],logo=null;try{logo=await pLoadImg(typeof LOGO_IMG!=='undefined'?LOGO_IMG:'')}catch(e){}
  var sick=r.type!=='vac'&&r.type!=='other',wd=r.shift?' shift day':' working day',tn=r.type==='vac'?'Vacation':r.type==='other'?'Casual':'Sick',days=+r.days||0,dw=lvWords(days)+wd+(days===1?'':'s'),dt=lvLong(String(r.decidedAt||r.at||new Date().toISOString()).slice(0,10)),asked=parseFloat(r.daysAsked);
  B.push({t:'head',name:'HHSL Safety Systems Limited',title:'Office & Training Centre \u2022 LP #31 Pacific Avenue, Point Lisas Industrial Estate, Couva, Trinidad W.I.',photo:logo,style:'classic'});
  var meta=[['Date',dt],['Employee',[r.name,r.title].filter(Boolean).join(', ')]];if(r.empNo)meta.push(['Employee no.',r.empNo]);
  meta.push(['Recorded by',[r.decidedByName,r.decidedTitle?noOwnerTitle(r.decidedTitle):''].filter(Boolean).join(', ')||'The office'],['Reference',r.ref||(draft?'Given when recorded':'')]);B.push({t:'kv',rows:meta});
  B.push({t:'h2',x:tn+' Leave Record'+(r.cancelled?' (Cancelled)':r.amended?' (Amended)':'')});
  B.push({t:'rp',runs:sick?[[r.name,1],[' contacted the office on '],[dt,1],[' and asked to be put on sick leave.']]:[[r.name,1],['\u2019s '+tn.toLowerCase()+' leave was recorded by the office on '],[dt,1],['.']]});
  var kv=(sick?[['Complaint given',String(r.complaint||'').trim()||'Not stated'],['Days asked for',asked>0?lvWords(asked)+wd+(asked===1?'':'s'):'Not stated']]:[]).concat([['Booked',lvLong(r.start)+(r.end&&r.end!==r.start?' to '+lvLong(r.end):'')+' ('+dw+')'],['Expected back',r.ret?lvLong(r.ret):'\u2014'],]).concat(sick?[['Medical certificate',days>2?'Required on return (more than 2'+wd+'s)':'Not needed (2'+wd+'s or less)']]:[]);
  B.push({t:'kvbox',rows:kv,lw:130});
  if(sick&&r.appNeeded!==false)B.push({t:'rp',runs:[[r.name,1],[' is required to submit a sick leave application on returning to work.']]});
  var asig=null;if(r.decSig){try{asig=await pLoadImg(r.decSig)}catch(e){}}
  B.push({t:'office',decision:(sick?'RECORDED':'APPROVED')+(r.unpaidDays?' \u2022 '+r.unpaidDays+' of '+r.days+(r.days==1?' day':' days')+' without pay':''),tone:'ok',sig:asig,who:r.decidedByName?(r.decidedByName+(r.decidedTitle?', '+noOwnerTitle(r.decidedTitle):'')):'',when:r.decidedAt?('Recorded electronically, '+lvShort(r.decidedAt.slice(0,10))+', '+r.decidedAt.slice(11,16)+' UTC'):''});
  B.push({t:'audit',x:'Recorded in HHSL Command by '+(r.decidedByName||'the office')+(r.decidedBy?' ('+r.decidedBy+')':'')+(r.decidedAt?' on '+lvShort(r.decidedAt.slice(0,10)):'')+', at the request of '+r.name+'. This record was made by the office and is not signed by the employee.'+(r.ref?' Reference '+r.ref+'.':'')+(r.amendNote?' '+r.amendNote:'')});
  return {title:'Sick Leave Record',footer:'HHSL Safety Systems Limited \u2022 T: (868) 679-1234 or 679-3354 \u2022 hhslservices@hhslsafety.com',blocks:B,style:{accent:'14506B'}}}
