function v517TypeHtml(word){var k=v517TypeKey(word),c=v517Col(k);return '<span class="v517tp" style="color:'+c+'"><i class="lvdot" style="background:'+c+'" aria-hidden="true"></i>'+v512Esc(word)+'</span>'}
