/* ---- the send box (rule 116): like the profile update link ---- */
function v518Pretty(d){d=String(d||'');if(d.length===11&&d.indexOf('1868')===0)return '+1 868 '+d.slice(4,7)+' '+d.slice(7);return '+'+d}
function v518Check(v){v=String(v||'').trim();if(!v)return {ok:false};if(/@/.test(v))return pdMailOk(v)?{ok:true,via:'email',to:v.toLowerCase(),show:v.toLowerCase()}:{ok:false};
 var p=pdPhone(v);return p.ok?{ok:true,via:'whatsapp',to:p.digits,show:v518Pretty(p.digits)}:{ok:false}}
var V518_HINT='A local number needs 7 digits (868 is added). A number abroad needs the country code. Or type an email.';
v517Digits=function(ph){var p=pdPhone(ph);return p.ok?p.digits:String(ph||'').replace(/\D/g,'')};
async function v518SendDlg(id){var x=v512Find(id);if(!v517CanSend(x))return;var P=v512Person(x),C=v517Contact(x),saved=[];
 try{if(C.phone){var pp=pdPhone(C.phone);if(pp.ok)saved.push({v:'wa',t:'WhatsApp',s:v518Pretty(pp.digits),via:'whatsapp',to:pp.digits,show:v518Pretty(pp.digits)})}if(C.email&&pdMailOk(C.email))saved.push({v:'em',t:'Email',s:C.email,via:'email',to:C.email.toLowerCase(),show:C.email.toLowerCase()})}catch(e){}
 var pick=saved.length?saved[0].v:'other',typed='',out=null;
 while(true){
  var row=function(o){return '<label class="v518op"><input type="radio" name="v518via" value="'+o.v+'"'+(pick===o.v?' checked':'')+'><span><b>'+v512Esc(o.t)+'</b><small>'+v512Esc(o.s)+' \u2022 on their profile</small></span></label>'};
  var html='<h3 id="hh-t">Send the application</h3><p id="hh-b">'+v512Esc(P.name)+' fills it in and signs it on their phone. The link works once, for 7 days.</p>'+
   (saved.length?'<div class="v518ops">'+saved.map(row).join('')+'<label class="v518op"><input type="radio" name="v518via" value="other"'+(pick==='other'?' checked':'')+'><span><b>Another number or email</b><small>Used instead of the one on their profile</small></span></label></div>':'<p class="v518none">They have no phone number or email on their profile.</p>')+
   '<div class="v518tow"><input id="v518-to" class="v508sel" type="text" style="padding:0 12px" placeholder="Phone number or email" autocomplete="off" value="'+v512Esc(typed)+'"><div class="v518hint" id="v518-hint">'+V518_HINT+'</div></div>'+
   '<div class="v512stk"><button type="button" class="btn ghost" data-hh="x">Cancel</button><button type="button" class="btn" data-hh="ok">Send</button></div>';
  var r=await v508Dlg(html,function(w){var inp=w.querySelector('#v518-to'),tw=w.querySelector('.v518tow'),hint=w.querySelector('#v518-hint');
   var cur=function(){var c=w.querySelector('input[name=v518via]:checked');return c?c.value:'other'};
   var sync=function(){var o=cur()==='other';tw.style.display=o?'':'none';if(o)try{inp.focus()}catch(e){}};
   [].forEach.call(w.querySelectorAll('input[name=v518via]'),function(e){e.addEventListener('change',sync)});tw.style.display=cur()==='other'?'':'none';
   inp.addEventListener('input',function(){hint.classList.remove('bad');hint.textContent=V518_HINT});
   w.addEventListener('click',function(ev){var b=ev.target.closest('[data-hh="ok"]');if(!b)return;pick=cur();typed=String(inp.value||'').trim();
    if(pick==='other'){var k=v518Check(typed);if(!k.ok){ev.preventDefault();ev.stopPropagation();hint.classList.add('bad');hint.textContent=typed?(/@/.test(typed)?'That email does not look right. ':'That number does not look right. ')+V518_HINT:'Type a phone number or an email. '+V518_HINT;try{inp.focus()}catch(e){}return}out=k}
    else out=saved.filter(function(o){return o.v===pick})[0]||null},true)});
  if(r!=='ok'||!out)return;
  /* Is this right? the exact number or email before anything is sent */
  var c2=await v508Dlg('<h3 id="hh-t">Is this right?</h3><p id="hh-b">The link goes to '+v512Esc(P.name)+' by '+(out.via==='email'?'email':'WhatsApp')+':</p><p class="v518big">'+v512Esc(out.show)+'</p><p class="was">Check it before you send. The person who gets the link can sign this application.</p><div class="v512stk"><button type="button" class="btn ghost" data-hh="x">Change</button><button type="button" class="btn" data-hh="ok">Yes, send</button></div>');
  if(c2==='ok')break;
  if(pick==='other')typed=out.to.indexOf('@')>-1?out.to:typed}
 await v518Make(x,P,out.via,out.to)}
async function v518Make(x,P,via,to){var id=x.id;
 var idt='';try{idt=await window.HHSL_getToken()}catch(e){}if(!idt){toast('Sign in again, then send it.');return}
 toast('Making the link\u2026');var res=null;try{var rq=await fetch('/.netlify/functions/lvapp',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'create',idToken:idt,leaveId:id,via:via,to:to,name:P.name,byName:(S.me&&S.me.name)||''})});res=await rq.json()}catch(e){res=null}
 if(!res||!res.ok){toast(res&&res.error==='phone'?'That phone number does not look right.':res&&res.error==='email'?'That email does not look right.':res&&res.error==='not allowed'?'You cannot send applications for this side.':'The link could not be made. Try again.');return}
 var now=new Date().toISOString(),me=(typeof myEmailLc==='function'?myEmailLc():'')||'';var L={status:'sent',at:now,via:via,to:res.to,expiresAt:res.expiresAt,by:me,byName:(S.me&&S.me.name)||''};
 try{if(S.stleave[id])S.stleave[id].appLink=L}catch(e){}try{var mp=atlLeaveMap();if(mp[id])mp[id].appLink=L}catch(e){}
 if(via==='whatsapp'){v517WaTo(to,res.text);toast('WhatsApp is opening. Tap Send there.')}else toast(res.mail&&res.mail.ok?'Email sent to '+res.to+'.':'The link was made, but the email could not be sent: '+((res.mail&&res.mail.error)||'try again'));
 renderSettings()}
v517SendDlg=v518SendDlg;

