document.addEventListener('click',function(ev){var t=ev.target.closest&&ev.target.closest('[data-act="v518-reopen"]');if(!t)return;ev.preventDefault();ev.stopPropagation();v518Reopen(t.getAttribute('data-id'))},true);

/* ---- reminders for applications not signed: 2 days = the person who sent it, 7 days = the Executives (bell, Home, phone) ---- */
function v518AllLeave(){var out=[];try{Object.keys(S.stleave||{}).forEach(function(k){var x=S.stleave[k];if(x&&x.kind==='leave')out.push(Object.assign({id:k,_side:'staff'},x))})}catch(e){}
 try{var mp=atlLeaveMap();Object.keys(mp||{}).forEach(function(k){var x=mp[k];if(x&&x.kind==='leave'&&!out.some(function(o){return o.id===k}))out.push(Object.assign({id:k,_side:'atl'},x))})}catch(e){}return out}
function v518Unsigned(){var me=(typeof myEmailLc==='function'?myEmailLc():'')||'',ex=!!(S.isOwner||S.isExec),now=Date.now(),out=[];
 v518AllLeave().forEach(function(x){try{if(x.cancelled||x.appRecv)return;var L=x.appLink;if(!L||!L.at)return;var st=v517LinkState(x);if(st!=='sent'&&st!=='expired')return;
  var age=Math.floor((now-Date.parse(L.at))/864e5);if(!(age>=2))return;var mine=String(L.by||'').toLowerCase()===me;
  if(age>=7&&ex)out.push({x:x,age:age,stage:7});else if(mine)out.push({x:x,age:age,stage:age>=7?7:2})}catch(e){}});
 return out.sort(function(a,b){return b.age-a.age})}
