/* ===== V5.23 (Akeem, 17 Oct 2026; BUILD_PLAN_V5.23_LEAVE.md): Leave. ONE form for every leave type on every side (the person's own form is
   the master; the office Add leave form and the link page are copies): First day, Number of days (optional), Last day (optional, fills in by
   itself) and a read-only Due back worked out from the person's own schedule (working days for staff, the shift cycle for Atlantic). Sick
   leave with no days and no last day is ongoing. The illness chips: Cold or flu, Fever, Stomach upset, Migraine and Dental print on the letter;
   Injury, Medical appointment, Other and anything typed are private (lvsens). One signature card (the office signs ON the form). Change can
   switch the leave type; Entered by mistake removes a leave that should not exist (the record is kept). Application needed on every leave
   row. Every leave notification opens the Leave page. ===== */
var V523_ILL=['Cold or flu','Fever','Stomach upset','Injury','Migraine','Dental','Medical appointment','Other'];
var V523_PRIV={'Injury':1,'Medical appointment':1,'Other':1};
var V523_PHR={'Cold or flu':'a cold or flu','Fever':'a fever','Stomach upset':'a stomach upset','Migraine':'a migraine','Dental':'a dental problem'};
var V523_LEG='Chips without a lock are shown on the letter. \uD83D\uDD12 Injury, Medical appointment, Other and anything you type are private: only senior management can see them.';
var V523_PRIVNOTE='\uD83D\uDD12 What you type here is private: only senior management can see it. It is never printed on the letter.';
function v523Priv(ill){return !!V523_PRIV[String(ill||'')]}
function v523Phrase(ill){return V523_PHR[String(ill||'')]||'illness'}
var V523_WD=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'],V523_MO=['January','February','March','April','May','June','July','August','September','October','November','December'];
function v523Long(d){var x=new Date(String(d)+'T12:00:00');if(!isDate(d)||isNaN(x))return '';return V523_WD[x.getDay()]+' '+x.getDate()+' '+V523_MO[x.getMonth()]+(x.getFullYear()!==new Date().getFullYear()?' '+x.getFullYear():'')}
function v523Esc(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;')}
/* the person's schedule: an Atlantic person on a shift follows the cycle; everyone else works Monday to Friday without public holidays */
function v523Cyc(pid){try{return !!pid&&!!atlByCycle(pid)}catch(e){return false}}
