async function v523SelfOpen(id,mode){var x=v512Find(id);if(!x)return;var idt='';try{idt=await window.HHSL_getToken()}catch(e){}if(!idt){toast('Sign in again, then try.');return}
 var w=null;try{w=window.open('about:blank','_blank')}catch(e){}
 var res=null;try{var rq=await fetch('/.netlify/functions/lvapp',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'self',mode:mode,idToken:idt,leaveId:id,work:v523Work(x)})});res=await rq.json()}catch(e){res=null}
 if(!res||!res.ok||!res.url){try{w&&w.close()}catch(e){}toast(res&&res.error==='not yours'?'This leave is not yours.':res&&res.error==='done'?'This is already sent.':'Could not open the form. Try again.');return}
 if(w){try{w.location.href=res.url;return}catch(e){}}location.href=res.url}

