try{var _v523Upd=updItems;updItems=function(){var u=_v523Upd.apply(this,arguments);try{if(!S.isErt&&u&&u.act)v523MisMine().forEach(function(x){u.act.push({k:'lvd:mis:'+x.id,t:Date.parse(x.cancelledAt),ic:'leave',title:'A leave recorded for you was removed',sub:stLT(x.type)+' \u2022 '+stShort(x.start)+(x.end&&x.end!==x.start?' \u2013 '+stShort(x.end):'')+' \u2022 entered by mistake',go:'me',id:x.id})})}catch(e){}return u}}catch(e){}
try{var _v523Eb=ertBellItems;ertBellItems=function(){var out=_v523Eb.apply(this,arguments);try{v523MisMine().forEach(function(x){out.push({ms:Date.parse(x.cancelledAt),ic:'no',title:'Your '+stLT(x.type).toLowerCase()+' leave '+stShort(x.start)+(x.end&&x.end!==x.start?' \u2013 '+stShort(x.end):'')+' was removed',sub:'Entered by mistake'+(x.mistakeReason?': '+x.mistakeReason:''),lvid:x.id})})}catch(e){}return out}}catch(e){}
