function v529ShiftTime(sh){return sh==='Night'?'7 pm to 7 am':'7 am to 7 pm'}
function v529Nice(d){try{return fmt(d)}catch(e){return d}}
function v529Ini(n){return String(n||'?').split(/[\s\-]+/).map(function(x){return x.charAt(0)}).join('').slice(0,2).toUpperCase()}
function v529Today(){return iso(TODAY)}
/* ---- the server (cover.js) ---- */
function v529Post(action,extra){return window.HHSL_getToken().then(function(idt){if(!idt)throw new Error('sign in');return fetch('/.netlify/functions/cover',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(Object.assign({idToken:idt,action:action},extra||{}))})})
  .then(function(r){return r.json().catch(function(){return {}}).then(function(j){j=j||{};j._status=r.status;return j})})}
