/* ===== V5.32 (Akeem, 20 Oct 2026): photos on Shift status and Cover, a notification-style count, "Shift covered" instead of a misleading error,
   names at once on Cover, and cover on the Atlantic roster (display only; nothing is written to the roster, hours or pay: rule 134) =====
   Everything still comes from the one record: the server reads the Atlantic roster (ert), leave (leavereq) and covers (covreq); the Atlantic roster in the office
   app reads the same ert people and the same covreq records. No copy is made. */
var V532={ph:{},phAsk:{},phBusy:false};
/* the avatar: the roster profile photo (thumbnail) when the server gave one to a supervisor, the initials until then and for people without a photo */
function v532Av(id,name,ini){var u=V532.ph[id];return '<span class="v529av">'+(u?'<img src="'+v531Esc(u)+'" alt="">':v531Esc(ini))+'</span>'}
function v532PhotoIds(){var ids={},st=V531.st,C=V531.cov;
  if(st){(st.sections||[]).forEach(function(s){(s.people||[]).forEach(function(p){ids[p.id]=1})});if(C)(st.pool||[]).forEach(function(p){ids[p.id]=1})}
  if(C&&C.people)C.people.forEach(function(p){ids[p.id]=1});
  return Object.keys(ids).filter(function(id){return !V532.ph[id]&&!V532.phAsk[id]})}
function v532Photos(){if(!S.isErt||!v529Sup()||V532.phBusy)return;var ids=v532PhotoIds();if(!ids.length)return;V532.phBusy=true;ids.forEach(function(i){V532.phAsk[i]=1});
  v529Post('photos',{ids:ids}).then(function(j){V532.phBusy=false;var n=0;if(j&&j.ok&&j.photos)Object.keys(j.photos).forEach(function(id){var u=j.photos[id];if(typeof u==='string'&&u.indexOf('data:image/')===0){V532.ph[id]=u;n++}});if(n)v529Paint();if(v532PhotoIds().length)v532Photos()})
  .catch(function(){V532.phBusy=false;ids.forEach(function(i){delete V532.phAsk[i]})})}
/* Cover opens with the names already there: the status carries a light list of the other shifts and the Duty Pool; the availability fills in when the server answers */
function v532Pre(C){var st=V531.st,me=String(S.myErtId||'');if(!st||!Array.isArray(st.pool))return [];
  return st.pool.filter(function(p){return p.id!==me&&p.id!==C.id&&p.group!==C.group})}
function v532CovPre(C){var pre=C.pre||[];if(!pre.length)return '<div class="card"><div class="none" style="padding:14px">Finding who can cover…</div></div>';
  return '<div class="card v531list"><div class="v529sec" style="margin-top:0">Checking who is free…</div>'+pre.map(function(x){return '<div class="v529row off">'+v532Av(x.id,x.name,v529Ini(x.name))+'<span class="v529nm"><b>'+v531Esc(x.name)+'</b><small>'+v531Esc([x.group,x.role].filter(Boolean).join(' • '))+'</small></span></div>'}).join('')+'</div>'}
/* after a cover is agreed, or a request is sent: say so, plainly, and bring Shift status up to date */
function v532Finish(kind,a,b){var C=V531.cov;if(!C)return;C.loading=false;C.err='';if(kind==='done')C.done={by:a||'',slot:b||v531Slots(C.run&&C.run.length?C.run:C.need.slice(0,C.n))};else C.sent={to:a||''};
  try{v531Load(true)}catch(e){}v529Paint();try{window.scrollTo(0,0)}catch(e){}}
function v532CovDone(C){var d=C.done,sl=d?d.slot:'',h='<div class="card v531for"><div class="v531lab">Cover for</div><div class="v531nm2">'+v531Esc(C.name)+'</div><div class="v531sub">'+v531Esc(C.group||'')+'</div></div>';
  h+='<div class="card v532done'+(d?'':' wait')+'"><span class="v532tick" aria-hidden="true">'+(d?'✓':'…')+'</span><span><b>'+(d?v531Esc(sl)+' covered':'Request sent')+'</b><small>'+(d?(d.by?'Covered by '+v531Esc(d.by)+'. ':'')+'Everyone who needs to know is told.':'Waiting for '+v531Esc(C.sent.to)+' to answer. You will be told when they do. Shift status shows it as asked until then.')+'</small></span></div>';
  h+='<div class="actions"><button type="button" class="btn" data-act="v532-back">Back to Shift status</button></div>';
  return '<div class="ertwrap etpad" id="v529-cover">'+h+'</div>'}
document.addEventListener('click',function(ev){var t=ev.target.closest&&ev.target.closest('[data-act="v532-back"]');if(!t||!S.isErt)return;ev.preventDefault();V531.cov=null;v529Paint();try{window.scrollTo(0,0)}catch(e){}});

/* ---- the Atlantic roster (office app): who is covered, and by whom, read live from the same cover records (covreq; office editors and directors already read them) ---- */
var V532A={cov:[],on:false};
function v532AtlStart(){if(V532A.on||!S.db||S.isErt||!window.HHSL_STANDALONE)return;V532A.on=true;
  try{S.db.collection('covreq').where('date','>=',addDays(iso(TODAY),-2)).onSnapshot(function(snap){V532A.cov=snap.docs.map(function(d){var x=d.data()||{};x.id=d.id;return x}).filter(function(x){return x.status==='confirmed'||x.status==='asked'});try{if(S.tab==='atl')atlRender()}catch(e){}},function(){V532A.cov=[]})}catch(e){V532A.on=false}}
function v532Live(c){var t=iso(TODAY);return v531Run(c).some(function(k){return k.slice(0,10)>=t})}
function v532Lab(c){return c.runLabel||c.shift||''}
function v532CovTag(p){var out='';V532A.cov.forEach(function(c){if(!v532Live(c))return;
  if(c.forErtId===p.id)out+='<span class="atlsub v532cv '+(c.status==='confirmed'?'ok':'wait')+'">'+(c.status==='confirmed'?'Covered by ':'Asked ')+esc(c.name||'')+' • '+esc(v532Lab(c))+'</span>';
  else if(c.ertId===p.id&&c.status==='confirmed')out+='<span class="atlsub v532cv ok">Covering '+esc(c.forName||'')+' • '+esc(v532Lab(c))+'</span>'});return out}
function v532Inject(h,p){try{var tag=v532CovTag(p);if(tag)return h.replace(/(<span class="atlsub">[^<]*<\/span>)/,function(m){return m+tag})}catch(e){}return h}
var _v532Row=atlRowHtml;atlRowHtml=function(p){return v532Inject(_v532Row.apply(this,arguments),p)};
var _v532Lv=atlLeaveRow;atlLeaveRow=function(p,x){return v532Inject(_v532Lv.apply(this,arguments),p)};
function v532AtlCard(){var L=V532A.cov.filter(function(c){return v532Live(c)}).sort(function(a,b){return String(a.date).localeCompare(String(b.date))});if(!L.length)return '';
  return '<div class="card v532atl"><div class="atlath"><span class="atllab">Cover</span><span class="atltag">'+L.length+'</span></div>'+L.slice(0,6).map(function(c){return '<div class="v532ar"><span class="atlrm"><span class="atlrn2">'+esc(c.forName||'')+'</span><span class="atlsub">'+esc((c.forGroup||'')+' • '+v532Lab(c)+' • '+(c.status==='confirmed'?'covered by ':'asked ')+(c.name||''))+'</span></span><span class="atlpill '+(c.status==='confirmed'?'atlpok':'atlps')+'">'+(c.status==='confirmed'?'Covered':'Waiting')+'</span></div>'}).join('')+(L.length>6?'<div class="atlsub">and '+(L.length-6)+' more</div>':'')+'</div>'}
var _v532Home=atlHomeHtml;atlHomeHtml=function(){try{v532AtlStart()}catch(e){}var h=_v532Home.apply(this,arguments);try{h+=v532AtlCard()}catch(e){}return h};
var _v532Page=atlPageHtml;atlPageHtml=function(){try{v532AtlStart()}catch(e){}return _v532Page.apply(this,arguments)};

