/* ===== V5.33 (Akeem, 20 Oct 2026): everyone sees their own requests and letters; leave managers approve all leave =====
   (1) Every person, whatever their rank, taps their own request (the Waiting for approval card on the ERT Dashboard, the rows under Your requests on My profile)
   and sees its information, with View PDF and Save PDF at the bottom (the existing own-leave page, v523Mine). A job letter row opens a small page with its details and,
   once issued, View PDF and Save PDF. Edit and Withdraw stay as they were.
   (2) Anyone with Leave (Staff members) or Leave: Atlantic at Manage approves and signs all leave of their side, over the allowance included; never their own
   (the database rules already say so: nothing changes there); a change from unpaid days and a cancellation request stay with an Executive. ===== */
/* the letter viewer for any model (the leave viewer's own markup; Save PDF is the existing lv-pvsave) */
async function v533ShowModel(m,name){try{var res=await pvPages(m);var w=$('#lvpv');if(w)w.remove();w=document.createElement('div');w.id='lvpv';w.className='lvpv';w.setAttribute('role','dialog');w.setAttribute('aria-label','Letter PDF');
  w.innerHTML='<div class="lvpvh"><button class="btn ghost" data-act="lv-pvx">‹ Close</button><b>'+esc(m.title)+'</b><button class="btn" data-act="lv-pvsave">⇩ Save PDF</button></div><div id="pv-host" class="lvpvb"></div>';document.body.appendChild(w);
  S.lvPvModel=m;S.lvPvName=name;var keep=S.pv;S.pv={zoom:1};pvDraw(res);S.pv=keep}catch(e){toast('Could not make the letter. Try again.')}}
/* a job letter of the person's own: its details, and View PDF / Save PDF once it is issued */
async function v533Jl(id){var x=jlFind(id);if(!x)return;var st=jlStatus(x),rows=[['Status',st[0]],['Addressed to',x.addressee||'—'],['Purpose',jlPurp(x.purpose)],['Asked on',x.at?lvShort(String(x.at).slice(0,10)):'—']];
  if(x.ref)rows.push(['Reference',x.ref]);if(x.status==='declined'&&x.declineReason)rows.push(['Reason declined',x.declineReason]);
  var body=rows.map(function(r){return '<div class="v533kv"><span>'+esc(r[0])+'</span><b>'+esc(r[1])+'</b></div>'}).join('');
  var btns=x.status==='issued'?'<button type="button" class="btn" data-hh="view">View PDF</button><button type="button" class="btn ghost" data-hh="dl">Save PDF</button>':'';
  var r=await v508Dlg('<h3 id="hh-t">Job letter</h3><div id="hh-b">'+body+(x.status==='requested'?'<p class="none" style="padding:8px 0 0">The letter is made when HR issues it. You can then view and save it here.</p>':'')+'</div><div class="v512stk">'+btns+'<button type="button" class="btn ghost" data-hh="x">Close</button></div>');
  if(r==='view'){try{var m=await jlModel(x,false);v533ShowModel(m,(x.ref||'Job letter')+' - '+pSafe(x.name||'')+'.pdf')}catch(e){toast('Could not make the letter. Try again.')}}else if(r==='dl')jlPdf(x,false,false)}
document.addEventListener('click',function(ev){var t=ev.target.closest&&ev.target.closest('[data-act="v533-jl"]');if(!t)return;ev.preventDefault();ev.stopPropagation();v533Jl(t.dataset.id||'')},true);
/* the Atlantic approver: an Atlantic leave manager (Leave: Atlantic at Manage) or an Executive */
function v533AtlApr(){try{return !!(S.isOwner||S.isExec||(typeof v486Can==='function'&&v486Can('atl')))}catch(e){return false}}
/* a manager's own record is never approved by that manager: the person is the manager (same sign-in email) */
function v533SelfAtl(pid){try{var id=String(pid||'').replace(/^a_/,''),p=(S.people||[]).filter(function(q){return q.id===id})[0];return !!p&&ertEmail(p)!==''&&ertEmail(p)===String(lvMe()||'').toLowerCase()}catch(e){return false}}
(function(){try{var st=document.createElement('style');st.textContent=".v533tap{cursor:pointer}.v533hint{font-size:12.5px;color:var(--brand);font-weight:700;padding:2px 0 0}"+
 "button.mpnopen{background:none;border:0;padding:0;margin:0;text-align:left;font:inherit;color:inherit;cursor:pointer;text-transform:none;letter-spacing:0;flex:1;min-width:0;min-height:44px}button.mpnopen *{text-transform:none}"+
 ".v533kv{display:flex;justify-content:space-between;gap:12px;padding:7px 0;border-top:1px solid var(--line)}.v533kv:first-child{border-top:0}.v533kv span{color:var(--muted)}.v533kv b{text-align:right}";document.head.appendChild(st)}catch(e){}})();

/* ===== V5.34 (Akeem, 21 Nov 2026): one button look everywhere (UNIVERSAL_RULES 146) =====
   The standard button: 15 px text in the REGULAR weight (the app has Lato 400 and 700 only, so 600 was drawn as bold and looked heavy), 44 px high, one line, never two rows,
   sentence case. Compact buttons (top and sheet bars, account cards, small pickers, chips, tiles, mini and sm buttons) keep their own size but follow the weight and the one line.
   A row of buttons wraps onto a second ROW when the labels do not fit; a label never wraps and is never cut. */
(function(){try{
  var X=':not(.mini):not(.sm):not(.chip):not(.special):not(.tplpair):not(.v486add):not(.sgfullb):not(.lvtile):not(.hero):not(.pcardbtn):not(.bkic):not(.insend):not(.lk-go):not(.tkslim):not(.topsave):not(.v502new):not(.updch)',
  BAR=':not(.sheet-bar *):not(.tplbar *):not(.acctacts *):not(.jbb *):not(.lvpvh *):not(.pbtns *):not(.ecfb *):not(.reqdone *):not(.payacts *):not(.updkinds *)',
  B='html body :is(#app,#set-in,#hhdlg,body) '+new Array(15).join('.btn'),
  css=B+'{font-weight:600!important;text-transform:none!important;letter-spacing:0!important;white-space:nowrap!important;flex-shrink:0!important;min-width:max-content}'+
   B+X+BAR+'{height:44px!important;min-height:44px!important;padding-top:0!important;padding-bottom:0!important;padding-left:14px!important;padding-right:14px!important;font-size:15px!important;line-height:1.2!important}'+
   'html body .actions{flex-wrap:wrap}'+
   /* the backup reminder and the automatic backup page: the buttons fill their row */
   'html body #view-home .bkhome .actions>.btn,html body #set-in #sec-devbk .actions>.btn{flex:1 1 auto!important}'+'@media (max-width:640px){html body #set-in #sec-devbk .actions>.btn:nth-child(3){flex-basis:100%!important}}';
  var st=document.createElement('style');st.id='v534-btn';st.textContent=css;document.head.appendChild(st)}catch(e){}})();

/* ===== V5.35 (Akeem, 21 Nov 2026; UNIVERSAL_RULES 147): the Leave page top bar, the model page for the new bar.
   LEFT Back and the app menu button (as today: each keeps its 48 px tap area), then the title. RIGHT search, the round + and the three-dots button (More). The old search row, gear,
   download icon, "+ Add" and the (i) beside the title are gone from view: the three-dots menu holds Download report, Leave allowances, Leave history,
   Record absent without leave, Unpaid days to deduct, Job letters and About this page. Tapping search turns the whole bar into the search field.
   The old buttons stay in the page (hidden) because the existing code fires them (v487Fire) so every action still works exactly as before. ===== */
function v535Svg(n){var P={search:'<circle cx="11" cy="11" r="6.5"/><path d="m20 20-4-4"/>',plus:'<path d="M12 5v14M5 12h14"/>',more:'<circle cx="12" cy="5" r="1.4" fill="currentColor" stroke="none"/><circle cx="12" cy="12" r="1.4" fill="currentColor" stroke="none"/><circle cx="12" cy="19" r="1.4" fill="currentColor" stroke="none"/>',x:'<path d="M6 6l12 12M18 6 6 18"/>',back:'<path d="M15 18l-6-6 6-6"/>'};
  return '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+P[n]+'</svg>'}
function v535Btn(act,label,svg,sol){var b=document.createElement('button');b.type='button';b.className='v535b'+(sol?' sol':'');b.setAttribute('data-act',act);b.setAttribute('data-tic','1');b.setAttribute('aria-label',label);b.innerHTML=svg;return b}
function v535MenuClose(){var d=document.getElementById('v535mk');if(d)d.remove()}
function v535MenuOpen(){return !!document.getElementById('v535mk')}
function v535Items(){var C=S._v487Can||{},side='staff',o=[];try{side=v486CurSide()}catch(e){}
  if(C.rep)o.push({g:1,t:'Download report',s:'Choose the period, people and type, then PDF or Excel',run:function(){v487Fire('rp-open')}});
  if(C.allow){o.push({g:2,t:'Leave allowances',s:'Yearly days by role, position or person',run:function(){v486AllowOpen(side)}});o.push({g:2,t:'Leave history',s:'Everything recorded, changed and cancelled',run:function(){v520Hist()}})}
  if(C.aw)o.push({g:3,t:'Record absent without leave',run:function(){v487Fire('aw-new')}});
  if(C.pc)o.push({g:3,t:'Unpaid days to deduct',run:function(){v487Fire('pc-open')}});
  try{if(!S.isErt&&typeof jlSee==='function'&&jlSee())o.push({g:3,t:'Job letters',run:function(){openSettings('jletters')}})}catch(e){}
  o.push({g:4,t:'About this page',run:function(){var h=document.querySelector('#set-in .sheet-bar [data-act="hp-open"]');if(h)h.click()}});return o}
function v535Menu(anchor){v535MenuClose();var rows=v535Items(),bar=document.querySelector('#set-in .sheet-bar'),r=(bar||anchor).getBoundingClientRect();
  var d=document.createElement('div');d.id='v535mk';var h='',g0=0;rows.forEach(function(x,i){h+=(g0&&x.g!==g0?'<div class="v535sep"></div>':'')+'<button type="button" class="v535it" role="menuitem" data-i="'+i+'"><b>'+esc(x.t)+'</b>'+(x.s?'<small>'+esc(x.s)+'</small>':'')+'</button>';g0=x.g});
  d.innerHTML='<div class="v535menu" role="menu" aria-label="More" style="top:'+Math.round(r.bottom+4)+'px">'+h+'</div>';document.body.appendChild(d);
  d.addEventListener('click',function(ev){ev.stopPropagation();var it=ev.target.closest&&ev.target.closest('.v535it');if(it){var x=rows[+it.dataset.i];v535MenuClose();try{x.run()}catch(e){}return}if(ev.target===d)v535MenuClose()})}
/* the bar */
function v535Is(){return !!(S.set&&S.setPage==='leave'&&!S.lvAdd&&!S.lvAllow&&!(typeof v486Inner==='function'&&v486Inner()))}
