/* ===== V5.36 (Akeem, 21 Nov 2026): say exactly what a backup left out and exactly what a restore could not import, and put both in the problem logs.
   Backup: the parts the account is not allowed to read are named (they are private or per-person records by design: the database rules refuse a list of them).
   Restore: every item that could not be saved is counted by kind with the reason; the record names are shown on the screen (first 5 of each kind) and are never put in the logs.
   Problem logs: the Error log page (errRecord) and the Private log bugs (v519Bug), both quiet, the kind and the counts only. ===== */
function bkNiceName(c){try{return (typeof BK_NAMES!=='undefined'&&BK_NAMES[c])||c}catch(e){return c}}
function bkWhy(code){code=String(code||'');return code==='permission-denied'?'not allowed for this account':(code==='unavailable'||code==='deadline-exceeded'||code==='cancelled')?'no connection':code==='resource-exhausted'?'too many at once':(code||'error')}
function bkLogProblem(msg){try{if(typeof errRecord==='function')errRecord('backup',msg,'');if(typeof v519Bug==='function')v519Bug('backup',msg,'normal','backup')}catch(e){}}
/* a backup: name what was left out; returns the short text for the toast and keeps it for the Backup page */
function bkSkipReport(skipped,quiet){try{skipped=(skipped||[]).filter(function(x){return String(x).indexOf('/')<0});if(!skipped.length){try{abkSet({lastSkip:''})}catch(e){}return ''}
  var names=skipped.map(bkNiceName);var txt=names.join(', ');try{abkSet({lastSkip:txt})}catch(e){}
  bkLogProblem('Backup left out '+skipped.length+(skipped.length===1?' part':' parts')+' this account may not read: '+skipped.join(', '));
  return ' ('+skipped.length+(skipped.length===1?' part was':' parts were')+' left out, not allowed for this account: '+txt+')'}catch(e){return ''}}
/* a restore: what could not be imported, by kind, with the reason */
async function bkFailReport(fails,total){try{var g={};fails.forEach(function(f){var o=g[f[0]]||(g[f[0]]={n:0,why:{},ids:[]});o.n++;o.why[bkWhy(f[2])]=1;if(o.ids.length<5)o.ids.push(f[1])});
  var kinds=Object.keys(g).sort(function(a,b){return g[b].n-g[a].n});
  var lines=kinds.map(function(c){var o=g[c];return '• '+bkNiceName(c)+': '+o.n+' ('+Object.keys(o.why).join(', ')+')\n   '+o.ids.join(', ')+(o.n>o.ids.length?' …':'')});
  bkLogProblem('Restore: '+fails.length+' of '+total+' items not imported: '+kinds.map(function(c){return c+' '+g[c].n+' ('+Object.keys(g[c].why).join(', ')+')'}).join('; '));
  S.bkLastFail=lines.join('\n');
  await hhAlert(fails.length+' of '+total+' items were not imported. Everything else was imported.\n\n'+lines.join('\n')+'\n\nThe kinds and the numbers are in the Error log and the Private log. The record names are shown here only.',{title:'Some items were not imported',icon:'info'})}catch(e){}}

