try{UPD_REG.lvsk={kind:'needs',tab:'leave',lvl:'manage'};UPD_REG.lvch={kind:'foryou'};UPD_REG.lvcn={kind:'foryou'};if(SPP_NEEDS.indexOf('lvsk')<0)SPP_NEEDS.push('lvsk');SPP_TAB.lvsk='leave';SPP_TAB.lvch='leave';SPP_TAB.lvcn='leave'}catch(e){}
