function dShow(iso){var m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(iso||'');return m?(+m[3])+' '+MON[+m[2]-1]+' '+m[1]:''}
function dParse(t){t=String(t||'').trim();if(!t)return '';var m=/^(\d{4})-(\d{1,2})-(\d{1,2})$/.exec(t);if(m)return okd(+m[1],+m[2],+m[3]);m=/^(\d{1,2})[\s\/.\-]+([A-Za-z]{3,9}|\d{1,2})[\s\/.\-,]+(\d{4})$/.exec(t);if(!m)return '';var mo=/^\d+$/.test(m[2])?+m[2]:MON.map(function(x){return x.toLowerCase()}).indexOf(m[2].slice(0,3).toLowerCase())+1;return okd(+m[3],mo,+m[1]);
  function okd(y,mo,d){if(mo<1||mo>12||d<1||d>31||y<1900||y>2100)return '';var dt=new Date(Date.UTC(y,mo-1,d));if(dt.getUTCMonth()!==mo-1)return '';return y+'-'+('0'+mo).slice(-2)+'-'+('0'+d).slice(-2)}}
function monYr(t){t=String(t||'').trim();var m=/^(\d{1,2})[\/\-.](\d{2,4})$/.exec(t);if(m){var mo=+m[1],y=+m[2];if(y<100)y+=2000;return mo>=1&&mo<=12?{mo:mo,y:y}:null}m=/^([A-Za-z]{3,9})[\s,\-]+(\d{4})$/.exec(t);if(m){var i=MON.map(function(x){return x.toLowerCase()}).indexOf(m[1].slice(0,3).toLowerCase());return i>=0?{mo:i+1,y:+m[2]}:null}return null}
function pleaShow(t){t=String(t||'');var q=/^(\d{4})-(\d{2})$/.exec(t);if(q)return MON[+q[2]-1]+' '+q[1];var m=monYr(t);return m?MON[m.mo-1]+' '+m.y:''}
function emailNow(){var u=A().currentUser;return String((u&&u.email)||'').toLowerCase()}
function nameFromGoogle(){var u=A().currentUser;return (u&&u.displayName)||''}
function hasPassword(u){try{return (u.providerData||[]).some(function(p){return p.providerId==='password'})}catch(e){return false}}
function isGoogle(u){try{return (u.providerData||[]).some(function(p){return p.providerId==='google.com'})}catch(e){return false}}
function inAppBrowser(){var ua=navigator.userAgent||'';return /FBAN|FBAV|Instagram|Line\/|MicroMessenger|Snapchat|Twitter|TikTok|GSA\//i.test(ua)||(/iPhone|iPad|iPod/.test(ua)&&!/Safari/.test(ua)&&!window.navigator.standalone)}
function niceErr(e){var c=(e&&e.code)||'';
  if(c==='auth/email-already-in-use')return 'That email already has an account. Go back and tap Sign in.';
  if(c==='auth/invalid-email')return 'Enter a valid email address.';
  if(c==='auth/weak-password')return 'Use a password with at least 8 characters.';
  if(c==='auth/too-many-requests'||c==='auth/quota-exceeded')return 'Too many tries today. Try again tomorrow, or continue with Google.';
  if(c==='auth/network-request-failed')return 'No connection. Check your signal and try again.';
  if(c==='auth/popup-blocked')return 'Your browser blocked the Google window. Allow pop-ups for this page and try again.';
  if(c==='auth/popup-closed-by-user'||c==='auth/cancelled-popup-request')return '';
  if(c==='auth/operation-not-allowed')return 'Google sign-in is not switched on yet. Use your email and a password, or ask the office.';
  if(c==='auth/account-exists-with-different-credential')return 'This email already signs in another way. Use your email and password.';
  if(c==='auth/requires-recent-login')return 'For safety, sign out and sign in again, then try again.';
  if(c==='permission-denied')return 'The office has not finished switching this on yet. Try again later.';
  if(c==='auth/unauthorized-domain')return 'This web address is not allowed for sign-in yet. Ask the office. (Reason: unauthorized-domain)';
  return 'That did not work. Try again.'+(c?' (Reason: '+String(c).replace('auth/','')+')':'')+(e&&e.message&&c?' '+String(e.message).replace(/Firebase: /,'').slice(0,180):'')}
