function rowsFor(tab){var ex2=execSet(),out=[];
 if(tab==='inc'){(S.v589Inc||[]).forEach(function(r){out.push({tab:tab,id:r._id,name:r.name||r._id,sub:r._id+' • '+(r.status==='rejected'?'Rejected':'Setup not finished'),photo:r.photo,can:true})});return out}
 if(tab==='staff'){var m=S.stdocs||{};Object.keys(m).forEach(function(k){var d=m[k];if(!isStaffDoc(d))return;var ems=emailsOf('staff',k);if(ems.some(ownerEm))return;out.push({tab:tab,kind:'staff',id:k,name:d.name||'Unnamed',sub:[d.title,d.email].filter(Boolean).join(' • '),photo:d.thumb||d.photo||'',phone:d.phone||'',can:S.isOwner||!ems.some(function(e){return ex2[e]})})});return out}
 (S.people||[]).forEach(function(p){if(tab==='atl'?!isAtl(p):isAtl(p))return;var ems=emailsOf('ert',p.id);if(ems.some(ownerEm))return;out.push({tab:tab,kind:'ert',id:p.id,name:p.name||'Unnamed',sub:[p.role,p.email].filter(Boolean).join(' • '),photo:p.thumb||'',phone:p.contact||'',can:S.isOwner||!ems.some(function(e){return ex2[e]})})});return out}
function sorted(a){return a.slice().sort(function(x,y){return String(x.name).localeCompare(String(y.name))})}
