   try{if(kind==='ert'){for(var i=0,P=['ert/'+key,'ertpub/'+key,'ertshifts/'+key,'photos/'+key];i<P.length;i++){try{var x=await S.db.doc(P[i]).get();if(x.exists)await S.db.doc(P[i]).delete()}catch(e){if(i===0)miss.push('profile')}}}else{for(var j=0,Q=['staff/'+key,'staffleave/d_'+key];j<Q.length;j++){try{var y=await S.db.doc(Q[j]).get();if(y.exists)await S.db.doc(Q[j]).delete()}catch(e){if(j===0)miss.push('profile')}}}}catch(e){miss.push('profile')}
   if(!miss.length){try{if(kind==='ert'&&S.peopleAll)S.peopleAll=S.peopleAll.filter(function(x){return x.id!==key});if(kind==='staff'&&S.stdocsAll)delete S.stdocsAll[key]}catch(e){}}
