/* 3.06 Inform personnel: send the crew card to each person on WhatsApp, and record who was informed */
var INF={jid:'',blobs:{},dl:null,saved:{}};
function inStamp(x){if(!x||!x.at)return '';var d=new Date(x.at);if(isNaN(d))return '';return d.getDate()+' '+MON[d.getMonth()]+' '+pad(d.getHours())+':'+pad(d.getMinutes())+(x.byName?' \u00B7 '+String(x.byName).split(' ')[0]:'')}
async function inCopyCard(cid){
  var bp=INF.blobs[cid];if(!bp)return false;
  try{if(navigator.clipboard&&window.ClipboardItem){await navigator.clipboard.write([new ClipboardItem({'image/png':bp})]);return true}}catch(e){}
  if(INF.saved[cid])return 'again';
  try{var b=await bp;if(!b)return false;var dl=INF.dl||await window.claude.use('downloads');INF.dl=dl;await dl.save({kind:'crewimage',filename:'crew-card.png',data:new File([b],'crew-card.png',{type:'image/png'})});INF.saved[cid]=true;return 'saved'}catch(e){return false}
}
