var HH_IC={danger:'<path d="M3 6h18"/><path d="M8 6V4h8v2"/><path d="M19 6l-1 14H6L5 6"/>',warn:'<path d="M10.3 3.9L1.8 18a2 2 0 0 0 1.7 3h17a2 2 0 0 0 1.7-3L13.7 3.9a2 2 0 0 0-3.4 0z"/><path d="M12 9v4M12 17h.01"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v5M12 7.6v.2"/>',archive:'<rect x="3" y="4" width="18" height="4" rx="1"/><path d="M5 8v12h14V8M10 12h4"/>',signout:'<path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4"/><path d="M16 17l5-5-5-5M21 12H9"/>'};
/* 3.11 step-by-step safety sheet: steps shown inside one sheet, ending with a typed check */
/* 3.12 Error log: problems people hit are recorded quietly; only the Owner can read them (needs the 11.4 rules) */
var ERR={q:[],seen:{},n:0};
window.addEventListener('error',function(ev){if(!ev)return;var m=ev.message||(ev.error&&ev.error.message)||'';if(!m&&ev.target&&ev.target!==window)return;errRecord('crash',m,(ev.filename?String(ev.filename).split('/').pop():'')+(ev.lineno?':'+ev.lineno:''))});
window.addEventListener('unhandledrejection',function(ev){var r=ev&&ev.reason;var m=r&&(r.message||r.code)?(r.code?r.code+': ':'')+(r.message||''):String(r||'');errRecord('failed',m,(r&&r.stack?String(r.stack).split('\n')[1]||'':'').trim())});
setInterval(errFlush,30000);
function errLoad(){if(!S.isOwner||!S.db||S.errLoading)return;S.errLoading=true;S.db.collection('errlog').orderBy('ms','desc').limit(500).get().then(function(snap){S.errLog=snap.docs.map(function(d){var o=d.data()||{};o.id=d.id;return o});S.errLoading=false;if(S.set&&S.setPage==='errlog')renderSettings()}).catch(function(){S.errLog=S.errLog||[];S.errFail=true;S.errLoading=false;if(S.set&&S.setPage==='errlog')renderSettings()})}
function errAgo(ms){var m=Math.round((Date.now()-ms)/60000);if(m<1)return 'just now';if(m<60)return m+' min ago';var h=Math.round(m/60);if(h<24)return h+' h ago';var dd=new Date(ms);return dd.getDate()+' '+MON[dd.getMonth()]+' '+pad(dd.getHours())+':'+pad(dd.getMinutes())}
function errLogHtml(){if(!S.errLog){errLoad();return '<div class="card"><div class="none">Loading\u2026</div></div>'}
  var h='<div class="card"><h3>What this is</h3><div class="none">When something goes wrong for anyone using the app (a crash, a save that failed, a part of the app that would not load), it is recorded here quietly. Only you can see this. Nothing personal is recorded beyond who, when, the device and the page.</div>'+(S.errFail?'<div class="none" style="color:var(--exp)">The error log could not be read. Publish the 11.4 rules in Firebase.</div>':'')+'</div>';
  if(!S.errLog.length)return h+'<div class="card"><div class="none">No problems recorded. \u2714</div></div>';
  var g={};S.errLog.forEach(function(x){var k=(x.kind||'')+'|'+(x.msg||'');var o=g[k]||(g[k]={kind:x.kind,msg:x.msg,n:0,last:0,who:{},dev:{},ver:{},items:[]});o.n++;o.last=Math.max(o.last,+x.ms||0);o.who[x.name||x.by||'?']=1;o.dev[x.dev||'?']=1;o.ver[x.ver||'?']=1;if(o.items.length<5)o.items.push(x)});
  var list=Object.keys(g).map(function(k){return g[k]}).sort(function(a,b){return b.last-a.last});
  h+='<div class="card"><h3>'+S.errLog.length+(S.errLog.length===1?' record':' records')+' \u2022 '+list.length+(list.length===1?' kind of problem':' kinds of problem')+'</h3>'+list.map(function(o,i){var open=S.errOpen===i;
    return '<div class="errg"><button type="button" class="errh" data-act="err-open" data-i="'+i+'" aria-expanded="'+open+'"><span class="errk '+(o.kind==='crash'?'red':'amber')+'">'+(o.kind==='crash'?'Crash':'Failed')+'</span><b>'+esc(o.msg)+'</b><small>'+o.n+'\u00d7 \u2022 last '+esc(errAgo(o.last))+' \u2022 '+Object.keys(o.who).length+(Object.keys(o.who).length===1?' person':' people')+' \u2022 version '+esc(Object.keys(o.ver).join(', '))+'</small></button>'+
      (open?'<div class="erri">'+o.items.map(function(x){return '<div><b>'+esc(x.name||x.by||'?')+(x.ert?' (ERT)':'')+'</b> \u2022 '+esc(errAgo(+x.ms||0))+' \u2022 '+esc(x.dev||'')+(x.page?' \u2022 page '+esc(x.page):'')+(x.where?'<br><code>'+esc(x.where)+'</code>':'')+'</div>'}).join('')+'</div>':'')+'</div>'}).join('')+
    '<div class="actions"><button type="button" class="btn ghost" data-act="err-refresh">Refresh</button><button type="button" class="btn danger" data-act="err-clear">Clear all</button></div></div>';
  return h}
document.addEventListener('click',async function(ev){var b=ev.target.closest&&ev.target.closest('[data-act="err-open"],[data-act="err-refresh"],[data-act="err-clear"]');if(!b||!S.isOwner)return;ev.preventDefault();var a=b.dataset.act;
  if(a==='err-open'){var i=+b.dataset.i;S.errOpen=S.errOpen===i?-1:i;renderSettings();return}
  if(a==='err-refresh'){S.errLog=null;S.errFail=false;renderSettings();return}
  if(a==='err-clear'){var n=(S.errLog||[]).length;if(!n)return;if(!(await hhConfirm('',{title:'Clear the error log?',body:'All '+n+' records are deleted. New problems will still be recorded.',ok:'Clear all',cancel:'Keep them',danger:true})))return;
    var ok=0;for(var k=0;k<S.errLog.length;k++){try{await S.db.doc('errlog/'+S.errLog[k].id).delete();ok++}catch(e){}}toast(ok+' records cleared');S.errLog=null;renderSettings()}});
/* 3.12 offline bar: "Offline, showing saved data" and "Back online" */
function netInstalled(){try{return matchMedia('(display-mode: standalone)').matches||matchMedia('(display-mode: window-controls-overlay)').matches||navigator.standalone===true}catch(e){return false}}
function netHm(ms){if(!ms)return '';var d=new Date(ms);return pad(d.getHours())+':'+pad(d.getMinutes())}
function netBar(state){var b=document.getElementById('netbar');if(!b){b=document.createElement('div');b.id='netbar';b.setAttribute('role','status');b.setAttribute('aria-live','polite');document.body.appendChild(b)}
  clearTimeout(netBar._t);
  if(state==='off'){b.className='netbar off';b.innerHTML='<b>Offline</b> \u2022 showing saved data'+(S.lastData?' from '+netHm(S.lastData):'')+(netInstalled()?'. Changes are kept and sent when signal returns.':'. Saving needs signal.');b.hidden=false;document.documentElement.classList.add('is-offline')}
  else if(state==='on'){b.className='netbar on';b.innerHTML='<b>Back online</b> \u2022 updating\u2026';b.hidden=false;document.documentElement.classList.remove('is-offline');netBar._t=setTimeout(function(){b.hidden=true},3500)}
  else{b.hidden=true;document.documentElement.classList.remove('is-offline')}}
window.addEventListener('offline',function(){netBar('off')});
