/* 3.12 loading placeholders: grey outlines of what is coming, instead of empty pages or "0" */
function skelHtml(kind,n){var h='<div class="skel" aria-busy="true" aria-label="Loading">';for(var i=0;i<(n||3);i++){
  if(kind==='rows')h+='<div class="skrow"><span class="sk sk-av"></span><span class="skcol"><span class="sk sk-l" style="width:'+(55+(i*13)%30)+'%"></span><span class="sk sk-s" style="width:'+(35+(i*17)%25)+'%"></span></span></div>';
  else if(kind==='tiles')h+='<div class="sktile"><span class="sk sk-num"></span><span class="sk sk-s" style="width:70%"></span></div>';
  else h+='<div class="skcard"><span class="sk sk-s" style="width:22%"></span><span class="sk sk-l" style="width:'+(50+(i*11)%35)+'%"></span><span class="sk sk-s" style="width:38%"></span><span class="sk sk-bar"></span></div>'}
  return h+'</div>'}
