function chlogFill(){var el=document.getElementById('chlog-more');if(!el||el.dataset.done)return;el.dataset.done='1';
  fetch(el.dataset.src).then(function(r){if(!r.ok)throw 0;return r.text()}).then(function(t){if(document.body.contains(el))el.innerHTML=t}).catch(function(){if(document.body.contains(el))el.innerHTML='<div class="card"><div class="none">Earlier versions could not be loaded. Open this page again when you have signal.</div></div>'})}
/* 3.17 every date box gets a clear button (the computer's own date box has none) */
function dclrFix(){[].forEach.call(document.querySelectorAll('input[type="date"]'),function(el){
  if(el.dataset.dclr)return;el.dataset.dclr='1';
  var w=document.createElement('span');w.className='dwrap';el.parentNode.insertBefore(w,el);w.appendChild(el);
  var b=document.createElement('button');b.type='button';b.className='dclr';b.setAttribute('aria-label','Clear this date');b.title='Clear this date';b.innerHTML='\u2715';w.appendChild(b);dclrSync(el)})}
function dclrSync(el){var w=el&&el.parentNode;if(!w||!w.classList||!w.classList.contains('dwrap'))return;var b=w.querySelector('.dclr');if(b)b.hidden=!el.value||el.disabled||el.readOnly}
document.addEventListener('input',function(ev){if(ev.target&&ev.target.type==='date')dclrSync(ev.target)},true);
document.addEventListener('change',function(ev){if(ev.target&&ev.target.type==='date')dclrSync(ev.target)},true);
document.addEventListener('click',function(ev){var b=ev.target.closest&&ev.target.closest('.dclr');if(!b)return;ev.preventDefault();ev.stopPropagation();
  var el=b.parentNode.querySelector('input[type="date"]');if(!el||el.disabled||el.readOnly)return;el.value='';
  el.dispatchEvent(new Event('input',{bubbles:true}));el.dispatchEvent(new Event('change',{bubbles:true}));dclrSync(el);try{el.focus({preventScroll:true})}catch(e){}},true);
(function(){var pend=false;new MutationObserver(function(){if(pend)return;pend=true;requestAnimationFrame(function(){pend=false;dclrFix();[].forEach.call(document.querySelectorAll('.dwrap>input[type="date"]'),dclrSync)})}).observe(document.documentElement,{childList:true,subtree:true,attributes:true,attributeFilter:['disabled','readonly','value']})})();
