  if(a==='sig-open'){sigOpenDoc(t.dataset.id);return}
  if(a==='sig-pick'){var f=$('#sig-file');if(f)f.click();return}
  if(a==='sig-cam'){var c=$('#sig-camf');if(c)c.click();return}
  if(a==='sig-next'){sigReadInputs();var n=S.sigNew;if(!n||!n.bytes)return;if(n.step===1&&!n.title){toast('Give the document a name');return}n.step=Math.min(3,n.step+1);n.err='';renderSettings();$('#setsheet').scrollTop=0;return}
