  if(a==='sig-mail'||a==='sig-wa'||a==='sig-copy'){sigShare(a.slice(4),t.dataset.id||S.sigCur);if(a!=='sig-copy'&&t.dataset.id)return;if(a!=='sig-copy'&&S.sigCur){try{var r0=sigCur();if(r0&&(r0.status==='sent'||r0.status==='opened'))S.db.collection('signreq').doc(r0.id).update({resentAt:firebase.firestore.FieldValue.serverTimestamp()}).catch(function(){})}catch(e){}}return}
  if(a==='sig-dl'){sigDownload('signed');return}
