/* Version 10.0: permission ticks. Owner and Executives have everything; Admins have what an Executive ticked. */
async function pinSave(){
  if(!pinCanManage()||!S.db){toast('Only an Executive can manage the App Lock');return}
  var a=($('#pin-new')||{}).value||'',b=($('#pin-new2')||{}).value||'';
  if(!/^\d{4,8}$/.test(a)){toast('Use 4 to 8 digits');return}
  if(a!==b){toast('The two PINs do not match');return}
  var salt=Array.from(crypto.getRandomValues(new Uint8Array(8))).map(function(x){return x.toString(16).padStart(2,'0')}).join('');
  var hx=await pinHash(salt,a);
  var now=new Date().toISOString(),action=S.pin?'changed':'set';
  try{await S.db.doc('config/auth').set({enabled:true,salt:salt,hash:hx,updated:now,updatedBy:pinActor(),ownerAction:!!S.isOwner,action:action,idleMin:S.pinIdle});S.unlocked=true;try{sessionStorage.setItem('ert_unlock',now)}catch(e){}renderHome();settingsBackAfterSave();toast(action==='changed'?'PIN changed':'PIN set')}
  catch(e){toast('Could not save the PIN. Try again.')}
}
async function pinRemove(){ if(!pinCanManage()||!S.db){toast('Only an Executive can manage the App Lock');return} if(!(await hhConfirm('',{title:'Remove the App Lock PIN?',body:'The app stops asking for a PIN on every phone and computer until someone sets a new one.',ok:'Remove PIN',cancel:'Keep it',danger:true})))return;
  var now=new Date().toISOString();
  try{await S.db.doc('config/auth').set({enabled:false,salt:'',hash:'',updated:now,updatedBy:pinActor(),ownerAction:!!S.isOwner,action:'removed',idleMin:S.pinIdle});S.unlocked=true;try{sessionStorage.removeItem('ert_unlock')}catch(e){}renderHome();if(S.set)renderSettings();toast('PIN removed')}
  catch(e){toast('Could not remove the PIN. Try again.')}
}
function lockSettingsHtml(){
  var w=pinCanManage(),idl=S.pinIdle>0?S.pinIdle+' minutes':'off',status=S.pin?'A PIN is active. Executives, Admins and Staff must enter it when opening a new app session, when they come back to the app, and after '+(S.pinIdle>0?S.pinIdle+' minutes without use':'being away for 5 minutes')+'.':'No App Lock PIN is active.';
  status+=' Authorized leadership can set, change or remove it. Changing the PIN invalidates unlock sessions created with the previous PIN.';
  var audit=S.pinAudit&&S.pinAudit.updated&&!ownerAudit(S.pinAudit)?'<div class="none" style="margin-top:12px">Last '+(S.pinAudit.action==='removed'?'removed':'changed')+' '+esc(String(S.pinAudit.updated).replace('T',' ').replace(/\.\d+Z$/,' UTC'))+' by '+esc(whoLabel(S.pinAudit.updatedBy,'authorized leadership'))+'.</div>':'';
  return '<div class="card" id="sec-lock"><h3>App lock</h3><div class="sethead"><span class="grow">'+status+' The actual PIN is never stored or displayed.</span></div>'+audit+
    (w?'<div class="f"><label for="pin-new">'+(S.pin?'New PIN':'PIN')+' (4 to 8 digits)</label><input id="pin-new" type="password" inputmode="numeric" maxlength="8" autocomplete="off"></div><div class="f"><label for="pin-new2">Repeat the PIN</label><input id="pin-new2" type="password" inputmode="numeric" maxlength="8" autocomplete="off"></div><div class="actions"><button class="btn" data-act="pin-save">'+(S.pin?'Change PIN':'Set PIN')+'</button>'+(S.pin?'<button class="btn ghost" data-act="pin-remove">Remove PIN</button>':'')+'</div>'+'<div class="f"><label for="pin-idle">Lock again after no use</label><select id="pin-idle" data-pinidle="1">'+[[5,'5 minutes (default)'],[15,'15 minutes'],[30,'30 minutes'],[0,'Off (only when the app is left)']].map(function(o){return '<option value="'+o[0]+'"'+(S.pinIdle===o[0]?' selected':'')+'>'+o[1]+'</option>'}).join('')+'</select></div>':'<div class="none">You can view the App Lock status, but you cannot change it. Lock again after no use: '+idl+'.</div>')+'</div>';
}

