function dangerZoneHtml(){
  return '<div class="card dzwarn"><h3>\u26A0 Read this first</h3><div class="none">These tools permanently change or delete data for everyone. They are meant for clearing test data, not for day-to-day work.</div><ul class="nmlist" style="margin:0 14px 12px"><li>A full backup file is saved to this device <b>before</b> anything changes. If it cannot be saved, nothing happens.</li><li>Each action asks for <b>three confirmations</b>.</li><li>Deleted items cannot be brought back except by restoring that backup.</li></ul></div>'+
    '<details class="card dzbox"'+(S.dzOpen?' open':'')+' data-dz="1"><summary>Show the tools</summary>'+ownerMaintenanceHtml()+'</details>';
}

async function deleteDocs(col,docs){
  var ix=0,fail=0;
  async function worker(){while(ix<docs.length){var d=docs[ix++];try{await S.db.doc(col+'/'+d.id).delete()}catch(e){fail++}}}
  await Promise.all([worker(),worker(),worker(),worker(),worker()]);return fail;
}



 
