var TK_ASSIGN=[['TEAM LEAD',/lead|supervis|team/i],['PARAMEDIC',/param|medic|emt/i],['BA OPERATOR',/\bba\b|breathing|cart/i],['AGT',/\bagt\b|gas\s*test/i],['CSA',/\bcsa\b|confined/i],['FIRE WATCH',/fire\s*watch|\bfw\b/i]];
function repLooksCombined(n){return splitRepNames(n).length>1||nameTokens2(n).length>=4}
function repOptionsHtml(read,client){
  var list=savedReps(client),people=splitRepNames(read),single=list.filter(function(r){return !repLooksCombined(r.n)}),used={},level='',opts=[];
  if(!people.length&&read)people=[String(read).trim()];
  people.forEach(function(p){
    var best=null,bs=0;single.forEach(function(r){var sc=nameScore(p,r.n);if(sc>bs){bs=sc;best=r}});
    if(best&&bs>=0.75&&!used[best.n]){used[best.n]=1;if(bs<0.9)level='check';opts.push({v:best.n,l:best.n.toUpperCase()+' (saved'+(bs<0.9?', read as '+p.toUpperCase():'')+')'})}
    else opts.push({v:p,l:p.toUpperCase()+' (new)'});
  });
  var combined=people.length>1?list.filter(function(r){return repLooksCombined(r.n)&&nameScore(people.join(' '),r.n.replace(/[\/&,+]/g,' '))>=0.7}).map(function(r){return r.n}):[];
  var html=(opts.length?'<optgroup label="Read on the paper">'+opts.map(function(o,i){return '<option value="'+esc(o.v)+'"'+(i===0?' selected':'')+'>'+esc(o.l)+'</option>'}).join('')+(opts.length>1?'<option value="'+esc(opts.map(function(o){return o.v}).join(' / '))+'">Both: '+esc(opts.map(function(o){return o.v.toUpperCase()}).join(' / '))+'</option>':'')+'</optgroup>':'');
  var rest=single.filter(function(r){return !used[r.n]});
  if(rest.length)html+='<optgroup label="Other saved reps">'+rest.map(function(r){return '<option value="'+esc(r.n)+'">'+esc(r.n.toUpperCase())+'</option>'}).join('')+'</optgroup>';
  return {pick:opts.length?opts[0].v:'',level:level,html:html,people:people,combined:combined,multi:people.length>1};
}





