function sameArea(a,b){return (String(a).indexOf('Atlantic')>-1)===(String(b).indexOf('Atlantic')>-1)}
function matchLine(m){
  var p=[m.n+' of '+Math.max(m.memN,m.paperN)+' names match'];
  p.push(m.shiftOk?m.c.shift+' shift matches':'Shift differs (rostered '+m.c.shift.toLowerCase()+')');
  if(!m.cm)p.push('client differs');
  if(m.veh==='match')p.push('vehicle matches');else if(m.veh==='differs')p.push('different vehicle');
  if(m.unit)p.push('unit matches');
  return p.join(' \u2022 ');
}
 
 
