function applyErc(d){setTimeout(function(){if(typeof ertSyncSoon==='function')ertSyncSoon()},0);
  var base=JSON.parse(JSON.stringify(DEF_ERC));
  var legacy=(d&&Array.isArray(d.rates)&&d.rates.length)?d.rates:base.rates;
  if(d&&Array.isArray(d.clients))base.clients=d.clients.map(function(c){var x=JSON.parse(JSON.stringify(c)),old=!(d&&d.rateModel>=2),oldRules=!(d&&d.rateModel>=3),name=String(x.n||'').toUpperCase(),atl=name==='ATLANTIC';if(old&&atl&&Array.isArray(x.rates))x.rates.forEach(function(r){if(r.lead==null&&r.base!=null)r.lead=r.base});if(old&&!atl&&Array.isArray(x.rates)&&x.rates.length&&x.rates.every(function(r){var z=legacy.filter(function(q){return +q.y===+r.y})[0];return z&&+r.base===+z.ert&&+r.lead===+z.lead}))x.rates=[];if(oldRules&&name==='PLNL'&&(x.profile==='standard'||JSON.stringify(cleanPayRules(x.rules,legacyStandardPayRules(12)))===JSON.stringify(legacyStandardPayRules(12)))){x.profile='plnl';x.rules=plnlPayRules()}else if(oldRules&&x.profile==='standard'){x.rules=standardPayRules()}return normalClient(x,legacy)});
  base.yard=Object.assign({},(typeof DEF_YARD!=='undefined'?DEF_YARD:{}),(d&&d.yard)||{});if(base.yard.start==='07:45'&&base.yard.end==='16:00'){base.yard.start='08:00';base.yard.end='16:30'}if(base.yard.lunch==null)base.yard.lunch=0.5;
  base.offshore=Object.assign({day:1000,hol:2000},(d&&d.offshore)||{});
  base.ertShowPay=!(d&&d.ertShowPay===false);
  base.allow=(d&&d.allow&&typeof d.allow==='object')?JSON.parse(JSON.stringify(d.allow)):{};
  base.presets=(d&&Array.isArray(d.presets))?d.presets.filter(function(x){return x&&x.id&&x.n}).map(function(x){return {id:String(x.id),n:String(x.n).trim(),rules:cleanPayRules(x.rules,standardPayRules())}}):[];
  if(!(d&&d.rateModel>=5)){var oldAtl=JSON.stringify(cleanPayRules(legacyAtlanticPayRules())),newAtl=atlanticPayRules();base.clients.forEach(function(c){if(JSON.stringify(c.rules)===oldAtl)c.rules=JSON.parse(JSON.stringify(newAtl))})}
  base.builtinRules={};if(d&&d.builtinRules&&typeof d.builtinRules==='object')['standard','plnl','atlantic'].forEach(function(k){if(d.builtinRules[k])base.builtinRules[k]=cleanPayRules(d.builtinRules[k],factoryPresetRules(k))});if(!(d&&d.rateModel>=5)&&base.builtinRules.atlantic&&JSON.stringify(base.builtinRules.atlantic)===JSON.stringify(cleanPayRules(legacyAtlanticPayRules())))delete base.builtinRules.atlantic;
  base.links={};if(d&&d.links&&typeof d.links==='object')Object.keys(d.links).forEach(function(k){if(typeof d.links[k]==='string'&&d.links[k])base.links[k]=d.links[k]});
  base.disabled=(d&&Array.isArray(d.disabled))?d.disabled.filter(function(x){return x&&x.id&&x.n}).map(function(x){return {id:String(x.id),n:String(x.n).trim().toUpperCase(),site:String(x.site||''),at:String(x.at||''),by:String(x.by||'')}}):[];
  if(!base.clients.some(function(c){return c.n==='ATLANTIC'})&&!base.disabled.some(function(x){return x.n==='ATLANTIC'}))base.clients.push(normalClient({n:'ATLANTIC',site:'ATLANTIC',meal:0,min:0,profile:'atlantic'},legacy));
  if(d&&Array.isArray(d.holidays))base.holidays=d.holidays.filter(function(x){return x&&isDate(x.d)}).map(function(x){return {d:x.d,n:String(x.n||'')}});
  if(d&&Array.isArray(d.rates)&&d.rates.length)base.rates=d.rates.map(function(r){return {y:+r.y||2026,ert:+r.ert||0,lead:+r.lead||0,atl:(r.atl==null?69.09:Math.max(0,+r.atl||0))}});
  var currentDefault=yearRate(base.rates,new Date().getFullYear())||{ert:60,lead:65};
  base.defaultErt=d&&d.defaultErt!=null?Math.max(0,+d.defaultErt||0):(+currentDefault.ert||0);
  base.defaultLead=d&&d.defaultLead!=null?Math.max(0,+d.defaultLead||0):(currentDefault.lead==null?+currentDefault.ert||0:+currentDefault.lead||0);
  S.erc=base; S.erc.lastMoneyChange=(d&&d.lastMoneyChange)||null; try{S.ercBase=JSON.parse(JSON.stringify(S.erc))}catch(e){S.ercBase=null} S.ercLoaded=true;
  if(S.whdocs&&S.whdocs.length)rebuildWorkHours();
  if(S.set)renderSettings();
  renderErLog();
  ensurePaySnapshots();
}
 
 
 
 
 
 
async function afterLocationRename(lid,oldN,newN,moved){
  if(!S.canRates){if(S.ercLoaded&&locRateStatus({id:lid,name:oldN,alt:''}).c)toast('Renamed. Someone with Rates access can rename or relink its Rates site.');return}
  if(!S.ercLoaded||!S.db)return;
  if(!S.erc.links)S.erc.links={};
  var st=locRateStatus({id:lid,name:oldN,alt:''});
  if(!st.c){if(moved)await saveErc();return}
  S.erc.links[lid]=st.c.id;
  var renamed=false,clash=S.erc.clients.some(function(x){return x!==st.c&&x.n===newN});
  if(oldN!==newN&&st.c.n===oldN&&!clash&&(await hhConfirm('Also rename the linked Rates site '+oldN+' to '+newN+'?\n\nIts rates, pay rules, meal break, minimum hours and work-hours name stay the same. Existing jobs and tickets keep their locked settings.\n\nChoose Cancel to keep the Rates name. The location and Rates site stay linked either way.',{ok:'Rename it too',cancel:'Keep the old name',icon:'info'}))){st.c.n=newN;renamed=true}
  var ok=await saveErc();
  if(!ok){if(renamed)st.c.n=oldN;return}
  renderSettings();if(renamed)toast('Rates site renamed to '+newN);
}
function isHoliday(day){return S.erc.holidays.some(function(x){return x.d===day})}
var LEAD_ROLES=['TEAM LEAD'];
function rowWeighted(r){var t=r.tx||[];return (+t[0]||0)+(+t[1]||0)*1.5+(+t[2]||0)*2+(+t[3]||0)*3}
function rowPay(r,day,client){if(client&&client.offshore){var o=offshoreCfg();return (r&&(r.pid||r.name))?(isHoliday(day)?+o.hol||0:+o.day||0):0}return rowWeighted(r)*rateFor(day,(r.leadRate||isLeadRole(r.role)||(r.pid&&allowAt(r.pid,day).lead))?'TEAM LEAD':r.role,client)}
