/* 3.47 ticket view page: tapping a ticket shows everything read-only; Edit ticket opens the form */
async function saveTicket(){
  collectTicket();var t=S.ert;if(!t)return;
  if(!t.doc.date){toast('Enter the ticket date');return}
  if(!t.doc.client){toast('Enter the client');return}
  if(!t.doc.paySnapshot)t.doc.paySnapshot=makePaySnapshot(t.doc.client,t.doc.date,true);
  var old=(S.erlog||[]).filter(function(x){return x.id===t.id})[0]||{},was=old.status==='SIGNED',now=t.doc.status==='SIGNED';
  var mClosed=!!old.id&&(monthClosed(old.month)||monthClosed(t.doc.month));
  if(old.id&&(was||mClosed)){
    if(!hp('erLock')){toast(mClosed?monLabel(old.month||t.doc.month)+' is closed. You need the \u201CER Log month locks and ticket numbering\u201D permission to change it.':'This ticket is signed. You need the \u201CER Log month locks and ticket numbering\u201D permission to correct it.');return}
    var why=askReason((mClosed?'This month is closed (after payroll). ':'This ticket is signed. ')+'Reason for the change (required):');if(!why)return;
    t.doc.corrections=(old.corrections||[]).concat([{at:new Date().toISOString(),by:actorName(),reason:why,afterPayroll:mClosed}]).slice(-30);
  }
  if(!old.id&&monthClosed(t.doc.month))t.doc.latePayroll=true;
  if(!old.id&&now&&monthClosed(t.doc.month)&&!hp('erLock')){t.doc.status='UNSIGNED';renderTicket();toast(monLabel(t.doc.month)+' is closed. Save this ticket unsigned; someone with the month-lock permission can then sign it.');return}
  if(now&&!was&&erFutureSign(t.doc)){toast(erFutureMsg(t.doc));t.doc.status='UNSIGNED';renderTicket();return}
  if(now&&!was){var signing=Object.assign({id:t.id},t.doc);if(!(await confirmTicketSign(signing))){t.doc.status='UNSIGNED';renderTicket();return}if(signing.duplicateOverride)t.doc.duplicateOverride=signing.duplicateOverride;t.doc.signedAt=new Date().toISOString();t.doc.signedBy=actorName()}
  if(!now&&was&&!(await hhConfirm(unsignWarning(),{ok:'Unsign',icon:'warn'}))){t.doc.status='SIGNED';renderTicket();return}
  if(!now&&was){t.doc.unsignedAt=new Date().toISOString();t.doc.unsignedBy=actorName()}
  if(!old.id&&!t.doc.created){t.doc.created=new Date().toISOString();t.doc.createdBy=actorName()}
  var ok=await saveErDoc(Object.assign({id:t.id},t.doc));
  if(ok){if(now)await postSignedHours(Object.assign({id:t.id},t.doc));saveRep(t.doc.client,t.doc.rep);(t.doc.repsRead||[]).forEach(function(n){var sel0=(savedReps(t.doc.client).filter(function(r){return !repLooksCombined(r.n)&&nameScore(n,r.n)>=0.9})[0]);if(!sel0)saveRep(t.doc.client,n)});if(t.doc.jobId&&t.doc.linked==='scan'){var sdoc=Object.assign({id:t.id},t.doc),six=(S.erlog||[]).findIndex(function(x){return x.id===t.id});if(six>-1)S.erlog[six]=sdoc;else S.erlog.push(sdoc);syncJobFromTickets(t.doc.jobId)}toast('Ticket saved');S.erm=t.doc.month;S.era=erAreaOf(t.doc);if(S.ert===t){t.view=true;t.isNew=false;t.base=null;t.discardArm=false;delete t.dupId;renderTicket();$('#logsheet').scrollTop=0}else closeTicket()}
}
 
