function dlTsMatch(q){var ws=String(q||'').toLowerCase().split(/\s+/).filter(Boolean);return (S.people||[]).filter(function(p){var n=String(p.name||'').toLowerCase();return ws.every(function(w){return n.indexOf(w)>-1})}).sort(function(a,b){function rk(p){var n=' '+String(p.name||'').toLowerCase();return ws.length&&n.indexOf(' '+ws[0])<0?1:0}return rk(a)-rk(b)||a.name.localeCompare(b.name)})}
