  var nm=o.filename||'file',blob=o.data instanceof Blob?o.data:new Blob([o.data]),ext=(/\.([a-z0-9]+)$/i.exec(nm)||[])[1];ext=(ext||'').toLowerCase();
  openFileViewer({title:nm,onDownload:onDownload,onClose:onClose,html:'<div class="none" style="padding:20px">Opening\u2026</div>'});
